window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_027"]={"n":"徐渭","dyn":"明","poems":[{"t":"王元章倒枝梅画","f":"七言绝句","c":["皓态孤芳压俗姿，不堪复写拂云枝。","从来万事嫌高格，莫怪梅花著地垂。"]},{"t":"兰","f":"七言绝句","c":["莫讶春光不属侬，一香巳足压千红。","总令摘向韩娘袖，不作人间脑麝风。"]},{"t":"醉人","f":"七言绝句","c":["不去奔波办过年，终朝酩酊步颠连。","几声街爆轰难醒，那怕人来索酒钱。"]},{"t":"题画梅 其二","f":"七言绝句","c":["从来不见梅花谱，信手拈来自有神。","不信试看千万树，东风吹著便成春。"]},{"t":"葡萄 其一","f":"七言绝句","c":["半生落魄巳成翁，独立书斋啸晚风。","笔底明珠无处卖，閒抛閒掷野藤中。"]},{"t":"乙丑元日大雪自饮至醉遂呼王山人过尚志家痛饮夜归复浮白于园中","f":"七言律诗","c":["元日独酌不成酡，穿邻唤客雪中过。","三百六旬又过矣，四十五春如老何。","帻软渐知簪发少，兴豪那计酒筹多。","小园风景偏宜雪，缀柳妆梅有许窠。"]},{"t":"岁暮夜雪招二王诗人菲果小饮","f":"七言律诗","c":["斗酒那能不醉休，醉来可使不歌不？","黄金虽我无颜色，秋水还谁辨马牛？","笑插落梅花乱鬓，起看城雪筋冰楼。","一角忽风天尽黑，万鸦抟雨下枝头。"]},{"t":"柳桥不知谁氏园旧有梨树六株花甚盛余每当月夜坐观移时拟买之屋而扁曰香雪园今归谁氏梨且斫尽矣","f":"七言律诗","c":["六树梨花打百毬，昔年曾记柳桥头。","娇来靥靥西施粉，冷伴年年燕子楼。","不受三郎催羯鼓，好当一梦入罗浮。","今来斫尽谁家圃，辜负山人扁额休。"]},{"t":"酒三品","f":"五言律诗","c":["小瓮五双盏，千蚨五瓮香。","无钱长买醉，有客偶携将。","酝藉宜高价，淋漓想故乡。","狭斜垆不少，今夜是谁当。"]},{"t":"与言君饮酒","f":"七言古诗","c":["今日与君饮一斗，卧龙山下人屠狗。","雨歇苍鹰唤晚晴，浅草黄芽寒兔走。","酒深耳热白日斛，笔满心雄不停手。"]},{"t":"为郑先生题画四首值大醉 其三 群牛渡水无牧人","f":"七言绝句","c":["春雨潇潇醉酒尊，何人命咏牧图浑。","溪寒月落牛自渡，老牧醉眠何处村。"]},{"t":"兰亭次韵","f":"七言律诗","c":["长堤高柳带平沙，无处春来不酒家。","野外光风偏拂马，市门残帖解开花。","新觞曲引诸溪水，旧寺岩垂几树茶。","回首永和如昨日，不堪怅望晚天霞。"]},{"t":"竹","f":"七言绝句","c":["一斗醉来将落日，胸中奇突有千尺。","急索吴笺何太忙，兔起鹘落迟不得。"]},{"t":"酒徒","f":"五言古诗","c":["御史别淳于，金钗堕长夜。","五斗不湿唇，双鬟抱垆泻。","笑杀斗升肠，耳热索竿蔗。"]},{"t":"龛山凯歌六首（为吴县史鼎庵） 其一","f":"七言绝句","c":["短剑随枪暮合围，寒风吹血着人飞。","朝来道上看归骑，一片红冰冷铁衣。"]},{"t":"赋得酒卮中有好花枝","f":"五言律诗","c":["虽云辞树底，犹得映杯中。","带叶蚁分绿，临妆脸并红。","传时香觉迩，覆处影方空。","若使玻璃杯，楼台浸几重。"]},{"t":"频婆","f":"五言律诗","c":["石密偷将结，他鸡伏不成。","千林黄鹄卵，一市楚江萍。","旨夺秋厨腊，鲜专夏盌冰。","上元灯火节，一颗百钱青。"]},{"t":"渔家四图四首","f":"古风","c":["渔伴网鱼换酒，渔妇把酒斟翁。","邻舍不离水上，对斟只在波中。"]},{"t":"与杨子完步浣纱溪梁有怀西施之乡","f":"五言古诗","c":["明月照江水，截梁与子步。","当时如花人，曾此照铅素。","江流不改易，月亦无新故。","薄云淡杪林，晴沙泛寒露。","借言伊人闺，应在烟生处。"]},{"t":"泛舟九曲","f":"五言古诗","c":["老王乱青冥，皇天夜遗蜕。","馀骨散九州，头颅此焉寄。","人视万劫馀，天意一夕计。","游艇沸沧波，髣髴热营卫。","亭午入数折，冲然元气闭。","县峰升羽人，毛竹倚仙姊。","辟彼齿牙蠹，生死龈腭内。","世人不解奇，但识世间事。","示之帝所遗，惟以溪山睇。"]},{"t":"丙辰八月十七日与肖甫侍师季长沙公阅龛山战地遂登冈背观潮","f":"五言古诗","c":["白日午未倾，野火烧青昊。","蝇母识残腥，寒唇聚秋草。","海门不可测，练气白于捣。","望之远若迟，少焉忽如扫。","阴风噫大块，冷艳拦长岛。","怪沫一何繁，水与水相澡。","玩弄狎鬼神，去来准昏晓。","何地无恢奇，焉能尽搜讨。"]},{"t":"沈参军（青霞）","f":"五言古诗","c":["参军青云士，直节凌邃古。","伏阙两上书，裸裳三弄鼓。","万乘急宵衣，当廷策强虏。","借剑师傅惊，骂座丞相怒。","遗帼辱帅臣，筹边著词赋。","截身东市头，名成死谁顾。"]},{"t":"入燕","f":"五言古诗","c":["董生抱利器，郁郁走燕赵。","贱子亦何能，飘然来远道。","行止本无常，譬彼云中鸟。","朝饮西园池，暮宿北林杪。","感事复怀人，生年苦不早。","欲吊望诸君，迹陈知者少。","垂首默无言，春风秀芳草。"]},{"t":"入燕三首 其二","f":"五言古诗","c":["荆卿本豪士，渐离亦高流。","舞阳虽少小，杀人如芟苗。","眇然三匹夫，挟燕与秦仇。","悲歌酒后发，涕下不能收。","猛气惊俗胆，奇节招世尤。","见者徒骇顾，那能谅其由。","我生千载后，缅兹如有投。","时违动自妄，忽作燕京游。","短褐入沽肆，酒至思若抽。","念彼屠与贩，零落归山丘。","皇皇盛明世，六辔控九州。","七首蚀野土，广道鸣华釐。","寸规不可越，安用轲之俦。","我思远及之，旷若林与鹙。","凤鸟不可得，苍鹰以为求。"]},{"t":"入燕三首 其三","f":"五言古诗","c":["大鹏奋南徙，岂为北海笼。","越鸟不逾南，见与胡马同。","自愧无垂云，抟彼沧溟风。","犹能胜鸲鹆，与济相始终。","上林多乔枝，万羽亦足容。","匝树绕不栖，翻附南飞鸿。","春冬递迁谢，倏忽两月中。","卧席不得暖，来往何憧憧。"]},{"t":"刈圃","f":"五言古诗","c":["草孽始一寸，及壮丈有馀。","岂直薮即带，兼以馆蚊胥。","夜热不可寐，宁止不露居。","窃恐值此辈，股髀遭其咀。","就中拟厥罪，蚊也尤其渠。","其他不出境，惟此远追趋。","穿帏眇纨麈，打扑不胜劬。","更番以迭进，安得尽屠诛。","聚响苦不震，万鷇啾婴雏。","工者搅梦寐，一夕百起呼。","蚊孽固莫逭，草实主其逋。","呼童问腰镰，不用安所须。","薙此忽如扫，一翅不得储。","譬彼塞垣莽，往往伏戎胡。","打冰烧其荒，窟穴空妖狐。","莫谓野人贱，刈圃非雄图。"]},{"t":"白鹇","f":"古风","c":["野性悦鸟鱼，客寓尚笼致。","正如好竹人，借居亦栽莳。","鹇鸟自南来，贸入西河里。","王孙好法书，笼以易吾字。","墨丝绣雪衣，绿?作裆帔。","有时啭喉中，鷕若袅云际。","日夕湖水波，秋树叶微紫。","送客不出门，白玉扫长彗。"]},{"t":"越王峥寺有僧欧兜蜕","f":"五言律诗","c":["伯图既灰寒，衲蜕亦禅冷。","都付塑工泥，迅矣千秋瞬。","我来值桃花，有似蝶遗粉。","一宿归去来，晨斋饱蔬笋。"]},{"t":"柳元谷以所得晋太康间冢中杯及瓦券来易余手绘二首 其一","f":"五言古诗","c":["遥思冢中人，有杯不能饮。","孤此黄兔窑，伴千三百稔。","券镪四百万，买地作衾枕。","想当不死时，用物必弘甚。","尊垒罗宝玉，裹袜贱绣锦。","岂有纤纤指，捧此锻泥蕈。","存亡隔一丘，华寂迥千仞。","活鼠胜死王，斯言岂不审。"]},{"t":"柳元谷以所得晋太康间冢中杯及瓦券来易余手绘二首 其二","f":"五言古诗","c":["古人笑不饮，此说岂无见。","五斗叫刘伶，哀来泪如霰。","嗟彼太康子，冢中亦杯坫。","固知好饮徒，无咽可浇咽。","杯出黄土中，忽复受倾灌。","譬彼避秦人，乃不知有汉。","我欲学卢充，诣市卖金盌。","庶几遇小姨，知是崔氏玩。"]},{"t":"送兰公子","f":"五言律诗","c":["耶溪芹藻色，相伴秋荷老。","公子朅重来，伤心那可道。","会日苦无多，相别一何早。","八月广陵涛，一叶渡残照。"]},{"t":"燕子矶观音阁","f":"五言古诗","c":["青山如美人，楼观即奁妆。","若无一片镜，妙丽苦不昌。","兹石一何幸，值此江中央。","上乘巨搆支，下集帆与樯。","朱碧得水鲜，凫雁拂波光。","烟雾不见海，神去万里长。","我与三友俱，兼以僮仆双。","日西买市饭，半道谢驴缰。","五口将十足，蹶然馁且僵。","百钱成一游，安得甘旨尝。","归来乏灯烛，微雨沾我裳。","沽酒不成醉，颓然倒方床。","犹梦立阁中，遥观大鱼翔。"]},{"t":"野火","f":"五言古诗","c":["马血为转燐，人血为野火。","何为松柏间，赤轮陟如跛。","人言鬼炬微，神者赤而大。","驺导向空驰，填云盛旗马。","枯冢僻且荒，来游则云那。","我欲往询之，恐即无可话。","隔河闻于菟，黄犊夜在野。","一夫呼以驰，炬灭松露泻。"]},{"t":"治冢二首 其二","f":"五言古诗","c":["明器夜为人，幽宫尽婚婿。","此事容有之，要非是常纪。","尝闻掘冢徒，自言习见鬼。","齿骨满百年，比次作泥委。","水银筑长河，鱼膏灯玉几。","苦作沙丘仪，未免劫时毁。","客有明月珠，一夕失所在。","黄金饰椟箱，洵美亦何济。"]},{"t":"侠客","f":"五言古诗","c":["结客少年场，意气何扬扬。","燕尾茨菰箭，柳叶梨花枪。","为吊侯生墓，骑驴入大梁。"]},{"t":"道坚母哀词","f":"五言古诗","c":["道坚母在时，随我游五泄。","适当大雪辰，衣湿不能热。","道坚解衣我，絮厚百铢绵。","云是母氏慈，每出必纫缀。","有妇非不勤，母自嗜据拮。","去此不五春，母与子长别。","子来属哀篇，忽值天雨雪。","春候思桑条，秋至感鸣祼。","念昔湿衣裳，命管忘好拙。"]},{"t":"送刘君","f":"五言律诗","c":["南雁正北归，君今复南去。","羽族如避炎，君胡故触暑。","嗟哉失路人，安所避辛苦。","而我亦同之，临歧泪如雨。"]},{"t":"上冢","f":"五言古诗","c":["吾叔邵武公，当年与我翁。","双陪闽蜀守，竹马走儿童。","归来知几日，相继归窀穸。","黄泥闭雪髭，欲会那可得。","叔家城北居，高栋亦彫题。","邀宾夕驻马，为母日烹鸡。","一朝桑海换，不能保子孙。","负薪冢上道，养鸭水边村。","我今六十五，仍高破角巾。","年年上爷冢，每每到孙家。","孙家留我坐，孙妇办汤茶。","以我上冢牲，啖孙且满引。","绕篱黄蝶飞，抽篱高碧笋。","起视檐西东，分檐住蜜蜂。","问蜂窠几许，四十还有馀。","窠窠如不败，胜我十亩租。"]},{"t":"往马水口宿烟麓陀庵","f":"五言古诗","c":["昔从良涿行，兹山在云际。","昨夕宿兹山，云乃出衣袂。","四徒夹一舆，两膝拳至鼻。","一里转百盘，锯牙不得直。","结苇以为庐，削木冒金髻。","夜钟但超悬，晨鸡聊一嘒。","巉岩既高骞，巑岏复孤厉。","回思燕赵时，筑城遏胡骑。","安得尽如斯，脱甲开户寐。"]},{"t":"阴风吹火篇呈钱刑部君附书（八山）","f":"七言古诗","c":["阴风吹火火欲燃，老枭夜啸白昼眠。","山头月出狐狸去，竹径归来天未曙。","黑松密处秋萤雨，烟里闻声辨乡语。","有身无首知是谁，寒风莫射刀伤处。","关门悬纛稀行旅，半是生人半是鬼。","犹道能言似昨时，白日牵人说兵事。","高幡影卧西陵渡，召鬼不至毗卢怒。","大江流水枉隔侬，冯将咒力攀浓雾。","中流灯火密如萤，饥魂未食阴风鸣。","髑髅避月攫残黍，幡底飒然人发竖。","谁言堕地永为厉，宰官功德不可议。"]},{"t":"杨妃春睡图","f":"七言古诗","c":["守宫夜落胭脂臂，玉阶草色蜻蜓醉。","花气随风出御墙，无人知道杨妃睡。","皂纱帐底绛罗委，一团红玉沉秋水。","画里犹能动世人，何怪当年走天子。","欲呼与语不得起，走向西屏打鹦鹉。","为问华清日影斜，梦里曾飞何处雨？"]},{"t":"射雁篇赠朱生","f":"七言古诗","c":["去年射雁黄浦口，三军进酒齐为寿。","今年射雁复何处，海舶停沙大桅竖。","君本临洮豪杰士，汉时六郡良家子。","作客羞为堂下人，射生惯落云中羽。","腰间束夭插两房，连年驱贼如驱羊。","辕门待士近不薄，朝来归兴何洋洋。","丈夫有遇有不遇，去留之间向谁语？"]},{"t":"八月十五日映江楼潮次黄户部","f":"七言律诗","c":["鱼鳞金甲屯牙帐，翻身却指潮头上。","秋风吹雪下江门，万里琼花捲层浪。","传道吴王度越时，三千强弩射潮低。","今朝筵上看传令，暂放胥涛掣水犀。"]},{"t":"寄吴宣镇","f":"五言古诗","c":["髯公本儒者，而有燕颔姿。","一朝秉元戎，虏马不敢嘶。","赫赫百年内，举筹不数枚。","大易称神武，岂在多伤夷。","明主见万里，何况数驿驰。","白壁本不瑕，青蝇亦何为。","昨闻敕尚方，作貂缀冠禔。","插羽高尺五，庸以华勋题。","愿君秉忠谅，以答鼓鼙思。"]},{"t":"述梦 其一","f":"古风","c":["伯劳打始开，燕子留不住。","今夕梦中来，何似当初不飞去。","怜羁雄，嗤恶侣。","两意茫茫坠晓烟，门外乌啼泪如雨。"]},{"t":"二马行","f":"七言古诗","c":["谁家两奴骑两骢，谁是主人云姓宗。","朝来暮去夹街树，经过烟雾如游龙。","问马何由得如此，淮安大豆清泉水。","胸排两岳横难羁，尾撒圆毬骄欲死。","阳春三月杨柳飞，骑者何人看者稀。","梅花银钉革带肥，京城高帽细褶衣。","马厌豢养人有威，出入顾盼生光辉。","去年防秋古北口，劲风吹马马逆走。","对垒终宵不解鞍，食粟连朝不盈斗。","将军见虏饱掠归，据鞍作势呼贼走。","士卒久矣知此意，打马追奔仅得彀。","天寒马毛腹无矢，饥肠霍霍鸣数里。","不知此处踏香泥，一路春风坐罗绮。"]},{"t":"观猎篇","f":"古风","c":["茅刀割水娇红茜，风偃寒梢卧长堰。","青林疏树隔荒坟，白水茫茫看不见。","将军本是北平豪，记得依稀身姓曹。","怕向扬州作贵客，惯从下泽骤鸣镳。","万里秋郊平似舸，千骑围中一是我。","箭叫饿鸱，龙腾快马。","趁鹿逐獐，解绦掣锁。","耳后生风，鼻头出火。","自来此州，杀贼不暇。","皂雕气销，韩卢魄堕。","昨见儒生，衣长履大。","入揖令公，挥金不谢。","抽笔制词，弯弓辄射。","住释挟屠，刳牛食鲊。","外枯中腴，无所不可。","促骑请邀，徵徒出野。","牵犬莫迟，见兔辄打。","傥遇大兕，一发断髁。","为先生寿，引满十斝。","健儿跪领将军言，翻身上马去如烟。","宝刀映日不足数，角巾受风真可怜。","浅草平堤水痕聚，万蹄避水移家去。","沙拥肥螯掠岸飞，丝牵小豸当空乳。","汉将穷追路欲阑，胡家瓯脱避何难。","今朝立马祁连上，不见匈奴一骑还。"]},{"t":"画鹰","f":"七言古诗","c":["闽南缟练光浮腻，传真谁写苍厓鸷。","生相由来不附人，绿韝空著将军臂。","八月九月原草稀，百鸟高高兔走肥。","烟中敛翼远不下，节短暗合孙吴机。","此时一中贵快意，深林燕雀何须避。","惟将搏击应凉风，谁贪饱脔矜山雉。","昨见少年向南市，买鹰欲放平原辔。","凡才侧目饱人喂，不似画中有神气。","夜来鸱枭作精魅，安得放此向人世，秋风一试刀棱翅。"]},{"t":"赠歌者","f":"七言古诗","c":["东风吹雨杨花落，清歌细绕鸣钟阁。","斗酒将倾客不来，白日斜飞晚云薄。","回腰欲舞不得舞，试买罗衫倩谁估。"]},{"t":"正宾以日本刀见赠歌以答之","f":"古风","c":["昨者吕君兄弟留余饮，旬日尽是陈遵解投辖。","有如前日桐乡之围无吕君，却是睢阳少南人。","吕君虎腰额虎额，万橹梯城双臂格。","幕府厅前脚打人，夜报不周崩一壁。","飞甓雨下完孤城，张巡不死南人生。","五千步马随朱缨，手指东海鸣金钲。","解刀赠我何来者，断倭之首取腰下。","首积其如刀有余，为寿兄前人一把。","是日别君霰飞子，佩刀骑马三十里。","夜眠酒家枕刀醉，梦见白猿弄沟水。","把鞘还惊未脱底，电母回身不敢视。","黑夜横分芒砀蛇，清秋碎割咸阳玺。","历个乃脱介俚，世间宝物稀有此。","方蝉道人穷莫比，挂壁穿之蒯缑耳。","人言宝刀投烈士，吕君何不持之向燕市。","荆轲聂政猝难致，五陵七贵家家是。","报恩结义从此始，却以投余据何理。","雄心如君莫可拟，用以投余良有以。","夜夜酣歌感知己。"]},{"t":"锦衣篇答赠钱君德夫","f":"古风","c":["啸蹙风云悲下雨，丈夫自是人中虎。","骂座曾喧丞相筵，槌鼓终埋江夏土。","南州有士气不羁，应科赴召靡不为。","闱中幕下岂所志，有托而逃世莫知。","西河高士双眼碧，阅人多矣金在石。","独许文章可将兵，到处降旗出城壁。","渭也闻之笑开口，渭才敢望诸君后。","小技元羞执戟人，雄心自按调鹰手。","古来学道知者希，今世谁论是与非。","啸歌本是舒孤抱，文字翻为触祸机。","君不见，沈锦衣？"]},{"t":"石门篇赠邵大佩","f":"古风","c":["君不见邵大佩，家住石门天所买。","两峰挟汉扶太阳，十里为波到沧海。","见君四明西郭外，主人楼居清水带。","一夜高论悬河流，四壁古文蠹鱼坏。","却说邵君赤城客，挟策从师岁三改。","绿袖青衿美少年，骑龙策凤专相待。","邵君敛衿如欲前，自言家住石门边。","仙人不去桃花洞，霞气时流芳草筵。","须臾抱笔加我手，邀我题诗进我酒。"]},{"t":"赋得百岁萱花为某母寿","f":"七言古诗","c":["二十年前转眼事，忆共郎君醉城市。","阿母烹鸡续夜筵，夜深烛短天如水。","我母当时亦不嗔，郎君过我亦主人。","两家酣醉无日夜，坛愁瓮怨杯生菌。","只今白首二十载，我母不在尔母在。","八十重逢生日来，双扉况复门庭改。","我今破网未番然，两翅犹在弹丸边。","郎君长寄书一纸，阿母多应赞一言。","上寿谁人姓张者，图里萱花长不谢。","阿母但办好齿牙，百岁筵前嚼甘蔗。"]},{"t":"天坛","f":"七言古诗","c":["张公当时骑白雀，下与高皇共斟酌。","一从九鼎向幽燕，碧坛空锁琉璃斮。","古松旧柏黑成迷，绿瓦从中一雉飞。","杨雄不得陪郊祀，空忆当年执戟时。","龙驹远自施罗来，开平巳死无人骑。","却付羽林谁健儿，压沙五石缓其蹄。","真人雄心老更雄，月中自控赴斋宫。","四十八卫万马中，一尘不动五里风。","黄柏太苦蔗太甘，盛时文字忌新尖。","当时作颂卑枚马，付与金华宋景濂。"]},{"t":"十六夜踏灯与璩仲玉王新甫饮于大中桥之西楼","f":"七言古诗","c":["树枝画月千条弦，十五不圆十六圆。","挂向酒楼檐外边，南市好灯值底钱。","大中桥上游人坐，不饮空教今夜过。","红脂在口香在楼，那能一个到垆头。","青衫白马无聊甚，望断黄金小钿鞦。"]},{"t":"淮阴侯祠","f":"七言古诗","c":["荒祠几树垂枯枣，黄泥落尽朱旗纛。","花桐漆粉缀须眉，犹是登坛人未老。","半生作计在鱼边，才得河堤老妇怜。","谁知一卷长竿去，唾取真王只五年。","暗中朱碧知谁是，浊水浑鱼每相似。","当时密语向陈豨，更谁传向他人耳。","丈夫勋业何足有，为虏为王如反手。","提取山河与别人，到头一镬悲烹狗。"]},{"t":"写竹赠李长公歌","f":"古风","c":["山人写竹略形似，只取叶底潇潇意。","譬如影里看丛梢，那得分明成个字。","公子远从辽东来，宝刀向人拔不开。","昨朝大战平虏堡，血冷辘轳连鞘埋。","平虏之战非常敌，御史几为胡马及。","有如大酋之首不落公子刀，带胄诸君便是去秋阮游击。","不死虏手死汉法，败者合死胜合优。","公子何事常忧愁，一言未了一叹息，双袖那禁双泪流。","却言阿翁经百战，箭镞刀锋密如霰。","幸余兄弟两三人，眼见家丁百无半。","往往弯弓上马鞍，但有生去无生还。","只今金玉光腰带，终是铜瓶坠井干。","兼之阿翁不敢说，曾经千里空胡穴。","武人谁是百足虫，世事全凭三寸笔。","山人听罢公子言，一虱攻腰手漫扪。","欲答一言无可答，只写寒梢卷赠君。"]},{"t":"刘总戎国挽章应乃子索（子言和戎非翁志也。第八言不死于妇之手也）","f":"七言古诗","c":["胡尘不动天山没，胡儿拽马求汉物。","壮士收翎铩皂雕，将军射雁嬉青鹘。","修髯三尺别沙场，苗叶金枪插在窗。","闲将马革不得裹，羞向红妆泣数行。","雁门昔有李将军，公亦提符守雁门。","数奇数偶枭卢等，必得封侯有几人。"]},{"t":"琴高图为李勋卫赋","f":"七言律诗","c":["天上神仙塞紫虚，人间毛颖不胜书。","乍闻弄玉骑青凤，又见琴高跨赤鱼。","千年古素粘蝴蝶，苍涛高处擎红颊。","不知侬是画中人，欲请波臣后鳞鬣。"]},{"t":"渔乐图（都不记创于谁，近见汤君显祖，慕而见学之）","f":"楚辞体","c":["一都宁止一人游，一沼能容百网求？","若使一夫专一沼，烦恼翻多乐翻少。","谁能写此百渔船，落叶行杯去渺然。","鱼虾得失各有分，蓑笠阴晴付在天。","有时移队桃花岸，有日移家荻芽畔。","江心射鳖一丸飞，苇梢缚蟹双螯乱。","谁将藿叶一筐提，谁把杨条一线垂。","鸣榔趁獭无人见，逐岸追花失记归。","新丰新馆开新酒，新钵新姜捣新韭。","新归新雁断新声，新买新船系新柳。","新鲈持去换新钱，新米持归新竹然。","新枫昨夜钻新火，新笛新声新暮烟。","新火新烟新月流，新歌新月破新愁。","新皮鱼鼓悲前代，新草王孙唱旧游。","旧人若使长能旧，新人何处相容受。","秦王连弩射鱼时，任公大饵刳牛候。","公子秦王亦可怜，祇今眠却几千年。","鱼灯银海干应尽，东海腥鱼腊尽干。","君不见近日仓庚少人食，一鱼一沼容不得。","白首浑如不相识，反眼辄起相弹射。","蛾眉入宫骥在枥，浓愁失选未必失。","自可乐兮自不怿，览兹图兮三太息。","噫嗟嗟乐哉！","愧杀青箬笠。"]},{"t":"漂母非能知人特一时能施于人耳观其对信数语可见而古今论者胥失之予过其祠感而赋此","f":"七言律诗","c":["男儿偃饿淮阴上，老婺一饭来相饷。","自言祇是哀王孙，谁云便识逢亭长。","秦项山河一手提，付将隆准作汤池。","称孤南面魂无主，万古争夸漂母祠。"]},{"t":"谷日大雪口号二首（客南京） 其一","f":"七言律诗","c":["谷日之雪一何大，一尺一半自昨夜。","望中飞絮已迷天，安得犹窥凤城瓦。","横街十丈滑如油，短驴难踏转生愁。","江边总有梅花发，诗客应无一个游。"]},{"t":"谷日大雪口号二首（客南京） 其二","f":"七言律诗","c":["晴天好驴稳如坐，鹅眼黄边只十个。","今朝百个不教骑，早起怀人午将过。","此时观中杨道人，三四黄冠拥火盆。","东边殿阁高无数，笑指瑶池白玉京。"]},{"t":"雪中骑驴访某道人于观追忆曩日栖霞之约","f":"七言律诗","c":["昨日雪深驴没蹄，今日雪晴驴可骑。","此时去访杨道士，青天犹压杨花垂。","太平门外虽多景，莫妙梅花水清冷。","栖霞有约不得行，孤负千峰老鸦颈。"]},{"t":"沈叔子解番刀为赠","f":"七言古诗","c":["沈子报雠塞外行，一诧便得千黄金。","买马买鞍意不惬，更买五尺番家铁。","镂金小字半欲灭，付与碧眼译不出。","细瓦厂中多狐狸，京师夜行不敢西。","叔子佩之只一过，黄蒿连夜闻狐啼。","今年我从上谷行，中丞遗我聊癸庚。","买驴南归只两旬，只愁马上逢黄巾。","叔子见我无所仗，解刀赠我行色壮。","毕竟还从水道归，挂在蓬窗两相向。","一日十拔九摩挲，鞘影鳞鳞入向河。","须臾报道渔罩外，电脚龙腾五尺梭。"]},{"t":"沈叔子解番刀为赠二首 其二","f":"古风","c":["知君本有吞胡气，太白正高秋不雨。","白蛇五尺自西来，出匣不多飞欲去。","佩此刀，向辽阳，土蛮畏死为君降。","阏氏纵有菱花镜，断却蝤蛴那得妆。","君如佩此向上谷，而翁之死人共哭。","黄酋亦重忠义人，一见郎君悔南牧。","河套云中尽虏庭，君如佩此去从军。","不须血染锋边雪，但见旗褰马上云。","看君眼大额广长，有如日月挂扶桑。","君有宝刀君自佩，解刀赠我不相当。"]},{"t":"寄郦绩溪仲玉为钱氏门人","f":"古风","c":["绩溪县亦神州赤，闻君作簿无鱼食。","谁能嚼肉过屠门，瘦杀鸾栖一枝棘。","近来二哥自县来，览君诗帙羡君裁。","高情欲并崔松馆，别体尤工汉柏台。","文成一线今将断，钱翁老死寒灰散。","十年半夜急传灯，西来衣钵君应管。","莫言小釜烹鲜鱼，莫言牛刀割只鸡。","真儒不拣啼儿抱，主簿同安是阿谁？","去年别君天真馆，我犹缚翅君飞远。","只今缚解翅不长，无由一奋来溪畔。","司马功高旧主人，君真父母匪邦邻。","坟头松丱今何似，匣里弓刀暗却尘。","由来壮士悲罗雀，我亦因之感死?。","今来已是十余春，金钱银钱不一缗。","我复何辞公不嗔，会须上冢拊愁云。","一哭裂却石麒麟，下来与君谈苦辛。"]},{"t":"四张歌张六丈七十","f":"古风","c":["开元之唐有张果，乃云生长陶之唐。","师汉帝者张子房，子房之后有张苍。","张苍之龄百余许，老无牙齿只吃乳，夜夜枕前罗十女。","子房辟谷祈不死，先师黄石公，后约赤松子。","张果骑驴驴是纸，明皇药果杯酒里。","果齿焦黑如漆米，起取如意敲落之，新牙排玉光如洗。","三郎惊倒谓玉环，我欲别尔渡海寻三山。","玉环泪落君之前，梨花春雨不得干。","繄彼三仙人，是君之祖君是孙。","今年己丑腊嘉平，正君七十之生辰。","三祖消息虽寥寥，桃仁传种还生桃。","况君作诗句多警，又如尔祖张三影。","三影诗翁八十余，此时特娶如花姝。","正宜七十张公子，夜夜香衾比目鱼。"]},{"t":"十月望十二月朔百舌群鸣连日腊朔之夜雷电彻晓大雨两月乡村人来说虎食人经秋不去","f":"古风","c":["万历十八年十二月之朔，百舌声声叫如昨。","如朋唤友互答应，乃是气机使然诺。","百舌小鸟尔，颛顼使之敢不听。","雷电本大物，蛰藏已久矣。","何为十一月，彻晓殷殷令人惊。","电入我窗两三划，我疑是灯还未灭。","起看灯花已落油已干，始知是电耳非关灯之残。","气候变迁亦常事，山林老翁闲料理。","十月十一月，连月苦大水。","十二月来还未止，猛虎食人如食豕。","百物价高宁倍屣，我亦左听右出耳。","信知十说九是诡，不饮不啖拚已矣。","宾来宾去无将迎，携榼提壶见好情。","谑谈不把苍毛尘，偶语惟禁白玉京。","几筵屏帐无家火，鞋袜衣衫多补丁。","噫嘻吁！","百鸟之语谁能解，百舌鸣冬或报瑞。","年来世事怪，反常常反怪。","安得公冶来，为鸟译出令人快。","我所解者提胡卢，枝头劝我邻家沽。","提胡卢，不知吾，少青蚨。"]},{"t":"铜雀妓","f":"五言律诗","c":["重泉锁玉燕，閟烛绕金蛾。","君销陵柏土，妾断偃松萝。","荐梦无云雨，留香别绮罗。","愿为铜雀瓦，生死托漳河。"]},{"t":"琉球刀 其二","f":"五言律诗","c":["单刀新试舞，双剑旧能轮。","雨过腥闻血，风旋雪裹身。","对镮归思动，挂壁蒯缑尘。","醉后时横看，终当赠与人。"]},{"t":"春日过宋诸陵 其一","f":"五言律诗","c":["藁葬未须怜，生时巳播迁。","威仪非旧典，世代是何年。","过客悲山鸟，王孙种墓田。","回看陇头树，似接汴京烟。"]},{"t":"春日过宋诸陵 其二","f":"五言律诗","c":["落日愁山鬼，寒泉锁殡宫。","魂犹惊铁骑，人自哭遗弓。","白骨夜半语，诸臣地下逢。","如闻穆陵道，当日悔和戎。"]},{"t":"金客","f":"五言律诗","c":["君是邺儿非，黄须短褐衣。","单身亡命去，虏首卖钱归。","业旷家人弃，门寒结客稀。","自知终有用，穷巷且藏机。"]},{"t":"赋得战袍红","f":"五言律诗","c":["海罽染啼猩，征袍制始成。","春笼香共叠，夜帐火俱明。","自与鹑旗映，还宜蟒绣萦。","战归新月上，脱向侍儿擎。"]},{"t":"严先生祠","f":"五言律诗","c":["碧水映何深，高踪那可寻。","不知天子贵，自是故人心。","山霭销春雪，江风洒暮林。","如闻流水引，谁识伯牙琴。"]},{"t":"怀陈将军同甫","f":"五言律诗","c":["飞将远提戎，翩翩气自雄。","椎牛千嶂外，骑象百蛮中。","铜柱华封尽，昆池汉凿空。","雁飞真不到，何处寄秋风。"]},{"t":"初入京瞻宫阙","f":"五言律诗","c":["域中夷夏极，天上帝王家。","西内宸居逼，南都鼎地赊。","乌啼御沟柳，象散阁门花。","昨到贫方朔，封书载几车。"]},{"t":"聚法师将往天台止其徒玉公庵中余为留信宿","f":"五言律诗","c":["欲向天台去，先为剡水寻。","秋行万山出，夜宿一庵深。","燕语调花气，猿归带讲心。","年年石梁兴，送尔益沈吟。"]},{"t":"哀周郑州沛 其一","f":"五言律诗","c":["莫以拘挛辈，交攻放达偏。","穷如知老后，乐似欠年前。","匣藻鲛俱泣，园花石共迁。","伤心能几辈，教我不潸然。"]},{"t":"哀周郑州沛 其二","f":"五言律诗","c":["雪涕寻前谊，敲门忆昨晨。","枭卢呼未歇，虾蟹醉仍频。","日者过荒馆，霜颠破角巾。","飘零霎如此，昨日故将军。"]},{"t":"赋得风入四蹄轻 其一","f":"五言律诗","c":["骏马四蹄风，形容有杜公。","一尘不动外，千里飒然中。","白草连天靡，苍鹰蹋翅从。","檀溪不须跃，随意过从容。"]},{"t":"赋得风入四蹄轻 其二","f":"五言律诗","c":["爱妾换初詶，将军蓦紫骝。","飕飕只闻响，阵阵不禁秋。","练影难长曳，房星易一流。","路旁看不细，多是失回头。"]},{"t":"赋得风入四蹄轻 其三","f":"五言律诗","c":["借将从虎物，并去翼龙腓。","戍削才辞枥，崩轰巳破围。","寒呼随踠起，黑旋裹鞍飞。","曾听将军说，双双碎铁衣。"]},{"t":"赋得风入四蹄轻 其四","f":"五言律诗","c":["赤骥本龙精，行时不是行。","看迟八尺影，过急一团声。","带烙成骈死，嘶盐了此生。","孙阳何处是，泪尽太行程。"]},{"t":"道场山赠栖云禅者","f":"七言律诗","c":["古塔临空宝阁欹，云峰上去路逶迤。","山田获稻僧人出，湖水行舟落叶移。","风静鸟翔施饭石，日斜鱼聚放生池。","远公心地元无住，却共飞云此住持。"]},{"t":"君从","f":"七言律诗","c":["君从闽海下南昌，正值中官降玉皇。","龙号真人亲拜斗，绣衣使者自焚香。","坛中祝寿千官满，官里传幡两道长。","不是薄游江海客，何由得睹此辉光。"]},{"t":"九重","f":"七言律诗","c":["九重忧隐德如汤，祷祀坛傍夜有光。","旱魃正逢周甲子，神君俱集汉明堂。","绣成幡盖虹双引，挂定琉璃水一行。","闻说词臣咸萃止，抽毫拂素侍君王。"]},{"t":"保安州（寄青霞沈君）","f":"七言律诗","c":["终军愤懑几时平，远放穷荒尚有生。","两疏伏阶真痛哭，万人开幕愿横行。","朝辞邸第风尘暗，夜度居庸塞火明。","纵使如斯犹是幸，汉廷师傅许谁评。"]},{"t":"奉送同府潘公募兵广东","f":"七言律诗","c":["使君佐郡俨行春，开府知名下令新。","手挈万金收死士，身藏半绶见乡人。","部分卷甲趋春雨，弩矢成行夹画轮。","引向辕门投谒罢，试看主客集鱼鳞。"]},{"t":"奉送同府潘公募兵广东二首 其二","f":"七言律诗","c":["亲承节命远征兵，暂侍高堂锦服明。","横海旧多经战士，狭斜新识少年名。","宿依山店樵苏寂，行负藤于结束轻。","来往莫须愁道远，明春专待破番营。"]},{"t":"寓穿山感事","f":"七言律诗","c":["荒城临海一山围，何事东方滞衮衣。","晓日每看牙将集，秋风自送远人归。","霜寒戍草嘶征马，潮落江门露钓矶。","欲请长缨何处是，且寻酒伴扣荆扉。"]},{"t":"从少保公视师福建抵严宴眺北高峰同茅大夫沈嘉则","f":"七言律诗","c":["晋公雅望复英姿，坐领楼船远视师。","夜半自平淮蔡日，秋深同上华山时。","军营列岸江全绕，骑火穿林席屡移。","却说陪游宾从美，不妨帐底有风吹。"]},{"t":"与客登招宝山观海遂有击楫岑港一窥贼垒之兴谨和开府胡公之韵奉呈","f":"七言律诗","c":["沧海遥连雉堞明，登临喜共幕宾清。","千山见日天犹夜，万国浮空水自平。","不分番夷营别岛，愿图方略至金城。","归来正值传飞捷，露布催书倚马缨。"]},{"t":"宿长春祠夜半朱君扣榻呼起视月山缺处露钱塘仅一勺而夜气滃之","f":"七言律诗","c":["长春明月夜阑干，起视当眉尺五间。","千里林光俱浸水，一杯江气亦浮山。","似闻隔岫吹长笛，欲唤真官语大还。","忽忆广寒清冷甚，有人孤佩响珊珊。"]},{"t":"恭谒孝陵正韵","f":"七言律诗","c":["二百年来一老生，白头落魄到西京。","疲驴狭路愁官长，破帽青衫拜孝陵。","亭长一杯终马上，桥山万岁始龙迎。","当时事业难身遇，冯仗中官说与听。"]},{"t":"答赠盛君时饮朝天宫道院","f":"七言律诗","c":["长安道院一牵裳，司马筵中再举觞。","柿叶学书才不短，杏花插鬓意何长。","药沈绿醑家厨酿，霜折红蕉道观房。","坐里黄冠三两辈，醉来相与说先皇。"]},{"t":"宫人入道","f":"七言律诗","c":["昭阳队里混铅华，垂老参师日半斜。","不向秋风怨团扇，却教明月进琵琶。","朝留楚簟身为雨，夜绣茅君线作霞。","见说缑山闲姊妹，尚论恩宠旧谁家。"]},{"t":"李长公邀集莲花峰","f":"七言律诗","c":["马水雄关天畔开，貂储暇日更登台。","高山似为遮胡设，折磴偏能勒骑回。","杯杓催时严黑雨，琵琶隔座揽轻雷。","须臾卷地寒风急，似送荆卿易水来。"]},{"t":"邦宪死","f":"七言律诗","c":["远从黄浦白波边，泪尽枯鱼黑索前。","共许相逢还几度，讵知此别即千年。","白杨树下多风起，广柳车中少客眠。","见说吴门塘上曲，才歌高士即潸然。"]},{"t":"送郑职方","f":"七言律诗","c":["高皇宝鼎北平迁，羽卫犹屯万灶烟。","养虎最宜防猝饿，调鹰莫更使多眠。","长江水绿千矛闪，大树旗红一的县。","匹马不嘶穿垒过，知君此际气翩翩。"]},{"t":"赠辽东李长君都司","f":"七言律诗","c":["公子相过日正西，自言昨日破胡归。","宝刀雪暗桃花血，铁铠风轻柳叶衣。","百口近来馀几个，一家长自出重围。","禅关夏色炎如此，听罢悽霜杂霰飞。"]},{"t":"徐州","f":"七言律诗","c":["今岁青青陇麦稠，去年河水过堤流。","无家不自波中出，有鳖都经树杪游。","枣叶双扉询翠袖，柳根一面护黄楼。","泗州潭底猕猴老，不信今还锁泗州。"]},{"t":"驾归自阅群望于衢恭赋","f":"七言律诗","c":["桃李晴曛禁苑烟，銮舆新幸北郊旋。","团花靺鞈蒐春日，细柳旌旗拊髀年。","一道甲光将雪借，千群马色截云鲜。","谁兼将帅为天子，共喜文皇九叶玄。"]},{"t":"寿吴宣府","f":"七言律诗","c":["近来宣府息烽埃，台吉求生款镇台。","笑引双椎胡女拜，传呼万帐令公来。","艾年佩鹊宁非早，薇省垂鱼不待推。","报与江南春信道，题诗寄处陇梅开。"]},{"t":"燕子楼","f":"七言律诗","c":["牡丹春后惟枝在，燕子楼空苦恨生。","昨泪几行因拥髻，当年一顾本倾城。","分为翡翠笼俱老，讶道泉台伴不成。","犹胜分香台上妾，更无一个哭西陵。"]},{"t":"驾幸月坛群望西街","f":"七言律诗","c":["玉露清秋湛碧空，金舆夕月引群工。","红云自结龙文上，彩仗如移桂影中。","壁畔常仪端捧鬯，郊西新魄正垂弓。","布衣久分华山侣，笑向归驴堕晚风。"]},{"t":"九月十六日游南内值大风雨归而雪满西岫矣","f":"七言律诗","c":["宝树琼台夹梵轮，星坛月宇讵非神。","从来天上游俱梦，说向人间恐未真。","风雨故梢铜网翼，鱼龙欲活石桥鳞。","寻诗正是回驴处，忽面西山雪照人。"]},{"t":"闻都督再迁山西武宁","f":"七言律诗","c":["胡床雪夜斗牛裘，亲待回探夜不收。","蓟北咽喉此为最，山西将帅尔称优。","千金粉面捐厮养，百鞘朱提买络头。","倒死潇拦姑诺诺，大宛终败匿骅骝。"]},{"t":"自坌道走居庸雪连峰百仞横障百折银色晃晃故来扑人中一道亦银铺也坐小兜冒以红毡疲骡数头匣剑笈书相后先冰气栗冽肌粟畾畾如南夏痱痤苦吟冻肩倍耸惫甚矣却赢得在荆关图画中浮生半日","f":"七言律诗","c":["昨夜飞花苦不多，朝来起视白峨峨。","一行裘帽风中去，半日关山雪里过。","银髻望夫高入汉，玉屏随客折成河。","中间一道明如线，四角红毡拥数骡。"]},{"t":"重修乾清宫成迎慈圣再御","f":"七言律诗","c":["阊阖重新紫极熙，姬姜再御宝軿移。","慈颜既近趋承易，圣体犹冲保护宜。","鸟换歌筵前日曲，花繁辇路旧时枝。","一人奉养兼天下，大孝鸿名万古垂。"]},{"t":"读文信公仙岩祠集焚吊 其一","f":"七言律诗","c":["每疑天意不分明，枉杀呼天问屈平。","诸葛既难扶后主，庐陵何用产先生。","停舟此夜艰危地，出户当年叹息声。","脑子不灵尤怪事，竟将腔血洒燕京。"]},{"t":"寄上海诸友人","f":"七言律诗","c":["双鱼岁晚渡江津，笋饭㹠羹又换春。","弃印可望天上客，射书元属海东人。","天愁夜幕铃偏急，栅暗缧藤鼠正巡。","湖水万重兰芷隔，因君还上佩芳身。"]},{"t":"清凉寺云是梁武台城","f":"七言律诗","c":["萧梁台殿一灰飞，荠麦清明雉兔肥。","坏榜几更金刹字，饥魂应烂铁城围。","东来镜折龙潭水，北去芦长燕子矶。","千古兴亡真一梦，隔江閒数莫鸦归。"]},{"t":"某君见遗石磬","f":"七言律诗","c":["泗上归来动隔年，亲提浮磬与泠然。","一除梵版裁云俗，再扣哀鹂绕竹圆。","老去固难腰似折，贫来直到室如悬。","閒窗重理当时架，数杵香残客话边。"]},{"t":"伍公祠","f":"七言律诗","c":["吴山东畔伍公祠，野史评多无定时。","举族何辜同刈草，后人却苦论鞭尸。","退耕始觉投吴早，雪恨终嫌入郢迟。","事到此公真不幸，镯镂依旧遇夫差。"]},{"t":"岳公祠","f":"七言律诗","c":["墓门朱戟碧湖中，湖上桃花相映红。","四海龙蛇寒食后，六陵风雨大江东。","英雄几夜乾坤博，忠孝谁家俎豆同。","肠断两宫终朔雪，年年麦饭隔春风。"]},{"t":"访李岣嵝山人于灵隐寺","f":"七言律诗","c":["岣嵝诗客学全真，半日深山说鬼神。","送到涧声无响处，归来明月满前津。","七年火宅三车客，十里荷花两桨人。","两岸鸥凫浑似昨，就中应有旧相亲。"]},{"t":"某伯子惠虎丘茗谢之","f":"七言律诗","c":["虎丘春茗妙烘蒸，七碗何愁不上升。","青箬旧封题谷雨，紫砂新罐买宜兴。","却从梅月横三弄，细搅松风灺一灯。","合向吴侬彤管说，好将书上玉壶冰。"]},{"t":"钱王孙饷蟹不减陈君肥杰酒而剥之特旨","f":"七言律诗","c":["鲰生用字换霜螯，待诏将书易雪糕。","并是老饕营口腹，省教半李夺蛴螬。","百年生死鸬鹚杓，一壳玄黄玳瑁膏。","不有相知能饷此，止持齑脯下村醪。"]},{"t":"上督府公生日诗","f":"七言古诗","c":["远曙轻笼海色苍，凉飔新荐菊英黄。","清秋此日逢华诞，绣褓当年绕异香。","地与人文增气象，天为王国产祯祥。","壮猷未老如方叔，秘略曾传似子房。","初捧兵符分虎竹，再衔使命驭龙骧。","森罗岛屿诸夷会，锁钥门庭一面当。","刁斗不传人自乐，牙旗欲动势偏扬。","雄豪定远遥辞汉，宽大汾阳近在唐。","管领华夷新士马，扫平吴越旧封疆。","曾先突骑重围里，亲式鸣蛙大道旁。","巳遣严兵营细柳，更教长剑倚扶桑。","三承宠锡恩何渥，一受深知德愈光。","定有姓名题御扆，每勤赏赐到遐荒。","千龄素质双麋鹿，五色奇毛两凤凰。","国有昌符臣协吉，家承严训子徵良。","田单下狄亲鸣鼓，姬旦居东久缺斨。","屡触歊炎辞羽盖，转巡郊野憩甘棠。","军中作气频投石，阵里筹机捷探囊。","敞日辕门标大纛，浮天水寨集馀皇。","雕弓并月名繁弱，宝剑冲星出豫章。","几处名香迎马首，数群长鬣夹车箱。","量兼沧海涵诸岛，身作长城障一方。","万里星辰罗北极，百番贡道出东洋。","曹彬赐剑权偏重，庾亮登楼兴合狂。","引至偏裨坚誓约，邀还宾佐据胡床。","鲸鲵久巳封京观，翡翠行看出越裳。","讵止芳名流简册，还将伟绩著旂常。","功成淮蔡应趋阙，路涉燕齐好㣥粮。","将相位兼劳出入，君臣道合致平康。","山城令节茱萸发，高宴华轩锦绮张。","日照花明诸乐作，风吹帐启众宾藏。","鹤鸣流响闻天汉，芝灿浮光到羽觞。","竞取良辰占上寿，复欣嘉会嗣重阳。","树联月桂辉花萼，斗近天河挹酒浆。","黑齿呈歌须译问，文身献舞傲专场。","地连玄峤仙常集，候傍黄钟日渐长。","共以精诚抒华祝，况兼佳丽属钱塘。","鲰生本住山阴里，浪迹疑乘海畔航。","城下钓鱼怀漂母，堂前结客忆周郎。","未逢黄石书谁授，不坠青云志自强。","抱玉巳怜非楚璞，吹竽那识动齐王。","幸因文字蒙徵檄，时佩菅毫侍琐廊。","綦履东西鱼共丽，戎衣左右雁俱翔。","县知陈阮时游魏，岂乏邹枚并寓梁。","博采燕昭期致骏，曲存宣父爱非羊。","众人国士阶元别，知己蒙恩心所量。","自分才难堪记室，人疑待巳过中行。","搆成燕雀犹知贺，报取琼瑶未可偿。","偶值高门挂弧矢，且赓小雅赋桑杨。","却惭未协宫商调，莫并当筵巧奏簧。"]},{"t":"督府明公新膺加荫（加太子太保、左都御史。一子荫锦衣千户）","f":"七言古诗","c":["连天沧海抱江洲，节钺东临今几秋。","早遣通儒招粤尉，远传片檄到蛮陬。","寇当剧处连营破，酋若逋时举族收。","万里华夷冯控制，一方文武备咨谋。","献俘不用陈兵见，对客频听借箸筹。","名将始知今亦有，元勋岂独古难酬。","近衔丹诏恩何渥，遥领青宫秩更优。","幕卷共瞻新换服，旗开尚见旧县斿。","春涛拍海风俱息，夜柝鸣边月正流。","建业既趋功可让，太原未下赏还留。","兰台本取银章绾，鹤禁谁扶宝辇游。","将帅并兼储副托，封章应掌百寮纠。","召公遗烈由孙显，曹璨英风与父俦。","世禄永延盟带砺，属车前导护宸旒。","东山久已淹姬旦，南服从来用武侯。","燕颔果封终入汉，鬯卣将锡定于周。","军书羽集裁偏暇，湖水冰涵望尽浮。","翠幰行堤花绕树，锦筝停曲鸟窥楼。","几年载笔承英盼，四海为家只浪投。","授简真惭称记室，逢人交庆识荆州。","追陪有分尘清宴，著述无能付短讴。","即拟汉家麟阁上，看题姓字最高头。"]},{"t":"蛙声","f":"七言古诗","c":["红芳绿涨绿连天，夹岸蘼芜匝涧湾。","别有鼓吹喧渡口，不教蚯蚓叠阳关。","殷郎咄咄书空易，汉吏期期奉诏难。","华苑公私猜典午，荜门佶屈课殷盘。","连营甲卒枚前閧，塞寺沙门咒后餐。","蟾蜍借月瘖何谓，科蚪萦波字与翻。","蒲潦溽蒸号太酷，梅风飘荡控宜寒。","使车南诣雕题译，贝叶西来鴃舌弹。","金响侠徒丸尽落，佩垂战士怒弥殷。","谐语就笞方乞半，孤雏隔乳未啼残。","韩冯枕荷愁喧寐，戴胜降桑许聒眠。","利口啬夫儳喋喋，薄言钲罢鼓阗阗。","咽兢笳乌不得晓，杂沸莲露几时圆。","迢迢来度天姬帐，閤閤回惊钩者船。","摇繁藻镜驱成瀫，韵碎菱丝讵可穿。","寄语草深瓜烂处，急呼蝍蛆备蚿怜。"]},{"t":"数年来南雪甚于北癸未复尔人戏谓南北之气互相换似贾人带之往来理或然欤边塞不易雨而今每潦十九韵","f":"七言古诗","c":["阴阳北去随南客，雨雪南来自北天。","雨烂胡弓知几岁，雪高越瓦巳三年。","偶然尽海迷辽鹤，不是登桥听杜鹃。","吠犬从今无一处，喘牛必问有诸贤。","明明日向彤雰暗，杳杳玑笼紫雾悬。","羲氏轮膏埋壁屑，滕公河水泻银钱。","铦锋插戟包难见，深阱穿泉粉愈填。","万里萧条昏井邑，千家凌夺失园田。","疑花宿误群归羽，折竹真摧几个圆。","鼻醋酽寒先惯吸，羹盐调剂未堪煎。","倾危作兔当山顶，搏控成狮向日边。","借皎肥身灰象饱，吹柔害物素猫拳。","绵针絮刺俱丛棘，玉瓣银筒假淤莲。","阳德尽阏阊阖上，阴威直到祝融颠。","华亭羽翼漫天久，上蔡鹰卢猎野偏。","伍员江长潮正怒，三闾沙白骨新捐。","稀如尸蛊穿云去，细似绳蝇点壁旋。","急舞鱼鳞明扈跋，繁遮蝗阵暗霄骞。","袁安卧苦僵犹得，解缙尸埋醉可怜。","万事岂俱埋得尽，有时终露髑髅冤。"]},{"t":"次夕降抟雪径满鹅鸭卵余睡而复起烧竹照之八十韵","f":"楚辞体","c":["把炬循除立断藜，鸦惊弹雪宿卬低。","终宵有许垂鹅伏，片刻应能没马蹄。","一一劈分舒阔掌，团团捲掷碎霜梨。","红场尽海毬争打，白鹭横江荻未栖。","崩屋塌檐支正急，窥窗入窦倚相暌。","后飞轻薄高难下，先引威棱导且齐。","隔岁窖藏犹霰雹，群儿想象入狻猊。","瓣觚出六摧桃李，瑞舛过三党稗稊。","博浪金椎徂击遍，弥天白纛杀机提。","鸾髡鹄赭吹毛尽，竹哭梅啼到骨披。","穿重解深三窟兔，侵多不剩一丸泥。","暗随鹏翼长沙拍，亮误鸡司短曙啼。","灰烬挑残寒夜火，袍谁脱与故人绨。","流苏既缟堪钩挂，粉的浑绵向镜低。","风絮谢娘难可拟，烟芦■客几成迷。","公孙被襆凉如铁，子母蚨缗泻若澌。","兽径易漫麋散迹，猎弓难放麝香脐。","岩俱周处南山额，毳尽苏卿北海羝。","鲛室百窗帘蛤蚌，羌胡一国水玻瓈。","饥脾苦逼长安殍，酸鼻寒凄宰相醯。","叶尹如捐棺可玉，麻姑未老海堪梯。","洪厓走汞流松外，穆满量珠赏竹西。","绿鬓取裁髽髻样，金钗都换柰花鎞。","儒齑瓦瓮盐艰糁，侠啖屠门蒜太臡。","蝙蝠假仙摇石乳，蚺蛇冯胆搅银堤。","将纫作盖俱成羽，取缀为裘尽是麑。","鹰隼攫身功夺狗，牛羊埋角罪归鼷。","轩辕镜色飞桥顶，欧冶镡霜掣剑溪。","荡样乾坤成玉合，纷纭翳膜刮金篦。","杨妃暗粉玄宫发，卓氏綦巾皓首齐。","此际胡云黄满塞，当年梁简赤曾题。","霁微未必清钟磬，洒急如堪付鼓鼙。","红袖共斟将共若，锦囊须佩却须奚。","寒郊瘦岛吟成蛰，煖肉肥肌屏作闺。","渐离荆卿僵易水，赵王代娣冷摩笄。","瑶枝上汉参云雾，银鬣行天睹駃騠。","并是凌寒贞岁柏，不同趋热媚权烓。","亲淹上国裘曾敝，眼见金吾骑总缇。","尽领熊罴供扫拂，别从雉兔较罟罤。","高培粪梗团成菌，柔仿山毛嫩作荑。","肖惨睢盱夔罔两，塑娇咽项女蝤蛴。","妆涂恨少施肌发，刻画争先解佩觿。","何事井喷烦蜥蜴，秪冯阴焰飐虹霓。","瓠犀璀璨排嫣齿，榴子龃龉堕老齯。","解榇紫騧鲜豹犊，俄穿翠襮化貂袿。","宫奁镜煖因椒瑾，塞壁刀斜谢鸊鹈。","木稼怕官谣杂谶，草乾愁牧马频嘶。","娲皇炼石霄犹漏，帝女烧铅杼懒挤。","冻霤尖持燕匕首，明窗尘射魏刀圭。","睥睨钉断于阗带，沙砾砻刓令尹圭。","连日大酺粲尽掬，倾筐堆帛取如携。","骑都烂漫糜羊胃，庖坦纵横解犊膍。","燕颔不醒颓锦帐，蛾眉邀醉叠金椑。","即堪楚曲流宫徵，必唤齐伧许滑稽。","荡甲摇犀明练组，长雕大镞拭弧錍。","孤烟罢突真三日，破釜县脐仅一黳。","水木骑羊来代递，滕封弄雨各诃诋。","心忧掘阅衣麻矣，狂走芄兰带悸兮。","霎尔黄肠溲赑屃，俄然白骨葬鲸鲵。","为灯跋烛须臾灭，沃锭消璆顷刻赍。","公向苍仪腾皓洁，竟忘赤地混缁黧。","随飙过越迎关吠，度叶为花带鸟栖。","蜂蛱误猜堪蜜蜡，清明才断正饧䬾。","西池万里吹黄竹，东郭双䟫趼赤鞮。","想见穹酋鸣立?，亲看床足缩趺蠵。","恰妨青帝迎春仗，无救朱炎病夏畦。","压取刚条俱偃偃，试寻劲草但萋萋。","几时千仞消淩?，何处双桑赫海輗。","形虎似盐虚晋俎，调梅无味枉商鑴。","蝗蟊未必沈三尺，甲拆先应了一刲。","庄语夏冰虫定怪，赵襄冬日袄争徯。","风偏助势长成练，月总输光不到犀。","履薄有人愁坠谷，乘危无尽上埋奎。","岂无黄道辜葵藿，翻以丹心许蒺藜。","火急寄言青女道，添霜啼杀伯劳儿。"]},{"t":"龛山凯歌 其三","f":"七言绝句","c":["红油画戟碧山坳，金镞无光入土消。","冷雨凄风秋几度，定谁拾得话今朝。"]},{"t":"龛山凯歌六首（为吴县史鼎庵） 其三","f":"七言绝句","c":["七尺龙蟠皂线绦，倭儿刀挂汉儿腰。","向谁手内亲捎得，百遍冲锋滚海蛟。"]},{"t":"龛山凯歌 其四","f":"七言绝句","c":["无首有身秪自猜，左啼魂魄右啼骸。","冯将老译传番语，此地他生敢再来。"]},{"t":"龛山凯歌 其五","f":"七言绝句","c":["旗裹金疮碎朔风，军中吮卒有吴公。","更教厮养眠营灶，自向霜槽喂铁骢。"]},{"t":"龛山凯歌六首（为吴县史鼎庵） 其六","f":"七言绝句","c":["夷女愁妖身画丹，夫行亲授不缝衫。","今朝死向中华地，犹上阿苏望海帆。"]},{"t":"内子亡十年其家以甥在稍还母所服潞州红衫颈汗尚泚余为泣数行下时夜天大雨雪","f":"七言绝句","c":["黄金小纽茜衫温，袖摺犹存举案痕。","开匣不知双泪下，满庭积雪一灯昏。"]},{"t":"凯歌赠参将戚公 其一","f":"七言绝句","c":["战罢亲看海日晞，大酋流血湿龙衣。","军中杀气横千丈，并作秋风一道归。"]},{"t":"望夫石","f":"七言绝句","c":["海天万里渺无穷，秋草春花插髻红。","自送夫君出门去，一生长立月明中。"]},{"t":"宴游烂柯山 其一","f":"七言绝句","c":["万山松柏绕旌旗，少保南征暂驻师。","接得羽书知贼破，烂柯山下正围棋。"]},{"t":"宴游烂柯山 其二","f":"七言绝句","c":["偏裨结束佩刀弓，道上逢迎抹首红。","夜雪不劳元帅入，先禽贼将出洄中。"]},{"t":"宴游烂柯山四首 其三","f":"七言绝句","c":["群凶万队一时平，沧海无波岭瘴清。","帐下共推擒虎将，江南只数义乌兵。"]},{"t":"宴游烂柯山 其三","f":"七言绝句","c":["帷中谈笑静风尘，只用先锋一两人。","万里封侯金印大，千场博戏采毬新。"]},{"t":"武夷山一线天","f":"七言绝句","c":["双峡凌虚一线通，高巅树果拂云红。","青天万里知何限，也伴藤萝锁峡中。"]},{"t":"入武夷寻一线天道中述事 其一","f":"七言绝句","c":["花落花开隔水津，栈梯茆屋总堪邻。","扁舟若不寻归路，便是武陵深处人。"]},{"t":"入武夷寻一线天道中述事 其二","f":"七言绝句","c":["乞得琼浆一碗新，沿溪行尽渴生尘。","云英只在桃花下，不肯呼来见外人。"]},{"t":"雪中访嘉则于宝奎寺之楼店","f":"七言绝句","c":["山径寻君重复重，小楼百尺卧元龙。","安窗偏向梅花角，去映江天雪数峰。"]},{"t":"武林馆中与徐仁卿同宿因赠 其一","f":"七言绝句","c":["楼上张灯倒瓦卮，自居东面唤人陪。","须臾据案言兵事，鬃帽偏欹横两眉。"]},{"t":"武林馆中与徐仁卿同宿因赠三首（徐号天峰，武义诸生也。徐千斤） 其二","f":"七言绝句","c":["近来选士爱躯长，共说君家貌不扬。","醉后忽呼高枕睡，虎头斜倚黑绳床。"]},{"t":"武林馆中与徐仁卿同宿因赠三首（徐号天峰，武义诸生也。徐千斤） 其三","f":"七言绝句","c":["长说边关好试材，幕中进止自须裁。","连宵一骑重围里，不见钧州王秀才。"]},{"t":"夏相国白鸥园 其一","f":"七言绝句","c":["白鸥池水拍天平，相对琼楼入太清。","试问歌台生草处，当时曾许外人行。"]},{"t":"夏相国白鸥园 其二","f":"七言绝句","c":["词客登临信笔裁，每于花谢笑花开。","请观世上看花者，曾见花开不谢来。"]},{"t":"阊门送别","f":"七言绝句","c":["送别阊门日已西，自将光景比乌栖。","平生不解依枝宿，今日翻成绕树啼。"]},{"t":"寄徐石亭","f":"七言绝句","c":["闻道名园盛牡丹，豪家欢赏到春残。","自怜亦具看花眼，种菜浇畦不得看。"]},{"t":"上谷歌 其一","f":"七言绝句","c":["少年曾负请缨雄，转眼青袍万事空。","今日独馀霜鬓在，一肩舆坐度居庸。"]},{"t":"上谷歌四首 其二","f":"七言绝句","c":["遥忆前朝己巳年，六龙此去未南旋。","黑云敢作军中孽，莫怪区区一也先。"]},{"t":"上谷歌 其四","f":"七言绝句","c":["个个健儿习战车，重重壁垒铁围赊。","尽教上谷长千里，只用中丞两臂遮。"]},{"t":"宣府教场歌","f":"七言绝句","c":["宣府教场天下闻，个个峰峦尖入云。","不用弓刀排虎士，天生剑戟拥将军。"]},{"t":"胡市","f":"七言绝句","c":["千金赤兔匿宛城，一只黄羊奉老营。","自古学棋嫌尽杀，大家和局免输赢。"]},{"t":"边词 其一","f":"七言绝句","c":["四壁龙门铁削围，枉教邓艾裹毡衣。","莫言虏马愁难度，即使胡鹰软不飞。"]},{"t":"边词 其二","f":"七言绝句","c":["牙兵个个是熊罴，别选奇才养作儿。","试看阵云穿急处，一团蜂子拥人飞。"]},{"t":"白马水还道中竹枝词","f":"七言绝句","c":["墙头赤枣杵儿斑，打枣竿长二十拳。","塞北红裙争打枣，江南白苧怯穿莲。"]},{"t":"边词 其四","f":"七言绝句","c":["立马单盘俯大荒，提鞭一一问戎羌。","健儿只晓黄台吉，大雪山中指帐房。"]},{"t":"边词 其五","f":"七言绝句","c":["十八盘山北去赊，顺川流水落南涯。","真冯一堵边墙土，画断乾坤作两家。"]},{"t":"边词 其六","f":"七言绝句","c":["黄酋堕马巳成禽，汉卒争功被脱身。","魂魄至今留黑石，兜鍪连岁落鱼鳞。"]},{"t":"边词 其八","f":"七言绝句","c":["葛那颈险断胡刀，蓦手攀颏按得牢。","归向镜中嫌未正，特搓过左一丝毫。"]},{"t":"边词十三首（并客燕时到马水口及宣府之作） 其八","f":"七言绝句","c":["沙门有姊陷胡娃，马市新开喜到家。","哭向南坡毡帐里，领将儿女拜袈裟。"]},{"t":"边词十三首（并客燕时到马水口及宣府之作） 其九","f":"七言绝句","c":["汉军争看绣裲裆，十万弯弧一女郎。","唤起木兰亲与较，看他用箭是谁长。"]},{"t":"边词十三首（并客燕时到马水口及宣府之作） 其十","f":"七言绝句","c":["长缨办取锁娇娆，马上纤腰恐不牢。","好把鸳鸯靴上脑，倩谁双缚马鞍鞒。"]},{"t":"边词 其九","f":"七言绝句","c":["女郎那取复枭英，此是胡王女外甥。","帐底琵琶推第一，更谁红颊倚芦笙。"]},{"t":"边词 其十","f":"七言绝句","c":["老胡宠向一人多，窄袖银貂茜叵罗。","递与辽东黄鹞子，侧将云鬓打天鹅。"]},{"t":"边词 其十二","f":"七言绝句","c":["姑姑花帽细银披，两靥腮梨洒练椎。","个个菱花不离手，时时站马上胭脂。"]},{"t":"上谷边词 其一","f":"七言绝句","c":["胡儿住牧龙门湾，胡妇烹羊劝客餐。","一醉胡家何不可，只愁日落过河难。"]},{"t":"上谷边词 其二","f":"七言绝句","c":["风吹乾草没沙泥，齧草奔风马自蹄。","却问骆驼何处去，大酋随猎未曾归。"]},{"t":"上谷边词 其三","f":"七言绝句","c":["胡儿处处路旁逢，别有姿颜似慕容。","乞得杏仁诸妹食，射穿杨叶一翎风。"]},{"t":"琉璃河","f":"七言绝句","c":["水怪从来畏铁腥，十寻铁棒压流横。","风雷自古无回避，也截蛟龙别处行。"]},{"t":"送林某 其一","f":"七言绝句","c":["野客年来百事休，也怜歌板去难留。","若为化作沿江柳，直管莺声到岸头。"]},{"t":"漫曲","f":"七言绝句","c":["闻道张家燕子楼，青罗小帽急梳头。","花枝谁肯先春老，无奈风吹雨打愁。"]},{"t":"画两僮枕帚而睡疑是寒拾应人索咏","f":"七言绝句","c":["人间何日不尘生，扫到何年扫得清。","输与天台双行者，睡弯苕帚午鸡鸣。"]},{"t":"画高岭莫行僧众","f":"七言绝句","c":["知是峨眉第几盘，客僧愁宿日低山。","头陀指与烟生处，只隔红霞四五湾。"]},{"t":"画梅时正雪下","f":"七言绝句","c":["谁写孤山伴鹤枝，早春窗下索题诗。","今朝风景偏相似，是我寻他雪下时。"]},{"t":"竹 其九","f":"七言绝句","c":["昨夜窗前风月时，数竿疏影响书帏。","今朝榻向溪藤上，犹觉秋声笔底飞。"]},{"t":"水仙杂竹","f":"七言绝句","c":["二月二日涉笔新，水仙竹叶两精神。","正如月下骑鸾女，何处堪容食肉人。"]},{"t":"郭恕先为富人子作风鸢图偿平生酒肉之饷富人子以其谩巳谢绝之意其图必立遭毁裂为蝴蝶化去久矣予慕而拟作之噫童子知羡乌获之鼎不知其不可扛也虽然来丹计粒而食乃其报黑卵必请宵练快自握亦取其意之所趋而巳矣每一图必随景悲歌一首并张打油叫街语也亦取其意而巳矣 其一","f":"七言绝句","c":["柳条搓线絮搓绵，搓够千寻放纸鸢。","消得春风多少力，带将儿辈上青天。"]},{"t":"郭恕先为富人子作风鸢图偿平生酒肉之饷富人子以其谩巳谢绝之意其图必立遭毁裂为蝴蝶化去久矣予慕而拟作之噫童子知羡乌获之鼎不知其不可扛也虽然来丹计粒而食乃其报黑卵必请宵练快自握亦取其意之所趋而巳矣每一图必随景悲歌一首并张打油叫街语也亦取其意而巳矣 其四","f":"七言绝句","c":["我亦曾经放鹞嬉，今来不道老如斯。","那能更驻游春马，閒看儿童断线时。"]},{"t":"郭恕先为富人子作风鸢图偿平生酒肉之饷富人子以其谩巳谢绝之意其图必立遭毁裂为蝴蝶化去久矣予慕而拟作之噫童子知羡乌获之鼎不知其不可扛也虽然来丹计粒而食乃其报黑卵必请宵练快自握亦取其意之所趋而巳矣每一图必随景悲歌一首并张打油叫街语也亦取其意而巳矣 其五","f":"七言绝句","c":["缚竹糊腔作鸟飞，崩风坠雨烂成泥。","明朝又是清明节，斗买饧糖柳市西。"]},{"t":"郭恕先为富人子作风鸢图偿平生酒肉之饷富人子以其谩巳谢绝之意其图必立遭毁裂为蝴蝶化去久矣予慕而拟作之噫童子知羡乌获之鼎不知其不可扛也虽然来丹计粒而食乃其报黑卵必请宵练快自握亦取其意之所趋而巳矣每一图必随景悲歌一首并张打油叫街语也亦取其意而巳矣 其六","f":"七言绝句","c":["江北江南纸鹞齐，线长线短迥高低。","春风自古无凭据，一任骑牛弄笛儿。"]},{"t":"郭恕先为富人子作风鸢图偿平生酒肉之饷富人子以其谩巳谢绝之意其图必立遭毁裂为蝴蝶化去久矣予慕而拟作之噫童子知羡乌获之鼎不知其不可扛也虽然来丹计粒而食乃其报黑卵必请宵练快自握亦取其意之所趋而巳矣每一图必随景悲歌一首并张打油叫街语也亦取其意而巳矣 其十二","f":"七言绝句","c":["村庄儿女竞鸢嬉，凭仗风高我怕谁。","自古有风休尽使，竹腔麻缕不堪吹。"]},{"t":"郭恕先为富人子作风鸢图偿平生酒肉之饷富人子以其谩巳谢绝之意其图必立遭毁裂为蝴蝶化去久矣予慕而拟作之噫童子知羡乌获之鼎不知其不可扛也虽然来丹计粒而食乃其报黑卵必请宵练快自握亦取其意之所趋而巳矣每一图必随景悲歌一首并张打油叫街语也亦取其意而巳矣 其十九","f":"七言绝句","c":["春来偏与老人雠，腰膂如弓项领柔。","看鹞观灯都好景，正难高处去抬头。"]},{"t":"扇图","f":"七言绝句","c":["渺渺平沙四望通，天涯双树立秋风。","画工不解寒鸦意，写入隋堤绿柳中。"]},{"t":"跃鲤送人 其二","f":"七言绝句","c":["鳞鬣不殊点额归，丰神却觉有风威。","不添一片龙门石，方便凡鱼作队飞。"]},{"t":"浣溪沙 鉴湖","f":"七言古诗","c":["浅碧平铺万顷罗，越台南去水天多，幽人爱占白鸥莎。","十里荷花迷水镜，一行游女惜颜酡，看谁钗子落清波。"]},{"t":"张家槐","f":"古风","c":["张家槐，鹊巢枝，使君才出户阖扉。","鞭行人，上及飞。","弹鹊母，连鹊卵，鹊母弃雏走何所。","曙衙开，邸报来，使君朝去鹊莫归。"]},{"t":"悲饔歌","f":"古风","c":["吴人饕，越人俎。","一臛忤舌死杖下。","肉少甘，骨为土。"]},{"t":"歌风台 其一","f":"古风","c":["碎媪酒，卧媪垆。","武家垆畔鼾呼呼。","丰沛中，群酒徒。","噱季鼻大糟所都。","谁唤隆准而公乎。","十二年，左纛还。","著红衫，应午炎。","七尺所临万马环。","诸王列侯敢不虔。","猎徒酒伴隘巷看。","独召故老金爵乾。","惜青春，赭朱颜。","乃思猛士得将安。","归问野鸡还我韩。"]},{"t":"歌风台 其二","f":"古风","c":["鄂州篇，衡县权。","渭也俯，拾所残。","悲异代，良楚酸。","谓河高水流拍天，渭两过之河未然。","麻姑量海海然浅，三尺鸟爪没至骭。","大家作计一何长，请看何人偏堕短。"]},{"t":"歌风台 其三","f":"古风","c":["英彭不雌，季心所猜。","今布越耳，终当为豨。","终当为豨，不如我先之。","旧所得猛士，十当一无遗。","十既一无遗，安得不歌以思。"]},{"t":"歌风台 其四","f":"古风","c":["骓渡江，八千从。","非父老是使彼，安识籍与梁。","巴蜀公，缟新城。","奉三老教发帝丧。","义兵若河日以东。","乃知王者，师上亲长礼教下首功。","蜀公亲历效验明。","乃知猛士，难四方守易战攻。","谁兼不蹄买蹀骢。","击太牢，祀鄹乡。","听叔孙通，徵鲁诸生。","惊礼四公，远来于商。"]},{"t":"予尝梦昼所决不为事心恶之后读唐书李坚贞传稍解焉","f":"古风","c":["坚贞十七，之死靡他。","数梦男子，百两以御。","贞觉而恚，莫知其谓。","华盛来胥，我貌未悴。","废沐垢首，尘肤败裳。","如叶未秋，虐使萎黄。","自兹以往，夕寝旦觉。","角雀谢穿，筐梅罢摽。","卷娄虽膻，理不乐蚁。","矧巳肉矣，曷感而蛾。","万有胶轕，曷可诘呵。","皇矣北帝，其将谓何。"]},{"t":"六昔","f":"古风","c":["昔朋友雉与鷮，不得巳今为枭。","昔骨肉鹅与鸭，不得巳今为鹘。","昔宗亲鹊与鹑，不得巳今为鹯。","昔官府驺与虞，不得巳今为虎。","昔乳煦汗血驹，不得巳今于莬。","昔黔苍万夫英，今视之蝇所生。"]},{"t":"雁台诗","f":"古风","c":["左江右湖，名山有台。","近阳背阴，雁为之来。","江海之大，矰缴丸矢。","待雁不来，凉空覆水。","主人有马，客亦有舟。","出自郭门，于焉遨游。","群焉以栖，人亦雁尔。","庄周为蝶，孰揆厥理。","买雁放生，入云出塞。","有问炙者，张目不对。"]},{"t":"土鲁番贡狮","f":"古风","c":["羌饭官驿，斯物不的。","官马当灾，腾于马脊。","俛啮以牙，嗜马肉炙。","四蹄裂马，如人裂帛。","兽威孔武，观者色沮。","媚此羌胡，若媚其母。","余呀以咨，羌曰余乳。","当其出穴，若婴离褓。","不见牝狮，惟见我哺。","斯言不欺，梁鸯养虎。"]},{"t":"与林玉两上人登会稽最高山山出秦望上率可五六里玉公早有来归之意因赋以止之","f":"五言古诗","c":["兹山一何为，仰首摩青云。","远去气色古，混沌傥未分。","引盻涉陕洛，毋乃隔夕曛。","中有旧社址，尚见数偶群。","短草覆井水，远松贮氛氲。","薄云在其下，犹羃高顶坟。","玄释谅能居，人世未可云。","念子觉无上，夙昔断膻荤。","焉能系不食，焉得不耕耘。","况兹值秋阳，寒气惨不昕。","未可来居斯，语子以慇勤。"]},{"t":"来晨憩广孝寺","f":"五言古诗","c":["可怜荒宇在，于焉恣游赏。","古砌伏野草，唯馀圣贤像。","巨碣指高树，御墨浮天上。","昔人不在斯，悠然引遐想。","曙入鸟初散，道寒露犹瀁。","回睇高山岑，翻然策筇杖。"]},{"t":"登秦望山","f":"五言古诗","c":["素情忻晏游，硕人事永矢。","上此万仞山，复沿北溪水。","顾瞻江海流，神去苍茫里。","后峰千里来，旁嶂两川起。","往昔窗中翠，今兹巅上视。","佳哉是观游，吾乡亦信矣。"]},{"t":"沿秦望溪水","f":"五言律诗","c":["流水澄若无，溪鱼宛游空。","磊磊聚圆石，澹荡偏能工。","高写象山曲，伏响回草中。","何朝饮麋鹿，蹄踪去难穷。"]},{"t":"秦望山东南下折有峰紫铁色错竖似花蕊土人呼雄鹅突余赠名花蕊峰","f":"五言古诗","c":["错如铁色紫，出土几千古。","寒空蕊尚繁，秋水莲难吐。","刻削差可拟，带插不添妩。","宛如齿龃龉，张吻讼所苦。","千秋献组绣，名号未得主。","直少让中岑，他山视应久。","借言花蕊峰，来春开何处。"]},{"t":"海樵山人新搆二首 其一","f":"五言古诗","c":["古莽伏圆址，新搆敞方榭。","去家不百步，连山凡几架。","衡门夹栟榈，卑池注微泻。","群峰列窗牖，佳木依檐瓦。","碑碣墙垣中，阶级陂陀下。","旷霁坦以来，远暮苍然化。","亭北指夕月，高台啸清夜。","嘉宾燕屡入，丽人时或迓。","卧榻楔岩石，旁户达僧舍。","主人胡不归，樵海未云罢。","束樵溯游风，于兹焉息驾。"]},{"t":"海樵山人新搆二首 其二 曲池","f":"五言古诗","c":["浚池叠青山，山色落池里。","上栽百岁树，下周三折水。","日夕众鸟下，客至数鱼起。","助筵摘果实，开芜种芋子。","上山一以望，高城正东迤。","波漾堂壁瑩，野阔登览美。","羡子善结架，多在聚景址。","彼亭既孤绝，兹地何旷尔。"]},{"t":"读庄子","f":"五言律诗","c":["庄周轻死生，旷达古无比。","何为数论量，生死反大事。","乃知无言者，莫得窥其际。","身没名不传，此中有高士。"]},{"t":"海上曲 其一","f":"五言古诗","c":["雪隐城月高，使君梯楼坐。","县绠讯谍士，但自苦城破。","问贼一何多，数百馀七个。","长矛三十六，虚弓七无笴。","腰刀八无馀，徒牛相右左。","转战路千里，百涉一无舸。","发卒三千人，将吏密如果。","贼来如无人，猝至使君下。"]},{"t":"海上曲 其二","f":"五言古诗","c":["暇日弃筹策，卒卒相束手。","四疆险何限，但阻孤城守。","旷野独匪民，弃之如弃草。","城市有一夫，谁不如木偶。","长立睥睨问，尽日不得溲。","朝餐雪没胫，夜卧风吹肘。","彼亦何人斯，炙肉方进酒。"]},{"t":"日暮进帆富春山","f":"五言古诗","c":["日暮帆重征，江阔眇无度。","峰翠逐岸来，树干参天去。","千里始此行，一日即羁旅。","石濑驶清磷，雪壑耸残素。","回睇吴山岑，苍苍眇烟雾。"]},{"t":"发严州舍舟登陆纵步十五里憩山麓丛榛远","f":"五言古诗","c":["乘舟坐无聊，遵途岸转杳。","急流赴海驰，怪石横江倒。","仰睇崟崎侧，惟见苍翠矫。","覆莽映赭壁，枝弱不胜鸟。","县崖窄可步，聚缆密如筱。","舟子勿前征，前路烟生草。"]},{"t":"将至兰溪夜宿沙浦","f":"五言律诗","c":["中夜依水泽，羁愁不可控。","远火澹冥壁，月与江波动。","寂野闻籁微，单衾觉寒重。","托踪蒲稗根，身共鸥凫梦。"]},{"t":"早发仙霞岭","f":"五言古诗","c":["披衣陟崇冈，日中下未已。","雄伟奠两都，喷薄走千里。","百折翠随人，一望寒生眦。","高卑互无穷，参差错难理。","蔓草结层冰，乔木秀县藟。","昼餐就村肆，小结依崖址。","去壑知几重，刳竿引涧水。","回视高峡巅，鸟飞不得比。"]},{"t":"自浦城进延平","f":"五言古诗","c":["溪山孕铁英，怪石穿水黑。","马齿漱寒流，冶火融初滴。","方艇走石罅，白日飞霹雳。","操舟信有神，出入坦然适。","以知庖丁者，游刃有馀历。","循理称达人，险难亦何戚。"]},{"t":"夜宿丘园乔木蔽天大者几十抱复有修藤数十寻县络溪渚","f":"五言律诗","c":["老树拿空云，长藤网溪翠。","碧火冷枯根，前山友精祟。","或为道士服，月明对人语。","幸勿相猜嫌，夜来谈客旅。"]},{"t":"湆澹滩","f":"五言古诗","c":["黑鳌穴地出，噀沫从天下。","春雪跌深潭，惊雷迸铁罅。","回思身所经，险怪几日夜。","老石万片焦，飞湍千里射。","药又窥绿渊，人命轻一诧。","或似鼓太冶，青铜沸将泻。","女娲撒馀砾，顽查搅不化。","念彼既怃然，值兹瓩柯讶。","姮桨起沈舟，凸字捩深窊。","因之误丝发，长与世人谢。","浪怒一何愚，终古不得罢。","有时搏阴飙，寒色惨朱夏。","借言吕梁叟，何时咨閒暇。","余虽愧达人，笑对成一嚇。"]},{"t":"武夷道士示予魏王子骞蜕首见紫气","f":"五言古诗","c":["不死者巳去，死者留人间。","骨骸自何夕，飞置山之颠。","取视始伊谁，县绠月屡牵。","而不如馀魄，安卧攒青莲。","道士苦斯役，留函阁高椽。","过客好奇异，启阅请自便。","兹物真仙灵，磊磊黄琅坚。","高顶泥丸宫，紫气犹一弦。","晦明准天时，白黑互纠缠。","胡为黄冠流，示人祸福先。","为予而变易，无乃劳子骞。","玉蕴山色辉，斯理良自然。"]},{"t":"十八日再观潮于党山","f":"五言古诗","c":["秋水自生幻，海若安措手。","惊雷砑雪狮，万首敢先后。","山窥本避濡，俄惊足下吼。","老壁拍波尘，千仞落衣袖。","望穷不见外，潋滟明灭久。","人天俨未消，劫火烧宇宙。","往昔每一凭，恐怖经句昼。","那知迫视怪，其怖应不朽。","岂惟我恐怖，天地亦应有。","景往目既迁，恐怖亦却走。"]},{"t":"萧荷花祠","f":"五言古诗","c":["荷花一夕凋，万里秋无色。","独遗花烈芳，千秋袭陂泽。","扬舲溯大湖，风紧日巳夕。","水鸟习旧栖，戢羽茭菰白。","吊古解维舟，去岸不盈尺。","秉烛褰绣帷，金翘俨宫额。","烛灭飒然中，神爽凛孤魄。","念此芒吻微，奚啻雄虺索。","岂无冶容膏，贞肌以为臛。","念兹不能忘，惆怅至明发。"]},{"t":"送明教往上海","f":"五言古诗","c":["玩雪东门家，天寒雪正下。","繁林积素花，群山映檐瓦。","杯至不得休，语密不可罢。","鸟集池树颠，色暝天欲夜。","顾予同心人，而有太息者。","云我为道谋，安得与君舍。","余为重解疏，敛襟向前谢。","超言虽遣累，离绪难释挂。","驾言春阳初，那得便徂夏。","执手归路中，冲寒为君话。"]},{"t":"寄善画葛君","f":"五言古诗","c":["展箑不尽规，墨色鲜于洗。","细图万壑云，寄我青山里。","感之不能忘，聊寄短篇耳。"]},{"t":"古山篇赠余君","f":"五言律诗","c":["余君本今人，而有怀古思。","三年卧白云，一醉抚流水。","握管扫素笺，闭门谢时事。","懒与今人交，自号古山子。"]},{"t":"赠陈君","f":"五言古诗","c":["珍木无弱羽，广川饶劲鳞。","皇都郁嵯峨，多士如繁星。","陈君在乡曲，少小驰芳声。","去我三百里，可望不可亲。","昨予志广览，自越之燕京。","见君长安道，一问知姓名。","却复讯动止，握手为予陈。","自受相公知，忽忽复几春。","一朝去乡校，今作太学生。","言温动有礼，志壮气自信。","晢颜口若海，丰下而长身。","再往论文史，终夕如倒囷。","藻思蔚以妍，俨与骨相并。","王良御八骏，技绝物有神。","一日骛千里，安得留其行。","念予复南去，揽策临修程。","小见伺越鸟，秪入枪榆群。","思君不能置，短篇陈素情。"]},{"t":"戒舞智","f":"五言古诗","c":["富非圣所却，贫乃士之常。","华屋非不美，环堵庸何伤。","多才戒舞智，善闭靡不彰。","舞智向愚者，弄偶于偶场。","偶月不知弄，尔弄何所偿。","舞智向智者，譬以光照光。","彼光不受照，尔照何由扬。","舞智两不售，不舞两不妨。","请君听予言，作善降百祥。"]},{"t":"寄彬中","f":"五言古诗","c":["邺下老韦布，能活刀下人。","鲁连剧排难，安得专其名。","不见申包子，含悽哭秦庭。","万马度关陇，救郢却吴军。","侧闻同心人，急难等赴焚。","秦师不可出，大义凛巳明。","栽倾本莫致，安命以为贞。"]},{"t":"答和公旦","f":"五言古诗","c":["高垣沼我驱，棘刺长如荻。","松柏年十寸，至今长五尺。","一朝锤笼藩，小鶠决蓬翟。","忽逢东来鸿，相煦以双翼。","逝焉渺长江，别子当几日。","不能偕我飞，一顾一悲呖。"]},{"t":"雪二首 其二","f":"五言律诗","c":["屋腐隙西椽，密雪夜如织。","朝窥床簟头，白糁高一尺。","侧身不敢摇，寒笼戢僵翼。","伴侣同苦辛，何从乞浆食。"]},{"t":"寄王子心葵","f":"五言律诗","c":["葵花似君心，向日解违阴。","葵叶我所愧，有足不能卫。","与君夙相知，把葵吴山时。","今日相思处，南冠絷楚傫。"]},{"t":"寄陶工部","f":"五言古诗","c":["短剑在匣中，秋水莲花芒。","芒色岂不好，终为人所防。","所贵金玉资，含辉有馀光。","谅哉工部君，璠瑜映明堂。","熏风动九夏，鸣音来锵锵。","至宝吐洪亮，不特华泽芳。","沈思不能寐，揽衣视河梁。"]},{"t":"筠石篇","f":"五言古诗","c":["片石插寒塘，泠泠箭竹黄。","谁提数寸管，坐到一秋长。","我亦耽清致，传闻今几霜。","翻飞乏羽翼，那得到君旁。","想见莓苔绿，坐令毛发苍。","叠膝嘉肺中，望断云根觞。","令我操题处，青棘披孤墙。","日影淡无色，十月梅早芳。","欲折以寄远，无此长臂攘。","料理竹下人，应少寒枝香。"]},{"t":"蒋扶沟公诗","f":"五言古诗","c":["伯氏颇好道，终岁事修服。","道上逢异人，髭须洒林竹。","修礼重致问，德音美如玉。","扣之转微茫，焦螟游广漠。","冀得长奉侍，双飞向王屋。","人命安可期，天犹互寒燠。","念别正徂暑，墓草巳更绿。","瀼瀼日中霜，亭亭风际木。","逢师苦不早，炼摄总成哭。"]},{"t":"柳浪堤楚颂亭二首为溧阳史氏题 其一","f":"五言律诗","c":["夹岸千章柳，青春翠浪浮。","如将曲池水，共作绕堤流。","长蛇偃青荫，水鸟悦芳柔。","试于垂缕处，一系木兰舟。"]},{"t":"柳浪堤楚颂亭二首为溧阳史氏题 其二","f":"五言律诗","c":["屈子颂匪今，轼也志空寓。","千载伊谁子，后皇锡嘉树。","曾剡剌崇檐，青黄揉广阼。","永与兹亭留，不迁乃其素。"]},{"t":"昨见","f":"五言古诗","c":["昨见食偶者，析偶以为薪。","零星椎股脾，寸尺移居臀。","心胸本无有，斧亦集其垠。","辟彼偃师工，立剖瞬者身。","彼偃师者析，庸以免其嗔。","免嗔岂得巳，为薪岂无榛。","何忘食女德，辛苦二十春。","食偶者答言，当其为偶辰。","我即薪视尔，尔自不我知，我志如此矣。","我欲尔也歌，尔即轩厥舐。","我欲尔也舞，尔即蹈厥趾。","我怒尔唇阖，我笑尔唇启。","凡我所控提，尔即如我自。","尔自不觉知，昧我蓄薪志。"]},{"t":"偶也","f":"五言古诗","c":["偶也难亿诈，为鱼岂无知。","假令鱼为偶，亦安避薪为。","此亦岂无谓，听我歌此词。","当鱼在沼时，沼阔不容坻。","沼既不容坻，研复朝洗之。","洗多墨岂少，墨积盈沼池。","从此再三洗，喁噞恒在兹。","唇外无滴漪，缝唇墨即入，何况相沬唏。","君在大气中，塞海皆氛霾。","君今口与鼻，能免不埃噫。","苏武在虏中，磕头皆羊羝。","死生凭羝辈，起处亦羝隈。","岂惟起处隈，嬉宁谢羝嬉。","君侪人如此，而况我也鱼。","我闻君里谚，契我鱼也志。","非伴情所知，事急随则随。"]},{"t":"狐粉","f":"五言古诗","c":["狐妖幻黛粉，窈窕美佳人。","慕予且宜笑，情好缘相亲。","物与人异调，孰识伪与真。","答子以慇勤，靡曲匪好音。","魅也一朝败，情歇音则存。","我欲灰兹音，匪乏炀与薪。","譬以宝贻魅，宝既不我存。","何由夺而烬，存此贻魅曲，以不磨魅愆。"]},{"t":"补屋","f":"五言古诗","c":["僦居巳六年，瓦豁绽椽缝。","每当雨雪时，举族集盆瓮。","微溜方度楣，骤响忽穿栋。","有如淋潦辰，米麦决筛孔。","五月候作梅，一雨接芒种。","菌耳花箧衣，烂书揭不动。","樵子不上山，薪炭贵如矿。","生平好楼居，值此念愈踊。","数椽犹僦人，安得峻栌栱。","买瓦费百钱，巳觉倒囊笼。","命工勿多摊，擘艾聊救痛。"]},{"t":"作松棚","f":"五言古诗","c":["种松六万馀，千五百株活。","长养二十年，大者仅如括。","西斋落日多，六月苦炎热。","邻园树木稀，遮翳不可得。","顾言种树资，求用此时节。","命儿召两佣，伐干并其鬣。","干以需柱梁，鬣以备周匝。","四垂慎勿甲，凉风任超越。","时移一丈板，独踞文竹兀。","伸纸二丈馀，举墨陡一泼。","左盘持蛑螯，右罍把饕餮。","挂衣梅叶梢，绿阴洒晞发。"]},{"t":"理葡萄","f":"五言古诗","c":["去冬雪作殃，无物不冻死。","橘柚断衢州，松柏亦多痹。","园有月支藤，盘屈四五咫。","结实苦不多，一斛有馀委。","迨其堪落时，丸九挂珰水。","一日十挈竿，与鸟争啖舐。","将以馈邻翁，窃恐哂微细。","欲以付果坊，不足一餐费。","幽之瓶盎间，浆溃败其脆。","渴夜艰茶汤，暂可灌消肺。","比者理旧须，应手落枯瘁。","及至更提携，僵挭忽断碎。","如人两手足，而痿其一臂。","支干既以孤，收穫焉可倍。","夏景苦桑榆，聊以障西坠。"]},{"t":"鼍矶研","f":"五言古诗","c":["向者宝端歙，近复珍鼍矶。","在海感蛟蜃，文理多怪奇。","白者为雪浪，星者黄金泥。","碎者银作砂，角者丝缠犀。","举手摸其理，索索铓响飞。","分符军石乡，庸以鏖隃麋。","曩者辱新乐，远寄青州来。","一夕忽失守，仍召顽滑资。","一字十研磨，一行百推移。","淹此斫阵马，羁控不得驰。","乃者董文学，匣有方尺储。","举以为我赠，与新乐不殊。"]},{"t":"问军中之系于国用","f":"五言古诗","c":["吾宗异秦赢，秉德嗜仁义。","绵延值盛明，仩版颇齿齿。","先人秉鱼须，联蝉及诸季。","列秩下大夫，往往有三四。","迨及贤科书，至今时一缀。","万木有荣凋，一体互强脆。","屈指四纪来，挛痹剧一臂。","耕者鬻其锄，贾者降为侩。","士者无一人，慵者倚而待。","饱者幸免饥，饥者幸未丏。","至论胤嗣间，十室九蜂虿。","墓寝蒸礿时，顾影兀孤介。","甚者乏继承，馁鬼满蒿薤。","余虽有两儿，性颇仇简册。","饮牛未渴辰，按项不能俛。","缘兹伤后昆，思欲谱先代。","念彼从戎人，蔓远瓜尚带。","况值用也来，举扣其大槩。","彼衰更倍兹，掷笔为一慨。"]},{"t":"避暑豁然堂大雨","f":"五言古诗","c":["梅候苦歊蒸，幸得五日霁。","凉风驱湿魑，奏功未全济。","眷言高山颠，有堂敞西翠。","松篁作籁竽，萧飒爽神智。","乃偕二三子，挂絺于其地。","买酒穿市中，炮鳖腥道器。","止取醉饱为，安能谨趋避。","袒跣择树依，叫号枕砖睡。","郡邑迫东厢，狂来忘逻逮。","冉冉日将倾，理邸方即迈。","雷雨自西来，初尚杂晴蜺。","一言未及终，振瓦落檐外。","冲风捎健鹘，寸进得丈退。","高景殊卑观，窜鸟在眉际。","本言逃炎苛，翻令咏奇致。","百事兼熊鱼，往往非著意。"]},{"t":"哀骆怀远公验词","f":"五言古诗","c":["怀远好诗什，近体有佳声。","迟余去五泄，深衣远相迎。","长身而瘦颊，自有山泽清。","命酒不停斝，酒罢有馀情。","迨予归来后，往往问寝兴。","彘肩腊松火，柿缕霜秋晴。","寄此远筐篚，兼致倡与赓。","何时卧狸首，闻之使心惊。","道远不得往，逋此泉下羹。"]},{"t":"野蚕","f":"五言古诗","c":["越桑虽云盛，不及吴中繁。","越女卖钗钏，仅可完蚕山。","如斯苦拯救，良亦可悯怜。","如何野蚕种，孳息多今年。","曳丝满郊郭，食叶留其觔。","叶叶如虫网，枝枝垂钓缗。","涎缕无所用，胶衣黏头巾。","过者苦拂拭，桑女交攒颦。","提筐往西园，空手归东邻。","即欲贸钗珥，有钱无桑村。","嗟彼机上杼，秋来鲜闻声。","匪来犹可说，国输良有程。","衣食无二理，蠹衣与食均。","尝闻捕蝗法，及此同瘗焚。"]},{"t":"范母诗","f":"五言古诗","c":["秉节三十年，万有二千夕。","一夕改霜心，晓镜换妆额。","范母二十二，独居在罗幕。","五十七乃亡，天长日几落。","独持一寸冰，万古胶夜席。","当夏不得融，何况秋霜白。"]},{"t":"子效索赠其两叔","f":"五言律诗","c":["劳子为我言，翁去不复活。","骨魄既巳寒，生事亦不热。","多我诸父慈，视侄等儿列。","时时惠釜钟，厨中作麋啜。"]},{"t":"送章蒲圻之官","f":"五言律诗","c":["倾盖语日斜，肉风吹两窍。","惜哉越鸡翰，遇鹄不能抱。","眷言激奖私，忽驾就远道。","尚矣漆园心，为吏不敢傲。"]},{"t":"夜雨偕友人进舟云门","f":"五言古诗","c":["夜影叠中流，进舟篁竹浦。","鸣雨来断雷，山云湿可谱。","及岸沿黑堤，攫猪复愁虎。","燎火得缁徒，怖馀涩言语。","芋垆聊炙衣，一笑赖尊俎。"]},{"t":"天目狮子岩","f":"五言古诗","c":["我昔闻真人，言修不死身。","选地满天下，与鬼争青城。","一岫插天日，宛尔怒猊狞。","老释据其口，黄冠复来争。","黄冠匪他人，云是真人孙。","聃昙本上圣，高道超沈冥。","说教虽异轨，俱以退让名。","区区百尺铁，青红抺秋荣。","龙女买色线，一夕绣可成。","胡为两龙象，角吻同苍蝇。","赋此觉蚩蚩，鉴之慎勿听。"]},{"t":"鹰","f":"古风","c":["?嗽讥奇才，千金买辽海。","铁翮睒秋空，鴐鹅百回败。","云中作战场，韩彭鼓天外。"]},{"t":"马","f":"五言古诗","c":["谁家连钱骢，㧙拨黄尘起。","千里一饭间，九州能有几。","健见不得骑，泪落青刍里。"]},{"t":"犬","f":"五言古诗","c":["少年猎平原，左卢右宋鹊。","兔起鹘落迟，一顾先巳搏。","但莫空中山，前头有汤镬。"]},{"t":"狸","f":"五言古诗","c":["狸虽一尺躯，猛气制十里。","有时怒一号，无牙堕梁死。","安得此辈来，坐吾书匣底。"]},{"t":"丽人","f":"五言古诗","c":["何处行云去，逍遥出洞房。","月里傥并色，镜中无此妆。","所思望不见，稿袂日边扬。"]},{"t":"才子","f":"五言古诗","c":["佩笔不须长，高唐侍楚王。","红蘅椠边出，白雪口中翔。","杀青供不及，一夜白潇湘。"]},{"t":"游大尖","f":"五言律诗","c":["万松滴千山，妙翠不可染。","割取武陵源，固是天所遣。","秦人迹无有，云中叫鸡犬。","夜泊渔舟来，下山寻不见。"]},{"t":"空上人常住少林索作于菊下","f":"五言律诗","c":["相逢菊花下，相映菩提光。","试问少林壁，穿云几许长。","指月莫盻手，掷拂閒挂墙。","睡鼾微作吼，狮子一时降。"]},{"t":"宗孙有别字柱南者索赋","f":"五言古诗","c":["天柱插南云，孤城满苍翠。","小凤读书馀，内屐窥粉雉。","大鱼作鸟飞，风穿万林鼻。","舍北以图南，物与人意会。","念彼共工额，幸不触斯际。","不然小折伤，恐烦太皞妹。","小凤顾予言，补天吾掉臂。"]},{"t":"鹳攫鹊雏鹰党翻然来救","f":"五言古诗","c":["水鸟修其胫，插彼茄菰泽。","俛咮啄虾鱼，深不下三尺。","况乃嗉中仓，可内寸鳞百。","江海饶此州，何往不充噱。","雄鹊知乳雌，作室高树末。","三月始罢斤，是予亲所炙。","长胫一何饕，掠雏剽其宅。","叔仲两三头，自窜宁顾伯。","顾鹊翁与母，叫噪徒额额。","苍鹰等路人，与鹊少平日。","不作乡邻看，被缨救其格。","特恐李阳拳，难齑鸣垤额。","盛邀爽鸠雄，并是夷门客。","朱亥袖铁锥，侯嬴出奇略。","左右信陵军，一举解赵壁。","五国破大秦，九合成小白。","义高诚足怜，多算亦何硕。","磔虺黑柏颠，独奋少掎角。","犹烦拾遗歌，不朽侠徒迹。","三复鸱鸮诗，白日为侬黑。"]},{"t":"感鹰活鹊雏事因忆曩卫衙梓巢鹳父死于弩顷之众拥一雄来匹其母母哀鸣百拒之雄却尽啄杀其四雏母益哀顿以死群凶乃挟其雄逸去","f":"五言古诗","c":["鹳嫠止一时，古语亮匪诬。","戟门巢梓者，狭斜挺罗敷。","少年系青丝，蹶张戎侯衙。","胡不自长守，转殪雪色颅。","乃向琴瑟杪，落此贞女夫。","群雄太无赖，挟鳏匹未都。","有如恶媒姆，送赘填门闾。","借衣盛綷蔡，叫呶倾百壶。","玩习为故事，指雁翻阔迂。","孰知狭斜内，而有罗大家。","贼雄杀黄口，希以威怖图。","殉夫义可族，何计收其孥。","此事去巳久，三纪颇有馀。","其时裂肝胆，狂走日夜呼。","安得毛挚侠，似此鹰活雏。","弇州隔几海，有物喑高梧。"]},{"t":"设为鱼虾所诘","f":"五言古诗","c":["啄鹊憎大鸟，无怪吾子然。","从臾饱虾鱼，子意一何偏。","鳞即贱于裸，于羽何择焉。","盛冬水如石，胶鬣不得旋。","孕肠急鞔鼓，张目不得眠。","茭菰牙始白，桃花涨春田。","熨块出累琐，多死渔者筌。","鳞褓及鹊鷇，较估谁艰难。","矧兹网罟酷，百倍鸟有鹯。","雏攫子不许，鳞烂子许旃。","乃乖漆园理，夺蚁与乌鸢。","等为一盗耳，何猛此彼宽。","窃东子则许，窃西子拘钳。","波臣诘如此，而我难为言。","众生递吞噬，此业何时捐。","西方古先生，解破万壁坚。","龙门傥罢跃，飞去好相参。","汝或未即去，我姑代彼宣。","三戒严重杀，五净肉亦权。","鹏饱六月息，孝先腹便便。"]},{"t":"天竺僧","f":"古风","c":["扬帆三竺涘，弭锡五羊城。","黑人初以涉，琉球次所经。","波弧十五兆，日矢九千嬴。","人疑鹏六息，彼视蠖一信。","衍既隘九土，师亦眇八垠。","片楮画大卵，沃焦灙孤萍。","劈芥内阎浮，粉尘陋虚邻。","铁簏卧龙象，银澜恬蛟鲸。","梵呗只字握，江海百谷臣。","云胡白?底，乃有赤篆文。","象胥几何译，龙树鲜恚嗔。","挂履度葱岭，趺湫蜕岩云。","投夹蕺南寺，及偕领西昆。","漏沙自箭准，圣水他涛奔。","有为乃复尔，无量何由臻。","相色示戏幻，接引讵劳尘。","白马幸维寺，黄龙未演轮。","薄痾阻问讯，拟待桃花春。"]},{"t":"烦吴伯子治墓堂","f":"五言古诗","c":["火瘗世曰凶，水封岂佳卜。","两徒踰五纪，先魄偃幽瀑。","多子为我更，我蘧往京国。","买石百尺馀，托子安墓卓。","子冗办未遑，我归上冢哭。","鹅鲂设未已，老雅掠豭肉。","候果墓旁儿，指告蚁上烛。","草设无威仪，人怠物不肃。","坐此无欢期，改燧十二木。","昨者卖字钱，募工可五六。","仍以烦吾子，歇百了一役。"]},{"t":"旱祷十七韵次陈长公","f":"五言古诗","c":["旱魃虐以猖，商羊乃深避。","云汉夜昭回，遵彼槁条肄。","绝意豕涉波，必死蚌持翠。","蜥蜴山泽穷，猳豨屠贾致。","黄缁递呗诅，玄冥等聋瞆。","如闻柴望禋，感通有精义。","洪畴儆恒阳，繁露肃常馈。","商林沃乃深，秦天岂终醉。","坛今邻阊阖，阍亦撤幽閟。","雷吏绿章封，宁有不达字。","油然未崇朝，沛尔倏濡澻。","虎猫效蜡劳，丰隆詟群祟。","连臂解桔槔，极目醒枯悴。","歌帝悦穰穰，报典虔惴惴。","窭人无农忧，连夕美凉寐。","农穫譬中行，美寐狷其次。","籴贱胜作农，先生有酒食。"]},{"t":"陈长公饷日铸茶瓦窑港银鱼白下法炮巨鳖夜酌深谈次其韵","f":"五言古诗","c":["日铸标枪芽，月团捲旗避。","纤甲赭旧条，柔针绿新肄。","瓦窑五寸银，脊色偃微翠。","双裙谑可谈，九肋底能致。","伯云准食医，治以聪我瞆。","斟炮法内京，酌长非外义。","珍此五侯鲭，惭余十浆馈。","主既唱无归，客顾称未醉。","阶虫先秋吟，径竹上霄閟。","叔夜寂鸣琴，子云寥问字。","待扣匪洪钟，立涸是盈澻。","泗鼎旷沈沦，神奸恣精祟。","伍员终鸱夷，三闾竟憔悴。","白驹返谷空，黄鸟临穴惴。","千古究何穷，再烛不能寐。","曲礼问更端，梵诠编复次。","伯树既巳空，吾出吾箪食。"]},{"t":"修拄杖首修发网胶漏磁壶及哥窑瓯某亦病只耳聋次前韵","f":"五言古诗","c":["猾器幸自残，黠繇巧规避。","辟诸鞅掌人，彼逸此独肄。","一竹楚啼赪，双磁越窑翠。","物非人易求，道远我难致。","无丞有重听，发复弥党瞆。","约发无纪纲，晨帐缺宋义。","握粟付騣工，宁减朝食馈。","讵意彼騣者，无往不辞醉。","犏缨高箱尘，马尾枯橐閟。","踉蹡攒八针，邀呼输四字。","浪言伏卵清，竟涤下流澻。","栉束起鬔松，嘲呼免魑祟。","竹返磁亦归，黥补色终悴。","注瓦智靡昏，捧玉神若惴。","甑破视何益，囊空卧安寐。","辱即宠为下，辟乃色最次。","屠门盛豕交，宁为爱而食。"]},{"t":"旱甚久不应祷再追前韵","f":"五言古诗","c":["祝融党羲轮，玄冥引车避。","课穷燧人苏，徵及枣杏肄。","辙鲋槁厥赪，坛豭秃其翠。","走索华阳逋，沈瘦永难致。","竟辜烧尾恩，翻仇听角聩。","玩愒如不闻，旷瘝秉何义。","余斋废酒沽，朋祭阻肉馈。","方嗤泽畔醒，敢思河朔醉。","承风独有雌，纳月幸无閟。","哽哽向隅悲，咄咄作空字。","朝筵闻客云，宵锄盗邻澻。","云密不东郊，蝀孽复西祟。","昨孑凛今靡，旧殍理新悴。","渐少墦乞骄，而多褐大惴。","待尽歌有爰，无吪祈尚寐。","感此疾威旻，遣以竞病食。"]},{"t":"寄京中友人","f":"五言古诗","c":["寒风夜中起，游子朝作客。","河流一尺冰，屋瓦三寸雪。","人言今岁冷，连岁屡觉热。","何事古江南，翻为今塞北。","君把如与鞦，触手冷于铁。","此时山中人，覆絮败毛褐。","欲寄寄莫由，此意共谁说。"]},{"t":"送王雪渔北上","f":"五言古诗","c":["淮阴所佩剑，不审值何许。","佩剑以钓鱼，于义亦何取。","一日几垂竿，竿竿可几鲤。","乃至捐漂厨，庸以益渔腑。","我取鱼之剑，聊略为渔估。","即非百金资，可易数月黍。","渔也智绝伦，何独昧兹举。","肠饥乞可为，剑去何所仗。","之楚复之汉，渔并仗剑往。","可以负渔竿，踉蹡见刘项。","猝办恐后时，载质先出疆。","王郎不钓鱼，故亦无竿饵。","闻郎所持竿，贯以山中紫。","毫长一寸馀，竿只五寸止。","居则南狎越，行则北声燕。","淮阴剑三尺，郎剑五寸县。","归来报千金，漂母是何人。","封侯剑不取，却取钧竿亲。"]},{"t":"吴季子饷我细腰壶芦石上芝二首 其一","f":"五言古诗","c":["葫芦老细腰，乃似细腰女。","即令楚宫来，今亦不堪舞。","我闻方外医，庸以盛药丸。","梧子及鱼眼，可容百万千。","老圃畜蔬种，亦够一顷田。","我既丑医帐，亦复少蔬阡。","拟挂于扶老，支吾五岳颠。","心强足不健，终岁掩帐眠。","止取作蒸鹅，聊以谑客涎。"]},{"t":"吴季子饷我细腰壶芦石上芝二首 其二","f":"五言古诗","c":["芝朵虽不润，芝色坚且古。","根须络拳石，如筋蚀臂股。","络古不复脱，初芽宁藉土。","石色既巳黄，芝紫亦稍妩。","有如意魁梧，状貌乃妇女。","谷城吊老人，泪下潸如雨。","置我笔研间，长与留侯语。"]},{"t":"大寒岭啖新胡桃频婆诸果","f":"五言古诗","c":["天险既巳异，地产应亦殊。","胡桃及平波，朱碧明椒隅。","入夏而徂秋，叶翠尚不渝。","但少鸟与雀，而多嬴与驴。","易水非不迩，滦河不为迂。","但求一寸鳞，如海水猿狙。","遥想燕太子，食客焉得鱼。","以知荆高徒，日嚼羊与猪。","猛风增食肉，嗔愤易睢盱。","慷慨赴秦庭，不复顾其馀。","乃缘谋略短，岂真剑术疏。","舞阳一竖耳，何乃与之俱。","哀哉樊将军，空割一只颅。","国有千乘大，能用王可图。","乃恃五寸铁，为计亦何愚。"]},{"t":"湘竹一妙管付截坏其顶文","f":"五言古诗","c":["武侯败街亭，马谡违节制。","兵颖迥不同，大小俱是事。","兹管湘中来，百中其一耳。","有如玳瑁鱼，脑血径弹子。","又如鸾与鹤，顶发杨梅紫。","全体匪不华，独此犹觉异。","讵可拘尺寸，但须存纹绮。","畏炎不得行，付托昧厥旨。","举刀一铿然，颠落不可止。","持归以复予，鱼鹤不成理。","对之一捧腹，削圆方竹比。"]},{"t":"口中","f":"五言古诗","c":["口中万吞吐，莫道一俗字。","刍豢离喙唇，冰雪满牙齿。","身中百所为，亦莫涉一俗。","但为鸾鹤翩，暮即云霞宿。","有斤不削人，有绳不直木。","淤泥填大千，荷叶自柚绿。","从此戒尔后，慎莫蹈往覆。","有如乖教言，断舌肘其足。"]},{"t":"驺虞","f":"古风","c":["驺虞生猛虎，凤凰产枭鸷。","二圣有朱均，太虚亦?彗。","纤纤妙肤理，盎然长疣赘。","梗楠固鸿材，钟斛瘿其际。","橘柚匪不甘，豪猬匝芒刺。","美恶一何殊，胎孕乃非二。","越鸡伏鹄卵，变之苦无计。","果嬴秉何神，蜎蠋乃能似。"]},{"t":"昙阳 其一","f":"五言古诗","c":["昙阳一髻左，道人三朵花。","谁云只是你，安知不是我。","大海彻岸冰，小生没处躲。"]},{"t":"昙阳 其二","f":"五言古诗","c":["闻道居绵竹，看来幻落花。","团团轮北斗，处处种西瓜。","遍地皆祗树，何方不落伽。"]},{"t":"昙阳 其三","f":"五言古诗","c":["无鼻无眼孔，有头有尾巴。","蛟龙大蝘蜓，蝌蚪小虾蟆。","一结生百结，百些无一些。"]},{"t":"昙阳 其四","f":"五言古诗","c":["将军骑健马，稚子打慈鸦。","各奔前程路，都来暮鼓衙。","同舟迷敌国，蓦面认通家。"]},{"t":"昙阳 其五","f":"五言古诗","c":["何事移天竺，居然在太仓。","善哉听白佛，梦巳熟黄粱。","托钵求朝饭，敲锣卖夜糖。"]},{"t":"昙阳 其六","f":"五言古诗","c":["明知骑竹凤，还道媚妖蛇。","可恕者落帽，难饶者脱靴。","一灵生灭巳，百吠是非耶。"]},{"t":"昙阳 其七","f":"五言古诗","c":["男女兼黄白，丁宁嘱再三。","特将铁扫帚，痛握世媱贪。","窃幸师与我，不异青与蓝。"]},{"t":"昙阳 其八","f":"五言古诗","c":["火龙长九九，泥蛇八十一。","一物而两呼，两呼只一物。","将泥认外蛇，见蜂硬割蜜。"]},{"t":"昙阳 其九","f":"五言古诗","c":["好人不在世，恶人磨世尊。","聪明管自巳，阘冗任乾坤。","遗命云闻帝，多应是嚇人。"]},{"t":"昙阳 其十","f":"古风","c":["狮子吼未歇，蝴蝶霎巳来。","众生自矇?，抵死致疑猜。","认贼由他去，谤佛何为哉。"]},{"t":"赠吕正宾长篇","f":"七言古诗","c":["海气扑城城不守，倭奴夜进金山口。","铜签半傅鸊鹈膏，刀血斜凝紫花绣。","天生吕生眉采竖，别却家门守城去。","独携大胆出吴关，铁皮双裹青檀树。","楼中唱罢酒半曛，倒著儒冠高佛云。","从游泮水践绳墨，却嫌去采青春芹。","吕生固自有奇气，学敌万人非所志。","天姥中峰翠色微，石榻斜支读书处。"]},{"t":"三茅观观潮","f":"七言古诗","c":["黄幡绣字金铃重，仙人夜语骑青凤。","宝树攒攒摇绿枝，海门数点潮头动。","海神罢舞回腰窄，天地有身存不得。","谁将练带括秋空，谁将古慨量春雪。","黑鳌戴地几万年，昼夜一身神血乾。","升沉不守瞬息事，人间白浪今如此。","白日高高惨不光，冷虹随日萦城隍。","城中那得知城外，却疑寒色来何方。","鹿园草长文殊死，狮子随人吼祇树。","吴山石头坐秋风，带着高冠拂云雾。"]},{"t":"雪","f":"七言古诗","c":["暮天宝色珊瑚紫，海气结云云不蕊。","瑶阙重关金锁寒，枕席无欢帝妃死。","百神走马散曹吏，马蹄踏空神各视。","天孙纤手裁素罗，穗帐横施九万里。","鲛人丝色光海波，海犀输织一万驮。","神人罛赙不足用，长鬟散缟呼诸娥。","世人不解天上苦，罗帐锦筝围日暮。","换取貂襕拂玉鞍，起向山南射黄兔。"]},{"t":"万里比邻篇赠嘉则","f":"七言古诗","c":["白藤织笈春花密，青袍剪水波纹湿。","出门寸步即天涯，帏底牵衣弦正急。","关山断路不断云，吴刀割水那得分。","章华杨柳弄旧色，何地却少春申君。","人生远游须及春，青天能容七尺身。","芳草长途去万里，望望吾家随处是。"]},{"t":"述梦 其二","f":"古风","c":["跣而濯，宛如昨，罗鞋四钩閒不著。","棠梨花下踏黄泥，行踪不到栖鸳阁。"]},{"t":"今日歌","f":"七言古诗","c":["琉球佩刀光照水，三年不磨绣花紫。","换钱解向市中悬，我贵彼贱无人市。","家惟此刀颇直钱，易钱不得愁欲死。","客问此刀值几何，广州五葛飞轻雨。","及今求市不较量，但输三葛钱亦止。","千人十往九不顾，向刀长立折双趾。","一日不食良巳饥，两日不食将何以。","却走异县告长官，往日停车傥知己。","平生自有孟尝心，今日翻思门下士。"]},{"t":"送兰应可之湖州","f":"七言律诗","c":["梅黄雨霁带阴轻，送客西门驿路平。","会多忽别疑且惊，愁心应手弦凄清。","荷花镜里红侵舫，时共耽游楫徐漾。","思君苕溪若天上，空伫清歌对谁唱。"]},{"t":"题侄子家所藏双凤鸣阳画","f":"古风","c":["海水动天天欲晓，天晓日炙珊瑚老。","鲛人泣夜不得眠，早起来听凤凰叫。","梧桐百尺秋云际，竹梢覆水千年子。","一飞一宿还一鸣，百神张乐钧天启。","梧生诚亦难，凤出良不易。","愿以黄金铸梧树，莫教飞向丹山去。"]},{"t":"对明篇","f":"古风","c":["四明山，高万丈。","南为姚邑面前屏，北即新昌后门障。","新昌有客身姓吕，要与此山约为主。","尺素冯将一穴通，屋后安窗小如许。","窗中有时飒风雨，说是山灵教送与。","夜来猛虎啸一声，雄心枕畔风吹去。","长安花枝高入天，金陵有酒多如泉。","花留酒劝不肯住，归来只爱窗中眠。","窗中有书积万卷，书书尽是山灵管。","有才无命不干时，亦对山灵同一莞。","闻道去年醉采石，醉去狂来呼李白。","散发题书万竹中，腾身舞剑青天侧。","此时山灵失主人，自骑青虎寻复寻。","肉眼那知神道至，主人自识交亲临。","朅来笔端自有神，横开醉眼双作嗔。","此时墨雨添江水，此际诗花弄莫春。","莫春江水渺无边，射策封书复几年。","明珠不遇贾胡识，宝剑难酬夜色鲜。","诙谐汉庭方朔老，如闻永谢长安道。","况我今为抱拲人，虮虱移家宫絮袄。","两人曾作青春身，当时同说不同贫。","君今幸不为樊鹿，亦似蛟蟠不得申。","莲花之峰亦佳丽，君胡中道相捐弃。","邀我题诗对四明，我自贪君百壶旨。","只恐莲花嗔，四明喜，我亦付之一醉矣。"]},{"t":"继溪篇","f":"七言古诗","c":["海水必自黄河来，桃树还有桃花开。","试看万物各依种，安得蕙草生蒿莱。","龙溪吾师继溪子，点也之狂师所喜。","自家溪畔有波澜，不用远寻濂洛水。","年年春涨溪拍天，醉我溪头载酒船。","一从误落旋涡内，别却溪船三两年。"]},{"t":"北云篇","f":"七言古诗","c":["君家楼北楼子山，大椿千年去不还。","白云一片松间起，游子相望泪如雨。","殷勤夜乌莫更啼，东方日出烟生缕。"]},{"t":"楚宗室鸡将啄蚁画","f":"七言律诗","c":["锦葵窠下雄鸡白，黄蚁有翼飞终涩。","不应草叶更相遮，五寸荆轲千里隔。","王孙妙思快啖吞，马迁奇笔写鸿门。","当机对敌只如此，翻令看者飞心魂。"]},{"t":"沈刑部善梅花却付纸三丈索我杂画","f":"七言古诗","c":["长安街上尘如雾，葛布眼眼风难度。","归来扫溷索长笺，一束溪藤沈刑部。","墨浆五合饱苍蝇，刺叶藤花扫不成。","门前铜盏呼人急，却是冰儿来卖冰。","乾喉似火逢薪热，一寸入口狂烟灭。","自惭野卉不成妍，刑部梅梢如拗铁。"]},{"t":"送陈君会试","f":"七言古诗","c":["霜花作钱缀芳草，折荷送客邪溪道。","荷乾叶老障啼鸳，不及梅花弄清晓。","折却梅花赠所知，娥江东边舜江西。","封书七尺长髯客，早晚长安白马嘶。","长安白马去如云，杏花有情要逢君。","为君留却花三载，肯倩东风嫁别人。","去年君来棘墙栅，半醉不醉秋月白。","遗我海蚶颗三百，瓦沟一一瑩霜雪。","今年君马向长安，我无一丝挂君鞍。","但飞一滴相思泪，万里随风到杏园。"]},{"t":"六月七日之夕与梅君客生及诸乡里趁凉于长安街醉而称韵得片字","f":"七言律诗","c":["长安白苧风吹断，银河瑟瑟难成片。","楚人惯自唱阳春，一曲未终人巳散。","西内湖荷没鹤长，裁筒不得只闻香。","东方万瓦寒楼阁，月照金鳷琥珀黄。"]},{"t":"摩诃庵括子松下听弦上人弹琴","f":"古风","c":["括子松，知几树，黛色遥遥入云际。","上人弹琴坐其底，十指引出七条水。","松清琴妙听者寒，松叶堆翠成高山。","流涛绕殿撼铁板，狮子欲吼复不敢。","泛声忽歇浮云住，细猱一寸猿腾去。","南园玉蝶隔花听，东海金鳷乘雾语。","颖师一曲悲昌黎，我亦闻弦别鹤悽。","悟来忽问无弦旨，指鸣弦鸣须答对。","是不是，问太史。"]},{"t":"谑雪","f":"七言古诗","c":["梅花一夜窗中见，昨冬少雪春无霰。","寒来借景苦无多，窗小只须三百片。","每举枯杯对此花，只愁落尽是风沙。","谁知滕六虽无赖，亦遣残绡缟树叉。","一行分向朱门屋，误落寒酥点羊肉。","锦屏不使冻胭脂，飞絮落盐弦上扑。","四条觔急冷鹍鸡，一二时中肉作围。","岂无一笠黄茅里，僵杀岩岩一瓮齑。","初起青蘋本亦同，大王毕竟是雄风。","总令受者自分别，难道青天秉至公。"]},{"t":"白鹇诗","f":"七言古诗","c":["闰南烟雨迷青嶂，孤雌挟子飞天上。","却忆羁雄不得归，两桨深笼镜波漾。","片雪长梢向尾分，有时梦见武夷君。","山长水远无书寄，不及南飞鸿雁群。","主人为尔苦惆怅，开笼欲放非难放。","矰缴鹰鹯何处无，万里冯谁报无恙。"]},{"t":"握锥郎","f":"古风","c":["城西南，握锥郎，醉卧人家楼上床。","楼上女儿发未长，汗脱胭脂涴午妆。","锥郎双管鼾正急，女儿一见走且僵。","走向厨中唤爷娘，认是西家老鹄鸧。","从来不乱雌雄匹，定是多为曲糵伤。","扶下楼层梯十二，明朝说与都不记。","豆蔻孤香依旧含，葡萄千日如前醉。","我闻此语高其人，有迹无心那可嗔。","东墙桃花各有主，肯使西家共个春。","楚国才芳无宋玉，东邻如花女独宿。","攀墙唤玉巳三年，玉对楚王坚可怜。","小臣不比登徒辈，似隔银河路几千。","阮籍酣来眼不青，阮咸醒处大奔鹑。","借马追姑生夺婢，因丧吊女哭无情。","哭无情，笑有态，倒千金，须一买。","即使囊空买不成，韩香窃却未相应。","罢绣岂少倚市门，且须浊水浇乾唇。","投桃或可求连理，赠药安知不洧津。","鸟杂配，兽乱群，卓轸凤皇生逾贱。","韩冢鸳鸯死越芬，青陵一曲崩高云。"]},{"t":"星渚篇","f":"七言古诗","c":["昨夕梦见张骞至，今朝忽遇娄星渚。","同是天河往复还，可曾相识牛和女。","牛女迢迢河汉边，乌鹊为桥半月圆。","黄姑怜彼久离索，折取琼枝插作妍。","龙山尽处深波白，夜夜予来弄明月。","钓竿拂却珊瑚长，波声细作琵琶咽。","此时予思横不禁，此际萧郎系妾心。","楼中刻漏滴复滴，月里梧桐阴复阴。","娄子讶予醉欲去，去买鲤鱼长尺许。","既教柳叶出娥眉，更取花枝催羯鼓。","鼓声高急似鸣鼍，星高月落奈如何。","依稀鹊叫东方白，为作迢迢星渚歌。"]},{"t":"无题","f":"七言律诗","c":["黑云风搓成细柔，皎月天开空霁落。","云索条条有时断，月皎夜夜同君乐。","杯酒壶觞不尽兴，坐到天明复沽饮。","彩云五色月染成，添护蟾宫桂花影。"]},{"t":"廿八日雪","f":"七言古诗","c":["生平见雪颠不歇，今来见雪愁欲绝。","昨朝被失一池绵，连夜足拳三尺铁。","杨柳未叶花巳飞，造化弄水成冰丝。","此物何人不快意，其奈无貂作客儿。","太学一生索我句，飞书置酒鸡鸣处。","天寒地滑鞭者愁，宁知得去不得去。","不如著屐向西头，过桥转柱一高楼。","华亭有人住其上，我却十日九见投。","昨见帙中大可诧，古人绝交宁不罢。","谢榛既与为友朋，何事诗中显相骂。","乃知朱毂华裾子，鱼肉布衣无顾忌。","即令此辈忤谢榛，谢榛敢骂此辈未。","回思世事发指冠，令我不酒亦不寒。","须臾念歇无些事，日出冰消雪亦残。"]},{"t":"题画","f":"古风","c":["南海荔枝我曾吃，今见双鹂夺残一。","边郎元是陇西人，乃能画此南中物。","我闻南海之枝更绝伦，却只闻之未入唇。","不知双鸟争残颗，只是海南还是闽。"]},{"t":"郑本白兔","f":"楚辞体","c":["噫吁嘻，虾蟆无翼，能载羿妻。","宋鹊之捷，宁不能飞。","人言日广千里，月亦如之。","七为楼台三为坻，吴罡斫桂不得睡，帝命牵犬而猎之。","娄金之宿，徒有光芒。","赵简之翟，既以赠将。","罡兮持手不得猎，下呼鹊也腾苍苍。","玉兔告蟆，蟆不得庇。","宋鹊上天，玉兔下地。"]},{"t":"客强予画十六种花因忆徐陵杂曲中二八年时不忧度之句作一歌因为十六花姨歌舞缠头亦便戏效陵体用陵韵","f":"七言古诗","c":["东邻西舍丽难俦，新屋栖花迎莫愁。","蝴蝶固应憎粉伴，牡丹亦自起红楼。","牡丹管领春秾发，一株百蒂无休歇。","管中选取八双人，纸上娇开十二月。","谁向关西不道妍，谁数关头见小怜。","侬为顷刻殷七七，我亦逡巡酒里天。","昭阳燕子年年度，谁能镜里无相妒。","镜中颜色不长新，画底胭脂翻能故。","花姨舞歇石家香，依旧还归纸砑光。","莫为弓腰歌一曲，双双来近昼眠床。"]},{"t":"予作花十二种多风势中有榴花题其卷首曰石醋醋骂座","f":"古风","c":["洛阳城中崔处士，花园麝起花妖至。","封姨十八太颠狂，石家醋醋新高髻。","醋醋能娇百带牢，珊瑚枝上织鲛鮹。","明珠似月摇难落，冰住黄鱼白鳔胶。","封姨身重不能斤，翻杯湿却石家裙。","初来竞唱迎姨曲，转眼翻为骂座人。","朱唇粉晕山眉远，愁来皱断春蚕茧。","石娘娇小不辞觞，夜深潮浅腮红软。","金铃不动仗崔徽，明岁冯他十八姨。","借问当时诸女儿，可似此中数抹蓝燕脂。","噫吁嘻，胡蝶灰，黄蜂锥。","封姨之风丰隆雷。","问画图，有与无。","十八姨，胡为乎。","高阳酒徒，燕市狗屠。","耳热之后，秦筝呜呜。","明日重阳，无钱可沽。","十八姨，胡为乎。","十指握钩，五白呼卢。","夜叉子都，同醉一垆。","十八姨，胡为乎。"]},{"t":"蟹","f":"七言古诗","c":["虽云似蟹不甚似，若云非蟹却亦非。","无意教君费装裹，君自装裹又付题。","世间美好人夺冒，略涉小丑推向谁。","此幅傩云都不丑，知者赏之不容口。","涂时有神蹲在乎，墨色腾烟逸从酒。","无肠公子浑欲走，沙外渔翁拗杨柳。"]},{"t":"王鹅亭雁图","f":"七言古诗","c":["本朝花鸟谁高格，林良者仲吕纪伯。","矮人信耳辄观场，只晓徐熙与崔白。","崔徐一纸价百金，风韵稍让吕与林。","即如此图王鹅亭，云是剡溪雪夜人。","雁儿一扫六十只，何只不落青天云。","沙黄芦白喜相逐，逸者飞鸣劳者宿。","不须彭蠡泛扁舟，彭蠡湖今在吾目。"]},{"t":"画百花卷与史甥题曰漱老谑墨","f":"古风","c":["世间无事无三昧，老来戏谑涂花卉。","藤长刺阔臂几枯，三合茅柴不成醉。","葫芦依样不胜揩，能如造化绝安排。","不求形似求生韵，根拨皆吾五指栽。","胡为乎，区区枝剪而叶裁。","君莫猜，墨色淋漓雨拨开。"]},{"t":"又图卉应史甥之索","f":"古风","c":["陈家豆酒名天下，朱家之酒亦其亚。","史甥亲挈八升来，如椽大卷令吾画。","小白连浮三十杯，指尖浩气响成雷。","惊花蛰草开愁晚，何用三郎羯鼓催。","羯鼓催，笔兔瘦。","蟹螯百双，羊肉一肘，陈家之酒更二斗。","吟伊吾，迸厥口，为侬更作狮子吼。"]},{"t":"九马圉人图二圉醉濒堕","f":"七言古诗","c":["穆王八骏西驰去，造父把辔为之御。","此时八骏谁传形，太仓老王太仆卿，刻石嵌在卿之庭。","马瘦尾尖了无肉，颈长筋绽抽兰甚，俨如蝘蜓缘壁腾。","谓之为龙特无鳞，此图之马乃九匹。","却比八骏多其一，骨耸肉匀亦奇物。","老眼宁知画者谁，摩挲却是孟頫笔。","牧夫九人二人醉，醒者扶之醉不坠。","河南山东牧马儿，汗酒胡葱醉似泥。","此时傥堕无扶持，马且失矣太仆笞。"]},{"t":"完淳篇","f":"古风","c":["七孔虽外交，谁令滑其里。","一朝一凿之，七日浑沌死。","大隗山上牧马儿，轩辕黄帝称天师。","牧儿冯马马则扰，伯乐冶马马生巧。","噫吁嘻，海若太仓之米，庄生濠上之鱼，纪渻木鸡之无敢应，野老鸥鸟之忘其机。","葛天无怀差可意，卢敖汗漫长相思。","不周崩堕只下土，破天一角谁与补。","石头五色烂如花，女娲十笋高能许。","君不见朱提著铜银堕赝，心银之雁知何限。","蜘蛛借雨诈骊罝，络纬将声浑纺车，巧则巧矣真则差。","郑君号完淳，陈君请我说。","我谓淳之完，辟彼云中月。","自云自月自扫除，高团依旧金蟾蝫。"]},{"t":"闽工某摹伯时昭君下嫁图单于亲迓之随骑士胡姬姬娇而骑与单于并狞健可畏鞟衣结束文马华旌及姬之靴帽并妍绚可爱而掌琵琶者尤胜胡决不办此李盖以意为之取悦人目马三兄投赋赋之","f":"古风","c":["毛奴索金嫱不予，貌取西施为嫫母。","一朝远嫁作阏氏，不及宫斜一抔土。","奴也貌嫱故不真，龙眠貌嫱相隔千馀春。","朝风莫雪一万里，粉腮那得娇如此。","故知两貌师，彼此妍媸虽各别，并是以意而为之。","人生触处有不幸，东脱网罟西亦阱。","汉宫颜色不及天子知，胡廷憔悴未必单于终始相亲近。","琵琶小妾百双眉，是胡是汉尽花枝。","老羝夜醉葡萄酒，遁入毡帷知不知。"]},{"t":"朱次公读书飞来山群彦过访携饮塔颠方拈六韵拟赋雨至踉蹡而下漫闻次之","f":"七言律诗","c":["枕书小睡门开半，客来就榻弹书唤。","携壶醉客相轮尖，饿鹳窥餔搅云乱。","僧厨沸酒百蚊飞，双枣沈茶紫茧微。","酒罢书横依旧睡，梦为蝴蝶别花归。"]},{"t":"菘台醋","f":"古风","c":["辣鼻作犀向月卬，便唧鼻涕天尺长。","十卬九低头作鹭，才能一嚏噀作雾。","积年糟蛊烂人肠，霎从毛孔走大荒，一战笑受糟酋降。","伯伦无妇堪诒左，谁持五斗来贺我。","战捷知真却病不，兴败少渠真不可。","西国葡萄那得来，吾卿豆酝逐家堆。","黄公握曲千年返，卓氏当垆百店开。","新涡放水荷花白，旧栈溅珠黄琥珀。","个个鼾闻忉利天，人人梦到华胥国。","华胥国，餐?醁。","生无欢，死无哭。","孟公紫菘赛黄独，绿台大拇抽肥玉。","一浇一段鲁微生，闭在春瓷饷醉人。","一嚼一嚏醉辄醒，醒来却苦多烦恼，醒固不恶醉亦好。"]},{"t":"张旭观公孙大娘舞剑器","f":"七言古诗","c":["大娘只知舞剑器，安识舞中藏草字。","老颠瞥眼拾将归，腕中便觉蹲三昧。","大娘舞猛懒亦飞，秃尾锦蛇多两腓。","老颠蛇黑墨所为，两蛇猝怒斗不归。","红毡粉壁争神奇，黑蛇比锦谁邛低。","野鸡啄麦翟与晕，一姓两名无雄雌。","老颠蘸墨捲头发，大娘幞头舞亦脱，留与诗人谑题跋。","常熟翁来索判频，常熟长官错怪人。"]},{"t":"书茅氏画","f":"七言律诗","c":["小李将军固名笔，轻描细染工如织。","若图台阁与丝纶，界画便须三十日。","茅君挥洒无一尘，只如此幅自清真。","潇潇数点江湖墨，写出岩廊辅世人。"]},{"t":"附画风竹于箑送子甘题此","f":"古风","c":["送君不可俗，为君写风竹。","君听竹稍声，是风还是哭。","若个能描风竹哭，古云画虎难画骨。"]},{"t":"渔图","f":"五言绝句","c":["何人画秋色，芦花绣如组。","罢钓睡孤舟，月满潇湘浦。"]},{"t":"寿王生","f":"七言古诗","c":["四十年前王国鸣，红带编绳束发青，众客对之俱含情。","我亦把酒劝一觥，欲引其答骄不应。","今来转睛年六十，头发虽黑髭须白。","诸朋作寿鹅双蹠，我却龙钟行不得。","送肴一格四杮朱，令我自吃省我沽。","惜少方阑唱鹧鸪，方阑若在亦丑吾。"]},{"t":"沈将军诗","f":"七言古诗","c":["将军者谁沈家郎。","学书学剑学渔阳。","呼枭喝雉疲夜场。","月低日高睡竟忘。","躯干虽小胆则姜。","十年从军官参将。","杀贼归来坐五羊。","明珠芡米侧槩量。","买得绿珠可姓梁。","一妻五妾愁专房。","广西藤酒世无双。","海南红螺不假镶。","直钱虽少贵天生。","鹦鹉不谈立酒旁。","文犀玳瑁细碎妆。","龙脑一缕飞中央。","左县翡翠玉虫螀。","右挂镂金小凤皇。","回身未步身先锵。","盻影入鬓斜月光。","拽郎髭须郎吻张。","大卮小卮响喉咙。","池中岂少雌鸳鸯。","安得老鸧专颉颃。","郎谁与欢思边疆。","谁者换马邯郸娼。","庐龙将军急才良。","见郎谓何用不臧。","且试锁钥扼背吭。","分道密云汝往当。","汉家猛士守四方。","沈郎沈郎不寻常。","我思古人等雁行。","吹箫者谁勃丞相。"]},{"t":"春野图","f":"七言古诗","c":["北门之外多佳丽，白水茫茫绕天际。","中有幽人春野翁，摘荷采芰纫衣袂。","春野读书曾万卷，只今一字不欲看。","只将元气手中调，不许红尘眼中散。","昨者铸鼎鍊九还，吾欲从之乞一丹。","青牛在田不肯语，轻蓑大笠天将雨。"]},{"t":"刘雪湖梅花大幅","f":"七言古诗","c":["梅花自是花中魁，画梅花者今数谁。","雪湖刘子故不俗，未画梅花先写竹。","花梅筱竹两相于，直干横梢铁不如。","最好片云遮一抹，尤宜大雪踏孤驴。","我与刘君相见初，较量长短捋髭须。","圈花少让元章笔，发干元章不若吾。","捉笔呼煤将发干，闭门自不令人看。","须臾歇笔乃开门，一扫槎枒三丈绢。","我客金陵访画梅，画梅莫妙盛行之。","刘君放逸不可羁，一刘一盛无雄雌。","我今白日题梅画，恍忽如梦罗浮夜。","觉来香风搅衣带，花下美人是何代。"]},{"t":"洞岩入鳖口有石枰石桥及石池诸景","f":"七言古诗","c":["洞梁高负泥沙恶，一躯巧骨裹痴鞟。","昨闻巳是三十年，今夕张灯始扪摸。","初疑螺尾不可梯，再进再折无尽期。","鱼脑别波枯未已，蜃脚逢沙涩懒移。","人言此语得大槩，却须请君说细微。","桃根倒僵虫齧久，蜜脾仄挂蜂归稀。","二洞三洞止一隙，解衣卧洞身投鳖。","苍枰烂斧或有人，石桥浸影终无月。","当时蒋侯身不死，一去亲赍五日米。","遥闻橹响送江船，头上恐是钱塘水。","避秦岂直武陵隈，何事桃花不出来。","星河作影当归路，疑是淳于梦大槐。"]},{"t":"兰泉篇","f":"古风","c":["白虹细细三千尺，兰苕叶叶垂青碧。","百草诸芳不敢吹，惟有湘洲杜若与之齐。","浴蛟饮鹿无不可，漱齿洗耳随君宜。"]},{"t":"出塞","f":"五言律诗","c":["汉将去堂堂，边尘靖不扬。","雪沈荒漠暗，沙揽塞风黄。","虏帐朝依水，胡酋夜进觞。","舞儿回袖窄，无奈紫貂香。"]},{"t":"琉球刀 其一","f":"五言律诗","c":["客将刀出市，云是大琉球。","海泛防龙合，天阴听鬼愁。","挥空霜欲落，脱匣水堪抽。","万里烽烟地，随身去莫留。"]},{"t":"西北 其一","f":"五言律诗","c":["西北谁家妇，雄才似木兰。","一朝驰大道，几日隘长安。","红失裙藏镫，尘生袜打鞍。","当垆无不可，转战谅非难。"]},{"t":"西北 其二","f":"五言律诗","c":["金鞍七宝欹，玉手控青丝。","人马才相得，风云气本奇。","势轻香易堕，样巧影难为。","驰罢雄心在，何曾敛翠眉。"]},{"t":"西北 其三","f":"五言律诗","c":["尺锦即成装，当眉绾结方。","须臾撒身手，驰骤蹴风霜。","檐影千门乱，街心一带长。","忽逢游冶子，系马问家乡。"]},{"t":"桃花堤上看美人走马","f":"五言律诗","c":["一镜围湖水，千峰绕梵宫。","大娘回剑器，小伎落惊鸿。","影深穿柳日，蹄响带花风。","望断梨腮粉，红尘一道中。"]},{"t":"孟后怨","f":"五言律诗","c":["福薄姑言信，君难国事非。","官家俨平昔，贱妾独何依。","汴水千秋逝，山花几度稀。","还怜先帝宠，夜夜月中归。"]},{"t":"竹月篇为易道士赋","f":"五言律诗","c":["脩竹隐丹扉，萧萧映月微。","林稠光不碍，叶动白俱飞。","制鼎看圆魄，裁箫度羽衣。","翻经清夜永，犹带露华归。"]},{"t":"寄尚宾因借石磬","f":"五言律诗","c":["南明栖息久，凡著几何书。","夜峡月生石，朝窗云入疏。","特悬孤磬在，时扣万山虚。","自笑耽清物，持来一借予。"]},{"t":"宛转词","f":"五言律诗","c":["宛转一臂断，流落二乔轻。","覆水巳无及，通家如有情。","归来妆粉暗，啼罢泪痕清。","莫道红裙怯，官家盛甲兵。"]},{"t":"湖严氏有二女其翁以长者许渭继室渭自愆盟顷闻为海寇断其翁臂二女俱被执旋复放还便巳作宛转词怜之后知其长女被执时即自奋堕桥死幼女放还亦死因复赋此宛转词中覆水句正悔愆盟也","f":"五言律诗","c":["讶道自愆盟，天成烈女名。","生前既无分，死后空馀情。","粉化应成碧，神寒俨若生。","试看桥上月，几夜下波明。"]},{"t":"顺昌道中新晴","f":"五言律诗","c":["解辔投山屋，束鞍闻曙鸡。","风云留宿雨，花草踏晴泥。","晓峡喧溪路，春沙泛马蹄。","遥知武夷曲，只在乱峰西。"]},{"t":"十六夜宿叶坊玩月","f":"五言律诗","c":["昨照桥中阁，今辉驿口沙。","清光迷魍魉，冷晕呕虾䗫。","与水浮诸海，将山碧一涯。","春风正司令，桂树暂停花。"]},{"t":"杜鹃花","f":"五言律诗","c":["烟雨艳阳天，山花发杜鹃。","魂愁数叶暗，血渍一丛鲜。","正色争炎日，重台沓绛笺。","春风几开落，遗恨自年年。"]},{"t":"古镜","f":"五言律诗","c":["白日淘抔土，青天射两丸。","且须防薄蚀，讵止鉴衣冠。","神物含光易，深山识宝难。","不知丘壑里，还掩几冰团。"]},{"t":"陈女度尼","f":"五言律诗","c":["青春正及笄，削发度为尼。","别母留妆粉，参师歇画眉。","幻真临镜现，生灭带花知。","未必今来悟，前身受记谁。"]},{"t":"赠相士","f":"五言律诗","c":["节钺下明州，东随一剑留。","帷中占胜色，市上立清秋。","碧眼胡僧避，青囊道侣求。","相逢多暮客，曾见李藩不。"]},{"t":"分赋得吴山送俞君还赣","f":"五言律诗","c":["吴山碧石头，雄抱浙江流。","大可兴云雨，微还适览游。","常登应结恋，乍别不能留。","明朝翠色远，尔知在行舟。"]},{"t":"芸阁校书篇","f":"五言律诗","c":["薄雾霭香筒，青缃走蠹虫。","一梯陟刘向，万帙映杨雄。","鸟下窥书古，花飞缀字红。","他年在天禄，羞与俗人同。"]},{"t":"饮云居松下眺城南","f":"五言律诗","c":["夕照不曾残，城头月正团。","霞光翻鸟堕，江色上松寒。","市客屠俱集，高空醉屡看。","何妨高渐离，抱却筑来弹。"]},{"t":"送内兄潘伯海谒选","f":"五言律诗","c":["之人千里行，言宴款郊城。","牵尔衣裳处，糿予帷幕情。","见兄兼念妹，送舅祗携甥。","明岁承恩日，龙池万柳青。"]},{"t":"省试周大夫赠篇罢归赋此","f":"五言律诗","c":["十谒九不荐，那能长作儒。","江光凌弃壁，关色黯归繻。","薇蕨求新主，羹汤问小姑。","风雷亦何限，终是恼凡鱼。"]},{"t":"丰吏部公邀泛西湖观荷明日寄作令与嘉则叙父追和","f":"五言律诗","c":["吏部元耽饮，良辰尊俎携。","分明在湖上，记得似耶溪。","别浦红裙桨，垂杨白马堤。","茫茫荷叶路，共水入天西。"]},{"t":"白鹇","f":"五言律诗","c":["片雪簇寒衣，玄丝绣一围。","都缘惜文采，长得侍光辉。","提赐朱笼窄，羁栖碧汉违。","短檐侧目处，天际看鸿飞。"]},{"t":"来青亭","f":"五言律诗","c":["画栋将云绕，修檐傍汉开。","亭非邀翠入，山自送青来。","远色虚难写，遐观纵未回。","共言春景丽，不见使人猜。"]},{"t":"元旦与肖甫较射","f":"五言律诗","c":["烟光海日曈，青帝早司东。","候转弓犹劲，标疏的略红。","耦弯双月吐，长臂一猿通。","本是无争者，心知此际雄。"]},{"t":"季长沙公哀词","f":"五言律诗","c":["槐树宛低回，犹疑讲席开。","死因双宿去，生为六经来。","绕瑟飞春水，传灯暗夜台。","三年更筑室，未了独居怀。"]},{"t":"钮大夫园林","f":"五言律诗","c":["万树梅花国，垂帘试一凭。","高楼烟欲暮，远岫雪将晴。","帆舫时时渡，溪桥处处横。","若耶无限景，都有此中情。"]},{"t":"送高叟入燕","f":"五言律诗","c":["少小幽燕客，重游白发多。","人钦旧然诺，客和古悲歌。","红叶淮流舫，黄尘沛县骡。","向来沽酒处，留得几娇娥。"]},{"t":"背树","f":"五言律诗","c":["背树零宵露，羁魂断晓铺。","正当愁画地，谁遣放啼乌。","拭泪身仍系，酬恩计转迂。","应劳垂老魄，结草向冥途。"]},{"t":"赋得看剑引杯长","f":"五言律诗","c":["高会莫匆匆，鱼肠把似公。","睥睨寸心在，慷慨百壶空。","客散平原夜，波寒易水风。","秦雠不能报，泪落酒杯红。"]},{"t":"赋得暗尘随马去","f":"五言律诗","c":["春夕丽春灯，芳尘似有情。","难随罗袜缓，却逐马蹄轻。","高缕迷鞍浅，低光影镫平。","酒家莫留系，一夜遍都城。"]},{"t":"赋得芹芽","f":"五言律诗","c":["青春曲水湄，芹吐小芽滋。","在野未堪摘，献君知几时。","暖风来燕子，寒食伴棠梨。","一夜休教老，留尖煮鲙丝。"]},{"t":"镇江","f":"五言律诗","c":["落日挂城角，孤蓬憩水窗。","草长交浦断，潮大入河降。","笋蔌辞乡饭，樱桃过镇江。","吴船夫妇唱，十曲九成双。"]},{"t":"王山人丹房","f":"五言律诗","c":["山房在何所，宛在水中央。","丹灶泥初湿，红颜药正黄。","菱花归舫乱，荷叶过人长。","一自弹渔鼓，陶陶醉几场。"]},{"t":"仲春李子遂季子牙史叔考坐雨禹迹寺景贤祠中醉馀赋诗并用街字子遂来自建阳一别数载","f":"五言律诗","c":["病久不到此，荒祠草上阶。","阴晴连日异，闽越几年怀。","夜梵潮三丈，春酥雨一街。","梨花无月处，有客醉金钗。"]},{"t":"法相寺看活石","f":"五言律诗","c":["莲花不在水，分叶簇青山。","径折虽能入，峰迷不可还。","取蒲量石长，问竹到溪湾。","莫怪淹斜日，明朝恐未閒。"]},{"t":"侣琴篇为赵子赋","f":"五言律诗","c":["岂无兰蕙好，独结峄阳桐。","养鹤多因尔，游鱼亦为侬。","风雷县一壁，山水伴千重。","一作梅花弄，都令雪满空。"]},{"t":"宝刀诗","f":"五言律诗","c":["双钮黑银镂，来从大土酋。","绦绒结蛮女，铁色照并州。","不惜金千镒，能县水一沟。","床头好珍重，兼许茂先收。"]},{"t":"答谢上谷诸公","f":"五言律诗","c":["一客宣城镇，真多地主良。","停车松树下，投辖井中央。","红烛筹枚满，苍毛尘话长。","别来知几日，柳色满红墙。"]},{"t":"书箑赠顾鸿胪","f":"五言律诗","c":["廿载神交后，尺书长跪辰。","涸鱼幸不死，闰月亦徒春。","碧柳深高馆，红云近侍臣。","相过不能数，叔夜懒方真。"]},{"t":"王口北见遗貂帽因往","f":"五言律诗","c":["一围消雪远，两翅辟尘赊。","朔北冻杀马，辽东买断牙。","锦筵津颊玉，深户拥腮花。","一罩山人帻，徒遮鬓发华。"]},{"t":"纳妾诗","f":"五言律诗","c":["角枕覆衾长，新香异旧香。","昔年曾射雉，此日复求凰。","杏靥开春镜，鸦云换晚妆。","夫君莫早起，初日未高梁。"]},{"t":"骏霞篇为天台黄子赋","f":"五言律诗","c":["芜市千金骏，天台一片霞。","持将两神物，较许大名家。","每过愁驴直，言归必日斜。","御河生隔断，杨柳暗宫鸦。"]},{"t":"梨俱幽沈大雅与杜并传","f":"五言律诗","c":["潘家大谷梨，今遍九河堤。","接树冰千鞠，单颗水一提。","马驮香黑瓮，雁过脆红犀。","未怕相如渴，王孙尽翠眉。"]},{"t":"杏","f":"五言律诗","c":["杏有海东红，珍高百品中。","色来先压市，子大欲沈笼。","酿苦蜂何为，人甘蠹亦同。","道旁繁李树，好去问王戎。"]},{"t":"李","f":"五言律诗","c":["闽种夫人异，燕枝嘉庆同。","蹊堪为李广，核可付王戎。","碎玉当唇绿，飞饧绕臂红。","归来忆滋味，能得几时醲。"]},{"t":"胡桃","f":"五言律诗","c":["羌果荐冰瓯，芳鲜占客楼。","自应怀绿袖，何必定青州。","嫩玉宁非乳，新苞一不油。","秋风乾落近，腾贵在鸡头。"]},{"t":"白樱桃","f":"五言律诗","c":["樱桃琥珀珠，一树忽砗磲。","入袖迷吴苧，如珩信楚书。","朱唇尝处讶，翠叶冻边舒。","欲问丹阳鸟，曾衔此类无。"]},{"t":"土豆","f":"五言律诗","c":["榛实软不及，菰根旨定雌。","吴沙花落子，蜀国叶蹲鸱。","配茗人犹未，随羞箸似知。","娇颦非不赏，憔悴浣纱时。"]},{"t":"薯蓣","f":"五言律诗","c":["扶中识旧方，爽吻得新尝。","脏廪衰年坏，山薯此地良。","芋魁徒软美，松粉藉餦餭。","楚些郱遗此，清酥点蔗霜。"]},{"t":"铁脚","f":"五言律诗","c":["吴下绵披细，燕中铁唔纤。","俄为群少炙，祗用一竿黏。","暗雪辞饥啄，红椒飶醉髯。","窥螳黄雀事，公子慎金丸。"]},{"t":"黄鼠","f":"五言律诗","c":["幸不为残啮，何由冒劣名。","庖厨穷口腹，天地窘生成。","浅草遮人拙，深膏傍烛明。","断齑吾自分，食肉任干城。"]},{"t":"半痴","f":"五言律诗","c":["厄与痴相半，禽将鼠共县。","味虽供客好，名却使人怜。","所下惟双箸，何妨少一拳。","如闻三嗅叟，笑杀雉羹筵。"]},{"t":"荔支 其一","f":"五言律诗","c":["帆樯报荔支，犹忆海南时。","一邑明勾漏，千罂枕蜜脾。","消中随蔗往，高树放猿之。","近日肝肠别，依稀饿采薇。"]},{"t":"荔支 其二","f":"五言律诗","c":["当醉更须醉，当飧便买飧。","几年千里外，一颗百金难。","飞骑休轻刺，垂猩且夺看。","老甜今巳矣，世味饱咸酸。"]},{"t":"熊","f":"五言律诗","c":["李广射熊归，生肩付大儿。","都无一寸白，傥有几条笞。","腊掌吾曾饫，鲜蹯胜略差。","穷饕亦何剧，急鲊白鱼迟。"]},{"t":"黄羊","f":"五言律诗","c":["紫塞黄羊美，超腾不易供。","蹄虽千里外，命寄一厨中。","谁致西河俎，言穿老上弓。","宾筵三动指，早晚到驼峰。"]},{"t":"河豚","f":"五言律诗","c":["白下酒家檐，河豚荻笋尖。","寒江晴后雪，烂柳窾中鲇。","万事随评品，诸鳞属并兼。","惟应西子乳，臣妾百无盐。"]},{"t":"送薛鸿胪左官袁州","f":"五言律诗","c":["佐郡袁州去，江行万里西。","兴牵春水雁，心断早朝鸡。","蛮境风烟近，巫乡习俗迷。","正须烦料理，滕阁未遑跻。"]},{"t":"雨","f":"五言律诗","c":["一雨连秋夏，无朝不冥迷。","晓添四壁篆，夜助百虫悽。","蒙羃遮城漏，蒸潮汗础泥。","直愁衡岱顶，亦障海乌飞。"]},{"t":"夕霞 其一","f":"五言律诗","c":["明霞剪脚齐，茜水入霄泥。","雁鹜千行外，岩峦一角西。","石家锦步帐，海国紫玻瓈。","安取挥戈术，相留莫遣飞。"]},{"t":"夕霞 其二","f":"五言律诗","c":["明霞烂且都，雨歇霁霄铺。","万国楼台莫，孤村烟火晡。","波鳞销琥珀，海色上珊瑚。","一抹须弥翠，胭脂月镜孤。"]},{"t":"夕霞 其三","f":"五言律诗","c":["元气渺太素，丹铅何所妆。","白鱼劳尾变，红石补天长。","剩付烟岚彩，全并沆瀣光。","俄飞一片紫，骑凤是萧娘。"]},{"t":"送某子北上","f":"五言律诗","c":["送子有所思，秋风来何翩。","拜翁挂貂处，谈我篝灯前。","枣红刍马店，霜白听鸡天。","一队长鞭里，轻寒早著绵。"]},{"t":"某君中贡选送之","f":"五言律诗","c":["物有幽奇者，飞腾各擅方。","巨鱼须北化，细芷不南香。","在狱持何赠，穿泥以剑将。","回思成一笑，君自有鱼肠。"]},{"t":"人言凤尾蕉花于某县庭命作","f":"五言律诗","c":["凤尾本蕉材，红花绿叶毸。","县庭今一见，蛮地不曾开。","孔雀羞金翠，萧娘坐粉腮。","颖川黄霸在，辛苦送祥来。"]},{"t":"寿葛贞母","f":"五言律诗","c":["终岁不成妆，钗寒古凤凰。","诗堪将柏赋，年亦与松长。","列女谁同传，称人果未亡。","当筵思举案，误递百年觞。"]},{"t":"乙亥元日雪酌梅花馆 其一","f":"五言律诗","c":["秋叶巳凋疏，春林积雪初。","溪藤不复买，裙练免偷书。","挂碧来鸣鸟，虽红补破庐。","待予新买屋，自种两三株。"]},{"t":"乙亥元日雪酌梅花馆 其二","f":"五言律诗","c":["花叶看虽少，藤稍绕更赊。","苍须摇水雪，白玉碾龙蛇。","碧气将檐薄，浓阴夺竹斜。","去年深夏热，特地为予遮。"]},{"t":"初夏送某客入广","f":"五言律诗","c":["海南多宝地，客也傍春行。","涉岭梅丸绽，当廛荔子明。","百香番贾舶，双翠美人缨。","会向青楼去，时呼艇子乘。"]},{"t":"雨舟载鹤诗","f":"五言律诗","c":["买鹤载归去，况逢风雨天。","客装兼有此，江影两潇然。","湿重毸孤雪，波长立暮烟。","园池宁有此，漠漠迥堪怜。"]},{"t":"元夕之辰偕友人集九里之天瓦寒泉二庵各赋","f":"五言律诗","c":["寻常难淡泊，况复值兹辰。","山水留吾辈，灯花媚别人。","言归城市去，似别武陵春。","一路梅花水，今年弄月新。"]},{"t":"拟寿长春祠何老","f":"五言律诗","c":["云母何姑粉，增城几叶春。","冯心行好事，作屋住仙人。","锻柳堆山铁，眠松弄水银。","面上桃花色，流年始七旬。"]},{"t":"京中送友人南归","f":"五言律诗","c":["不道归真急，翻嫌握手迟。","绿蝇秋渐少，黄鸟日相思。","以我尚未去，问君来几时。","答言春尽后，北雁与同飞。"]},{"t":"送蔡安父之黄州","f":"五言律诗","c":["安父黄州去，乃当中夏时。","榴花作火艳，梅雨烂蚕丝。","研墨沄沄燥，窗书叶叶吹。","今朝霁如此，别马快风嘶。"]},{"t":"与葛景文","f":"五言律诗","c":["冬潦无人出，君胡为来欤。","山楼隔年病，江渡几封书。","健后堪风雨，贫来无菜蔬。","不能留一饭，归去寺烟馀。"]},{"t":"画红梅","f":"五言律诗","c":["即使胭脂点，犹成冷淡枝。","杏花无此干，铁树少其姿。","挂壁纷红雪，围春在锦池。","无由飘一的，娇杀寿阳眉。"]},{"t":"画竹","f":"五言律诗","c":["万物贵取影，写竹更宜然。","秾阴不通鸟，碧浪自翻天。","戛戛俱鸣石，迷迷别有烟。","直须文与可，把笔取神传。"]},{"t":"筵中漫赠王良秀笔史","f":"五言律诗","c":["囊琴三尺馀，投我主人居。","老叟能称隐，诸郎总解书。","夜深时唤酒，春尽共骑驴。","去到西湖上，梅花带雪舒。"]},{"t":"吴门逢孔将军于塾","f":"五言律诗","c":["旧日堪为将，今来复授经。","主人盛供帐，醉尉止都亭。","终岁只在野，因予一入城。","相悲十年事，泪落酒杯平。"]},{"t":"书倪元镇画","f":"五言律诗","c":["一幅淡烟光，云林笔有霜。","峰头横片石，天际渺长苍。","虽赝须金换，如真胜壁藏。","偏舟归去景，入画亦茫茫。"]},{"t":"无题","f":"五言律诗","c":["翁也专枢密，侬今职赞襄。","西京留守重，北帽侍中方。","陵气松鳞紫，湖霜藕叶黄。","江南秋色好，此去满帆樯。"]},{"t":"赋得草窗篇为周卫卿之号","f":"五言律诗","c":["草绿鸟喈喈，閒窗一斗开。","百虫堪上笔，一片欲遮苔。","莫影纱纹瀫，春芽老氏孩。","元公有知不，一笑陇牛堆。"]},{"t":"食虎眼","f":"五言律诗","c":["虎眼白琉璃，谁能隶虎皮。","小毬蜂粉结，高液鸟群司。","妇去茶如荠，王归胆亦饴。","由来甘苦柄，舌观岂能持。"]},{"t":"蟹 其一","f":"五言律诗","c":["红绿楪文窑，姜橙捣末高。","双螯交雪挺，百品失风骚。","喂喜朝争谷，飕闻夜泣糟。","大苏无缺事，只怪佞江瑶。"]},{"t":"蟹 其二","f":"五言律诗","c":["水族良多美，惟侬美独优。","若教无此物，宁使有监州。","辟鬼秦关夜，输魁海稻秋。","河豚直一死，只好作苍头。"]},{"t":"蟹 其三","f":"五言律诗","c":["吴兴馋吻守，越国朵颐人。","风韵谁偏少，吹嘘尔绝伦。","沅江九肪鳖，松泖四腮鳞。","遍试张华醋，还谁五色文。"]},{"t":"蟹 其四","f":"五言律诗","c":["尔故饱菱芡，饥来窃稻梁。","逃萧孟尝走，结草杜回亢。","蜕许山蝉嫩，腥怜海麝香。","那能亲箬笠，衣夜伴渔郎。"]},{"t":"蟹 其五","f":"五言律诗","c":["织筱挈千篮，枯筐养八蚕。","缚严愁广武，雾重死淮南。","金紫膏相蚀，尖团酒各酣。","秦人不曾识，付与两齐参。"]},{"t":"胡市归","f":"五言律诗","c":["胡养复胡王，无鹰不饱飏。","满城屠菜马，是鼻掩绵羊。","即苦新输辇，犹胜旧杀伤。","从来无上策，莫笑嫁王嫱。"]},{"t":"客饷我笋脯一小筐稚而甘澹拟谢","f":"五言律诗","c":["晨觞急十斟，笋脯美辽参。","玉版禅师韵，黄冠道士簪。","山存仍受虎，春代并更禽。","箨畔夫将妇，随农插绿针。"]},{"t":"闻人赏给事园白牡丹 其一","f":"五言律诗","c":["白牡丹殊雅，曾于旧谱闻。","扫眉娇虢国，新寡缟文君。","黑牯眠云饱，黄蜂夺雪芬。","爱憎谁与定，赊酒借花醺。"]},{"t":"闻人赏给事园白牡丹 其二","f":"五言律诗","c":["梁园月下白，青琐第中逢。","定是千金买，来陪一捻红。","珍奴学龟息，越女斗猿公。","作意驱脂粉，天然输与侬。"]},{"t":"闻人赏给事园白牡丹 其三","f":"五言律诗","c":["休量姑射子，不语息夫人。","香暗闻龙脑，须黄见蝶身。","雪腮宜买笑，霜鬓可饶嗔。","莫学卢郎妇，题诗谑老人。"]},{"t":"化城寺","f":"五言律诗","c":["方引主人辖，转为山寺嬉。","门深当水尽，路曲入松移。","破铎摇檐鸽，寒萍蔽沼龟。","过溪无虎啸，枉送远禅师。"]},{"t":"明日至古博岭雨","f":"五言律诗","c":["无寸非浓雾，寒空湿太胜。","泥深驴项没，雨近帽檐生。","练泄未到眼，客途先苦行。","真成评嚼榄，敢与枣儿争。"]},{"t":"京邸赠沈刑部","f":"五言律诗","c":["人多骢马客，君惬白云司。","棘署了公事，梅花作雪枝。","带宽知懒在，马重觉尘随。","颇忆洞庭否，烟波十二时。"]},{"t":"晓发句容","f":"五言律诗","c":["宵来醉眠处，忽为远林遮。","三尺短缑烂，一程长耳赊。","村村落斜月，树树抹轻霞。","只尺丹阳近，江鱼入馔嘉。"]},{"t":"送沈叔子南都迎母","f":"五言律诗","c":["马上定苦渴，几回停辘轳。","别兄当北邸，接母到南都。","桃叶横前渡，荷花满后湖。","此行大家逐，谁敢问当垆。"]},{"t":"送冯叔系之南都访旧","f":"五言律诗","c":["江国柳虽尽，将及梅花新。","路远即逢雪，天寒别有春。","高牙纷海幕，长剑著孤身。","乞取封书去，难辞旧主人。"]},{"t":"景文至其舅刘所过圜中","f":"五言律诗","c":["两橐行厨过，清醪溢瓦盆。","一行浇郁思，百覆失烦冤。","笋候人家饭，莺天桃杏村。","无由共甥舅，镇日数圜门。"]},{"t":"送俞生之入楚","f":"五言律诗","c":["作客向襄阳，鳊头大舸装。","江行多雪候，旅宿尽渔乡。","此景俱堪抹，行囊好为藏。","归来逢鉴赏，几度挂山窗。"]},{"t":"张子锡往访其弟长治","f":"五言律诗","c":["伯兄官署去，因寄仲君书。","问政应如水，添厨稍出鱼。","越人多好著，潞锦小花裾。","看取寄归匣，都无一尺馀。"]},{"t":"与任生话旧","f":"五言律诗","c":["麻衣飘雪处，益动而翁思。","近日君家事，予傫那得知。","笋天应荐墓，柏涕可枯枝。","莫作徒悲切，遗书退学诗。"]},{"t":"送张君会试","f":"五言律诗","c":["明年此时节，意气何扬扬。","但遣马蹄疾，莫愁花路长。","几多青楼妇，认取旧檀郎。","何处最笑指，当垆压酒娘。"]},{"t":"挽上虞葛翁","f":"五言律诗","c":["闻道自髫年，传经彻旧编。","裹粮百里外，卒业一灯前。","阅传知高士，遗孤是大贤。","斯人真不死，可以慰黄泉。"]},{"t":"授经馆中怀江东诸同志","f":"五言律诗","c":["能得几回春，匆匆滞此身。","一江书易寄，连月性难驯。","买药独行市，敲门暂访人。","几时束书卷，来伴钓鱼纶。"]},{"t":"蜡屐","f":"五言律诗","c":["一生几两屐，此语尔非迷。","何事沦猩趣，终年弄马蹄。","万钱收锦檿，五岳遍丹梯。","齿畔如濒损，厓蜂借一脾。"]},{"t":"题雪景画","f":"五言律诗","c":["幽人凭水槛，钓者挈鱼投。","况对千山雪，而无一客留。","腊酒此时熟，老夫终岁忧。","壶公能醉我，跳入画中休。"]},{"t":"为陶工部赠道者","f":"五言律诗","c":["终是千年鹤，今先返旧城。","到家人尚在，入洞云来迎。","紫气莫西渡，青山留震盟。","野夫惭尹喜，却办候关情。"]},{"t":"将游五泄宿吴系山庄遇老迎饷邀余辈先登峨眉不果","f":"五言律诗","c":["游辔维林竹，山窗来猎灯。","青苏炊白稻，碧笋束红藤。","坐落半宵月，流分曲水亭。","忽逢山下老，邀上峨眉层。"]},{"t":"白燕 其一","f":"七言律诗","c":["閒庭尽日见还稀，院院梨开去渐微。","别殿几年埋玉匣，旧人何处认乌衣。","春风水面徒闻语，夜月梁间好弄辉。","安得姚家红线缕，却看片雪带花飞。"]},{"t":"白燕 其二","f":"七言律诗","c":["西飞岁岁候青阳，花发名园何处藏。","天子郊禖呈瑞色，主人台榭有辉光。","轻翰攘雨绡初剪，小尾流风练愈长。","万里东归看易没，海天元是白云乡。"]},{"t":"续白燕 其一","f":"七言律诗","c":["一时伴侣自应非，海路空长遇亦稀。","汉将玉门投老入，赵妃雪夜待人归。","孤回夏日摇寒色，渐下秋空见羽衣。","巳识朱门无可托，玉楼天上任高飞。"]},{"t":"续白燕 其二","f":"七言律诗","c":["青壁红窗映苑墙，冲花泛羽唼群芳。","霜迷万瓦单栖渺，草绿千提片影凉。","云母屏深低缟袖，水晶帘动拂流黄。","西园蝴蝶浑无赖，暗粉飘尘上海棠。"]},{"t":"寄成女彝守备登州","f":"七言律诗","c":["牙门遥映列仙台，总帅偏宜上将才。","出海戈矛俱借水，飞空矢石并成雷。","天边送雁将心往，马上题诗带景来。","解道观游怜独赏，那能分向小蓬莱。"]},{"t":"送方阜民公子还歙","f":"七言律诗","c":["江关杨柳弄新晴，游子思家数去程。","客里经春花作伴，酒中连日雨留行。","轻装未结离歌发，大道临岐感慨生。","欲把今朝双别激，寄弹一滴使君灵。"]},{"t":"送通政胡君入闽","f":"七言律诗","c":["访旧暂为闽海客，归涂兼得武夷游。","不堪暮雨张筵别，况值春花带叶抽。","山障入云迷去骑，溪涛作雪泻行舟。","幕中无事同君饮，好向尊前借箸筹。"]},{"t":"言游武夷道中抚景因忆往年尚宾吕君天台之约","f":"七言律诗","c":["岩壑千重路转偏，春阴漠漠带炊烟。","困投野店聊呼酒，笑问名山数举鞭。","笼鸟对人喧曙色，桃花临水弄新年。","多情忽忆天台约，归去应寻剡曲船。"]},{"t":"落花","f":"七言律诗","c":["花落条空芳树稀，秦王宫里捲罗衣。","经过楚巷兼人丽，乍入梁园杂雪飞。","送雨迎风俱是别，沾泥带水不能归。","明年知向何枝发，愿傍青阳近口晖。"]},{"t":"泊阊门值闰月中秋","f":"七言律诗","c":["中秋只尺巳蹉跎，更值中秋此地过。","天上桂轮长苦满，人间酒盏莫嫌多。","虹桥一散能追不，海镜孤飞奈尔何。","最是虎丘此时节，清歌不住水微波。"]},{"t":"送葛韬仲","f":"七言律诗","c":["杏花杨柳夹扶疏，送客澄江煮白鱼。","紫艳葡萄千日酒，白藤花匣万言书。","丰城剑出应双跃，罍观缘多目独居。","待尔他年拂衣日，看予渡海跨青驴。"]},{"t":"饮枇杷园赠某君东道","f":"古风","c":["红葵古盌碧蛆沈，南市青帘买却斟。","布衣真可十日饮，碑钱索得隔年金。","游鱼触沼听歌浅，独鹤穿花出唳深。","给舍酒厨东壁是，缚?毕卓可能禁。"]},{"t":"十四夜","f":"七言律诗","c":["野外虚堂夜不扃，遥遥秋汉数峰青。","旧栽菱叶侵河路，新折莲房插胆瓶。","凉气欲来先到水，月光才上只移棂。","请看明夕三更漏，相对何人坐纸屏。"]},{"t":"月下梨花 其一","f":"七言律诗","c":["今宵风物异寻常，月底梨开万朵光。","闪雪摇冰偏倍昼，迷枝浸叶总生凉。","痕娇旧积啼春雨，镜色新圆选夜妆。","莫遣风吹回作态，素娥应妒舞霓裳。"]},{"t":"月下梨花 其二","f":"七言律诗","c":["细蕊繁花带月芳，新妆摇荡宋家墙。","银丛泛影通河切，酥的飘辉接梦长。","夕鸟几条垂滴滴，春空一片缀苍苍。","却嫌曙色催将晓，冷晕微收益渺茫。"]},{"t":"月下梨花 其三","f":"七言律诗","c":["丹轮皓质两微茫，桂粟梨云斗浅黄。","万点绡痕春带水，一庭雪影夜生香。","小星解照周衾伴，不夜争悬汉帐倡。","讶道独禁风露冷，曾听法曲立臾长。"]},{"t":"月下梨花 其四","f":"七言律诗","c":["壁月流空霁色扬，梨英当夕弄青阳。","摇寒隔院非关艳，映断长天别有芳。","粉靥团团新出洗，窗钱一一暗浮霜。","多情错认梅花夜，教进罗浮梦里觞。"]},{"t":"新建伯遗像","f":"七言律诗","c":["方袍綦履步从容，高颡笼巾半覆钟。","千古真知听话虐，百年遗像见犹龙。","夜来衣钵今何在，画理须眉亦似侬。","更道先生长不减，那能食粟度春风。"]},{"t":"夜酌迟友人不至","f":"七言律诗","c":["方朔侏儒两欲死，智伯中行一是知。","醉里放言何造次，醒中为客太支离。","檐飞细雨除清暑，烛笑粗花旋紫芝。","坐待人来将说与，夜深敲缺唾壶儿。"]},{"t":"赠府吴公诗","f":"七言律诗","c":["幕中曾与众人群，幕外閒听说使君。","破剑壁间鸣怪事，孤城海上倚斜曛。","诙谐并谢长安采，懒散犹供记室文。","把笔欲投还自笑，故山回首隔江云。"]},{"t":"为子微题鹧鸪图","f":"七言律诗","c":["瘴雨蛮烟岭树苍，旧游曾记泊桅樯。","对啼江岸霜初歇，独听扁舟草正芳。","旅景谁将上缣素，羽衣今复见茅堂。","似嫌越鸟南枝惯，拟欲乘风向北翔。"]},{"t":"两宿齐云下憩逆旅夜大雪因复登眺","f":"七言律诗","c":["夜投山店醉眠休，早起茫茫揽敝裘。","更向松间寻旧侣，要于雪后倚高楼。","几重碧殿深相映，万里瑶台俨若游。","归路欲迷何处觅，野梅花落绕溪流。"]},{"t":"孙忠烈公挽章","f":"七言律诗","c":["行藩黄屋车何用，上寿瑶阶酒未酣。","岂有满庭持汉节，终无个士死淮南。","百年正气天为永，一觉忠魂梦亦甘。","词客幽怀关世事，悲歌重扣剑之镡。"]},{"t":"下第回值九日登坞土山访北庵上人","f":"七言律诗","c":["归家忽巳逢重九，聊向高山试一登。","舌在何为更问妇，荤除元不是求僧。","秋云隔水流数片，落叶依岩积几层。","话了出门月初上，岸芦汀菊也相应。"]},{"t":"访玉芝师夜宿新庵同萧女臣","f":"七言律诗","c":["参禅喜与梁王裔，合掌跏趺野竹丛。","坐久空堂诸咒歇，夜深明月四山中。","亲陪客话拈珠串，独卧行单坦片棕。","一宿相留浑旧事，无生自愧永嘉公。"]},{"t":"往年观伎走解意当是北产故缀四律首章用北语今年复来知是金陵上元人又携一少伎同坐铲上分镫放体空中名曰童子拜观音乃昔年所无者","f":"七言律诗","c":["人似明珠马似盘，超腾隐现不离鞍。","各弯镫底罗鞋窄，都在空中妆翠寒。","合掌几回投地去，同心双蝶隔花攒。","莫嫌岁岁频来往，家住金陵自不难。"]},{"t":"与王山人对语","f":"七言律诗","c":["仗剑渡江王猛身，归来又共坐青裀。","平原自有三千客，门下聊同十九人。","曾许凤雏应不忝，由来龙性本难驯。","久知世事只如此，且借清樽一洗尘。"]},{"t":"饮太白楼","f":"七言律诗","c":["城上高楼接大河，城南池沼绕朱荷。","千年供奉飞杯地，一夜徐州上水歌。","露冷秋蛾争彩烛，川长风荻乱金波。","客中行乐无过此，前夕中秋何处过。"]},{"t":"杨道人访我于系索诗","f":"七言律诗","c":["道人半在城都行，今过稽山上禹陵。","身载瞿塘雪后水，手拖蒟酱国中藤。","稍谈鹿乘延卑品，欲拔鸡群亦上升。","近日嵇康知不免，懒将消息问孙登。"]},{"t":"新秋避暑豁然堂","f":"七言律诗","c":["竹雨松涛响道房，瓜黄李碧酒筵香。","人间何物热不喘，此地苍蝇冻欲僵。","一水飞光带城郭，千峰流翠上衣裳。","窗前古水摇枝入，好挂轻絺细雪凉。"]},{"t":"过陈守经留饭海棠树下赋得夜雨剪春韭","f":"七言律诗","c":["春园莫雨细泱泱，韭叶当篱作意长。","旧约隔年留话久，新蔬一刺出泥香。","梁尘巳觉飞江燕，帽影时移乱海棠。","醉后推敲应不免，只愁别驾恼郎当。"]},{"t":"迎春值雪","f":"七言律诗","c":["云黄瓦白照千家，雪里迎春倍物华。","士女红楼先捲幔，吏人采杖忽生花。","瑞多自古无连岁，路滑从东接郡衙。","半是三农占水旱，直随牛尾不辞赊。"]},{"t":"赠秦仲虚","f":"七言律诗","c":["冰玉山人本绝埃，西湖自筑初阳台。","何年养鹤曾飞去，是水当门尽绕来。","道士忽逢松树下，渔舟放在藕花隈。","知余欲与为邻舍，指点孤山一角梅。"]},{"t":"中秋雨集金氏园亭次陈思立","f":"七言律诗","c":["中秋风雨剧凌冯，拂闷觥筹倒一朋。","绿桂隔年疏彩晕，银毬终夜断长绳。","泥深水掌花边鸭，帽落霜颠影外僧。","醉后忽呼长剑看，赤鳞乘涨欲飞腾。"]},{"t":"十六日霁与张长治伯仲集城隅次长治韵","f":"七言律诗","c":["飘砧飞柝戍营秋，坐里閒听说潞州。","孤镜满城池水洗，明河千尺傍人流。","笑论昨夕能漂瓦，醉唤红裙缓下楼。","自古阴晴谁料得，莫辞连夜典鹴裘。"]},{"t":"许口北遗以绫帛绵三物题曰袍具作诗谢之","f":"七言律诗","c":["吴蚕巳挂山人肘，边马尤堪北寺台。","其奈沙场推解雪，那能花处一题梅。","昨期后府将军猎，今学西邻道士雷。","叠取蒲团高一尺，坐消一辆蔚州灰。"]},{"t":"小集滴水厓朝阳观","f":"七言律诗","c":["朝阳道观一何县，滴水孤厓百丈边。","馀气出关雄大漠，长风吹壁立青天。","窗扉近在栖雕处，阁道都拦坐客前。","不信夜来高顶望，定应笙鹤下飞仙。"]},{"t":"张云南遗马金囊","f":"七言律诗","c":["百颗缄题秋暑清，遥闻摘向最西营。","张骞本带葡萄入，马援难抛薏苡行。","万里锦苞辞晓露，一泓寒舌搅春饧。","年来不为临邛病，无奈羁愁渴易生。"]},{"t":"美人红甲","f":"七言律诗","c":["近日新妆处处施，玉纤染草学胭脂。","并将樱颗销筠管，忽散桃花上柳眉。","春色每从梢畔露，丽情半出袖边知。","塞风昨夜吹胶折，抱得琵琶下手迟。"]},{"t":"禹陵","f":"七言律诗","c":["年来只读景纯书，此日登临似启予。","葬罢桓碑犹竖卯，封完玉字不通鱼。","杨梅树下人谁解，菡萏须中气所居。","即遣子长重到此，不过探胜立须臾。"]},{"t":"曹娥祠","f":"七言律诗","c":["曹娥十四死长江，江水连潮万里长。","精卫定应仇渤澥，子胥岂只怒钱塘。","一江鱼鳖浮尸出，八尺龟螭卧绢黄。","总为金钗收正气，可怜枭獍绕爷娘。"]},{"t":"露筋祠","f":"七言律诗","c":["乌鸟既能伤义士，蚊虻何苦碎贞肌。","由来天道本无定，谁使昆虫必有知。","画壁几残春社雨，灵风时满夜归旗。","烟波一望三千里，长在湘江洛水湄。"]},{"t":"冯刑部索书册","f":"七言律诗","c":["躬耕既喜陪明主，列宴兼荣享大庖。","苍帝青阳临左个，朱犁黄犊引南郊。","筵前瓮盎归馀沥，马后蹄肩带割肴。","笑语细君将母好，不劳谐谑自为嘲。"]},{"t":"送啸上人之五台","f":"七言律诗","c":["白下珠林最有名，忽来燕赵作游僧。","春风大众迷花雨，夜壑孤藤看佛灯。","巳办一瓢相伴去，其如多病不能兴。","归来只洗双荷叶，听学文殊演上乘。"]},{"t":"集李侯宅得钟字","f":"七言律诗","c":["侯家帘幕夜重重，醉客觞繁断禁钟。","赐果自鲜冰后色，罂鹅直贱丈前醲。","月斜苑树寒孤鹊，字暗番经集万蜂。","尚有御缄看未得，何时重许拆双龙。"]},{"t":"送余兴国","f":"七言律诗","c":["邻家兄弟逼炊烟，不见于今四十年。","颊有长髯堪佐幕，头多短发尚留燕。","深秋一路逢红叶，明月双帆挂大川。","黄鹤楼中可相引，石榴皮畔觅神仙。"]},{"t":"送新昌潘公","f":"七言律诗","c":["北斗声名重二京，东朝保傅谢初荣。","百年华发晞三握，一日朱轮送满城。","渐喜河冰仍绿水，稍闻乡雪盛黄精。","快帆定落归心后，客梦几番天姥青。"]},{"t":"将别复偕游碧云流觞枯柳之下","f":"七言律诗","c":["征舆解道明朝发，别酒遥从此地酣。","尽日回肠依曲水，昔年种柳似江潭。","霜高睡短鸡偏促，雪滑泥长马不堪。","差有梅花知客意，一程开逼一程南。"]},{"t":"送朱使君太仆","f":"七言律诗","c":["长安明月金叵罗，几度从君醉踏歌。","北寺云屯朝烙马，西清风起夜闻荷。","大臣自引行当召，醉尉逢人且莫呵。","一叶米家书画舫，白虹终夕绕沧波。"]},{"t":"李子遂死予设位哭之遂击木而歌此","f":"七言律诗","c":["泪尽南天哭不回，李生真是可怜才。","生刍解识徐家物，死梦应寻范式来。","紫气镆干埋不得，青枫刺绣任成灰。","知君去證金环果，戏取杨花李上开。"]},{"t":"读问棘堂集拟寄汤君","f":"七言律诗","c":["兰苕翡翠逐时鸣，谁解钧天响洞庭。","鼓瑟定应遭客骂，执鞭今始慰生平。","即收吕览千金市，直换咸阳许座城。","无限龙门蚕室泪，难偕书札报任卿。"]},{"t":"金刚子珠串","f":"七言律诗","c":["不共番经出宝函，定从胡腕摘偏衫。","核堆绣字蛴螬烂，果聚香林孔雀衔。","不断百思惟岭獦，手提一串缚狂㺑。","饥来唤米无人识，送与游僧上海帆。"]},{"t":"送丁叔子北上慰乃兄","f":"七言律诗","c":["令威三世通家好，廿载迁居会面赊。","醉我龙铛才地主，怜君马首又天涯。","春灯雨雪潇潇夜，野店茶汤处处家。","想见皇都堤草绿，春鸰细语绕梨花。"]},{"t":"代寿黔公 其一","f":"七言律诗","c":["有道明王守四夷，公家锁钥在雕题。","一天枢纽群星北，万里金汤半壁西。","茅氏骑龙艰劫火，王乔奉药傥丸泥。","何如翊戴勋臣府，永鐍金书铁马蹄。"]},{"t":"代寿黔公 其二","f":"七言律诗","c":["异姓王功阶特进，大将军客揖须长。","太平象马舞何事，胜会凫鹥醉不妨。","锦席珠玑群彦舌，金炉烟雾百蛮香。","殷勤剩有华封祝，先遣山呼到帝乡。"]},{"t":"代寿黔公 其三","f":"七言律诗","c":["千花百果候青阳，二月斓斑匝点苍。","样簇浓枝灵鹫锦，光添绣褓石麟床。","干戈后取仪双髧，弧矢先悬志四方。","我国同休恩不浅，年年此日忆高皇。"]},{"t":"亚夫墓","f":"七言律诗","c":["王者从来云不死，共疑隆准及重瞳。","巳占龙气成天子，却幸鸿门败乃公。","一牧乳羊遮墓白，几株寒枣覆碑红。","怜侬疽发不欲活，岂为人间少邓通。"]},{"t":"白牝蛟 其一","f":"七言律诗","c":["宝山门外白蛟宫，独处千年不嫁雄。","顿顿涡涎垂燕子，殷殷霹雳懒蜈蚣。","风权近属谁家掌，日本频由尔路通。","一语稍嗔酬恶雨，量无周处在军中。"]},{"t":"白牝蛟 其二","f":"七言律诗","c":["侬应坐视稿三农，不尔祠何吝一丛。","早使嫁夫封石氏，肯教将尾示刘翁。","寸鳞缩虱腥逃井，蜕骨专车雪硬风。","莫倚豢龙终豢尔，史臣亲记醢雌龙。"]},{"t":"读文信公仙岩祠集焚吊 其二","f":"七言律诗","c":["山翁伏腊竞鸡豚，海舶针罗失晓昏。","六尺托孤俱赵氏，一宵投王得公孙。","波涛解逐旌旗走，岩洞宁无气魄存。","安得扶邛亲一拜，百花如锦醉山门。"]},{"t":"夜坐有感转忆往事","f":"七言律诗","c":["朝来乾鹊聒檐牙，入夜孤灯也弄花。","儿女一生梦养虎，行藏四足画添蛇。","因嗟竹箭歌如箦，时泛荷花到若邪。","记得万峰高顶鹿，竟晞黄犬猎人家。"]},{"t":"香烟 其一","f":"七言律诗","c":["谁将金鸭衔侬息，我只磁龟待尔灰。","软度低窗领风影，浓梳高髻绾云堆。","丝游不解黏花落，缕嗅如能惹蝶来。","京贾渐疏包亦尽，空馀红印一梢梅。"]},{"t":"香烟 其二","f":"七言律诗","c":["午坐焚香枉连岁，香烟妙赏始今朝。","龙拿云雾终伤猛，蜃起楼台不暇飘。","直上亭亭才伫立，斜飞冉冉忽逍遥。","细思绝景双难比，除是钱塘八月潮。"]},{"t":"香烟 其三","f":"七言律诗","c":["霜沈把竹更无他，底事游魂演百魔。","函谷迎关儳紫气，雪山灌顶散青螺。","孤萤一点停灰冷，古树千藤写影拖。","春梦婆今何处去，冯谁举此似东坡。"]},{"t":"香烟 其四","f":"七言律诗","c":["薝卜花香形不似，菖蒲花似不如香。","揣摩范晔鼻何暇，应接王郎眼倍忙。","沧海雾蒸神仗煖，峨眉雪挂佛灯凉。","并侬三物如堪捉，捉付孙娘刺绣床。"]},{"t":"香烟 其五","f":"七言律诗","c":["说与焚香知不知，最堪描画是烟时。","阳成罐口飞逃汞，太古坑中刷袅丝。","想见当初劳造化，亦如此物办恢奇。","道人不解供呼吸，閒看须臾变换嬉。"]},{"t":"香烟 其六","f":"七言律诗","c":["西窗影歇观虽寂，左柳笼穿息不遮。","懒学吴儿煅银杏，且随道士袖青蛇。","扫空烟火香严鼻，琢尽玲珑海象牙。","莫讶因风忽浓淡，高空刻刻改云霞。"]},{"t":"香烟 其七","f":"七言律诗","c":["香毬不减橘团圆，橘气毬香总可怜。","虮虱窠窠逃热瘴，烟云夜夜辊寒毡。","兰消蕙歇东方白，炷插针牢北斗旋。","一粒马牙聊我辈，万金龙脑付婵娟。"]},{"t":"春兴 其一","f":"七言律诗","c":["好景蹉跎知几回，今春商略紫洪隈。","固应带插挑深笋，兼好提尊饯落梅。","双蹇百钱苦难办，片桨孤舟荡莫催。","见说山家兜子软，借穿峰顶晚霞堆。"]},{"t":"春兴 其二","f":"七言律诗","c":["乾坤瞬息雪边风，万事阴晴雨后虹。","巳分屠门斋后断，只难酒盏座前空。","半缗榆荚求书客，数点梅花换米翁。","小饮墙西邻竹暗，绵蛮对对语春丛。"]},{"t":"春兴 其三","f":"七言律诗","c":["二月四日吾巳降，摄提尚复指苍龙。","当时小褓慈闱绣，连岁寒衣邻母缝。","一股虫尸忙万蚁，百须花粉乱千蜂。","自怜伯玉知非晚，除却樽罍事事慵。"]},{"t":"春兴 其四","f":"七言律诗","c":["李白桃红照眼明，兰风梨雪逼人清。","一枝带蕊冯吾折，双蝶随风各自争。","粉翅扑衣犹可耐，墨针穿帽此何黥。","因思花草犹难掇，却悔从前受一经。"]},{"t":"春兴 其五","f":"七言律诗","c":["七旬过二是今年，垂老无孙守墓田。","半亩稻秧空饿鹿，两株松树罢啼鹃。","悲来辛巳初生日，哭向清明细雨天。","忽撚柳枝翻一笑，笑侬元是老婆禅。"]},{"t":"春兴 其六","f":"七言律诗","c":["昨冬不寐苦夜永，此月新弦喜昼长。","柳色未黄寒食过，槐芽初绿冷淘香。","西池蝌蚪愁将动，北地鞦韆影不忘。","描写姬姜三百句，白鱼尽饱小巾箱。"]},{"t":"春兴 其七","f":"七言律诗","c":["胡烽信报收秦塞，夷警妖传自赣州。","十万楼船指瓯越，结交邻国且琉球。","不臣赵尉终辞帝，自王田横怕拜侯。","几岛弹丸髡顶物，敢惊沙上一浮鸥。"]},{"t":"春兴 其八","f":"七言律诗","c":["孟光久矣掩泉台，海口新阡此再开。","煖色一天霞影入，寒潮万里雪山来。","迢迢支垄何方发，个个曾扬著处猜。","急买松秧三百本，高阴元仗拂云材。"]},{"t":"送季子微赴李宁武总兵之约","f":"七言律诗","c":["黑貂裘袄尽长安，此去关山雪未残。","挂印曾蒙公子约，解袍应念故人寒。","大豪马邑坟堪吊，天险羊肠路复难。","到后莫须先一拜，未妨长铗向人弹。"]},{"t":"南镇之南原桃树数百花时余数游赏当武陵也道士苦打搅尽伐之忆以诗","f":"七言律诗","c":["镇南亦自有桃源，载酒来寻不计年。","秪为烧茶烦道士，故令闭洞返渔船。","一从春雨花开后，是处朝霞色可怜。","笑我老来无脚力，欲呼船子少船钱。"]},{"t":"二月望后连日夜风甚不减前年而是日二儿书至","f":"七言律诗","c":["天寒地冻正霜宵，被冷风号入帐骄。","贳屋再经飘瓦尽，破炉重补买薪烧。","老牛脊坏堪驮鸟，小犊书来尚滞辽。","好买柴团蔘一搭，急鞭归马补虚劳。"]},{"t":"唐伯虎画崔氏且题次其韵","f":"七言律诗","c":["彷佛相逢待月身，不知今夕是何辰。","行云总作当年散，胡粉空传半面春。","嫁后形容难不老，画中临榻也应陈。","虎头亦是登徒子，特取妖娇动世人。"]},{"t":"吴宣府新膺总督","f":"七言律诗","c":["邸报初翻数叶藤，栋梁今喜楩楠胜。","市场春后皆青草，司马秋来在白登。","天下安危真足仗，眼前修短却难凭。","最怜投辖相知客，不得随车负此情。"]},{"t":"子肃再赴戚总戎所未至死于都下","f":"七言律诗","c":["幕中宾客盛文词，幕府黄金客再持。","共拟归来作生计，不堪老去哭相知。","一春绿草飞蝴蝶，千里黄沙暗鼓鼙。","两地分明谁苦乐，游魂莫遣到家迟。"]},{"t":"红叶","f":"七言律诗","c":["才见芳华照眼新，又看红叶点衣频。","只言春色能娇物，不道秋霜解媚人。","宫水正寒愁字字，吴江初冷锦鳞鳞。","更馀一种閒风景，醉杂黄花野老巾。"]},{"t":"送长洲居山人士贞","f":"七言律诗","c":["客里尊罍每见陪，那能不饮送将归。","歌长筑短堪流泪，雉叫鹰呼未解围。","雨雪尚淹春箨荐，清明还竞夜饧非。","乡风处处从来异，曾宿阊门记忆微。"]},{"t":"五色鹦鹉黄鹦鹉并是圣母所驯各赋 其一","f":"七言律诗","c":["白燕往时呈翰苑，锦鹦今日贡宸居。","万年枝上栖偏丽，百鸟图中态未如。","豢养固知天意在，语言长得圣颜舒。","何因五色鲜成染，自是娲皇炼石馀。"]},{"t":"五色鹦鹉黄鹦鹉并是圣母所驯各赋 其二","f":"七言律诗","c":["合殿风和碧柳丝，嘉禽色占锦纹奇。","兼呈五德灵鸡绶，倒挂孤桐小凤仪。","无数天机临谱绣，有时人语出花枝。","侍儿不用抛红豆，自有佳音慰圣慈。"]},{"t":"五色鹦鹉黄鹦鹉并是圣母所驯各赋 其三","f":"七言律诗","c":["西陇灵禽翡翠妆，稀闻正色染黄裳。","自谈玉殿非关学，却照金笼别有光。","饮啄定应歌帝力，生成何幸禀中央。","千秋万岁欢无极，土德坤舆本肇祥。"]},{"t":"五色鹦鹉黄鹦鹉并是圣母所驯各赋 其四","f":"七言律诗","c":["鹦鹉由来只翠衿，中央正色见于今。","将悬半映初生柳，欲绣全宜细缕金。","教言一一闻清禁，衔果时时摘上林。","不是黄筌能画取，谁知殿角有祥禽。"]},{"t":"赏成氏牡丹和韵","f":"七言律诗","c":["将军台馆俯林泉，春后名花几日鲜。","一本千金非不贵，数杯深夜转堪怜。","却披半晕当亭下，似出残妆媚客前。","遥忆旧京欢赏处，马蹄尘土踏成烟。"]},{"t":"王翁八十令书贞松白石画中","f":"七言律诗","c":["乡里丈人谁最贤，竹斋先生无间然。","八旬尚有婴儿色，三老重登国学筵。","春社插花人醉后，秋蝇作字夜灯前。","庭中桂子森如玉，白石长松好共悬。"]},{"t":"姚崇明晚映堂","f":"七言律诗","c":["粉额县题晚映堂，主人留客夜焚香。","提壶不必过邻店，买笋真教拣破塘。","彭泽俸钱多备酒，崇明宦橐止栽桑。","僦居幸得为邻舍，伏腊长招醉酒浆。"]},{"t":"寿马先生七十","f":"七言律诗","c":["流朱拂茜杂轻霞，庭畔重县讲日纱。","一竹青青支国杖，数榴洒洒动江花。","社筵推长今三席，州郡分春巳万家。","自笑传经老徐孺，犹将诗说注虫虾。"]},{"t":"元夕寄金武康","f":"七言律诗","c":["曾醉春街典破裘，那堪老去却囊头。","鼠凌白昼争人食，雨共青灯管夜愁。","万户新妆哗月镜，一天彩胜乱风毬。","流思忽到苕西路，似见弦歌拥子游。"]},{"t":"戊辰廿有四日尚宾时中宿于圜夜大风雨冰厚尺诘朝得子甘北报走笔遍诸友","f":"七言律诗","c":["梦里分明梦塞鸿，朝来便有鲤鱼通。","话深白榻三人雨，冰断黄河一夜风。","马惫岂堪重蹀躞，乌飞何苦辨雌雄。","云天万里尝嫌窄，恰作庖鸡镇日笼。"]},{"t":"玉师挽章","f":"七言律诗","c":["只鞋葱岭去三年，两瓮团团岭个边。","劫火只思将骨化，寒花依旧护人眠。","我虽活在如笼鸟，子巳潇然作蜕蝉。","安得骑牛天竺道，月明重话三生缘。"]},{"t":"养生书成纪事与梦","f":"古风","c":["黄梁换色道书成，紫甲更来梦里呈。","孝妇不冤终有雨，水禽持?一何晴。","中郎赎命悭修史，叔夜滨刑且养生。","见说渔翁冯一叶，波掀浪稳付前程。"]},{"t":"某氏新园","f":"七言律诗","c":["买地铺山引露浓，中县洞壑亚玲珑。","抽将菡萏谁边水，割取蓬瀛若个峰。","江左枯棋宜别墅，襄阳落日醉山翁。","花枝尽媚当尊客，莫辨金钗座上红。"]},{"t":"送赵大理","f":"七言律诗","c":["才闻归马驻双轮，又见旌麾动去尘。","廷尉由来须长者，武侯聊借服南人。","昨经湘水洲兰莫，今渡黄河岸草春。","万里波涛随意挽，相逢处处有枯鳞。"]},{"t":"绿牡丹","f":"七言律诗","c":["牡丹绿者未曾闻，狡狯司花此弄新。","汉水鸭头教作帔，陇山鹦鹉未呼人。","韩郎顷刻愁难学，酒辈逡巡醉可频。","不羡张家回道士，自抛红粉练庚辛。"]},{"t":"次苏长公雪诗 其一","f":"七言律诗","c":["翩如中舞玉人纤，皎似禅宗戒律严。","姑去尽留云母粉，客来只醉水晶盐。","正愁黄独迷镵柄，故压梅花入帽檐。","埋没远山知几许，且收螺子画眉尖。"]},{"t":"次苏长公雪诗 其二","f":"七言律诗","c":["白糁堆寒没曙鸦，姨家风急搅银车。","翻将灞水驴边色，忽点孤山墓上花。","何物黄冠滕六友，相思白舫戴逵家。","今朝穆满觞黄竹，笑指银泥画戟叉。"]},{"t":"次苏长公雪诗 其三","f":"七言律诗","c":["固知袅袅不胜纤，亦有棱棱庄且严。","剑底白猿鏖越女，槎头黑瘿粉无盐。","冰初势巳寒千仞，霁后人多曝一檐。","笑忆小姬誇党日，可教轻试茗芽尖。"]},{"t":"次苏长公雪诗 其四","f":"七言律诗","c":["海上青山插髻鸦，海鲛输织不论车。","尽教一夜裁绡叶，那得倾都不奈花。","粉屐特停渔者榼，赤梢并付酒人家。","蚨郎迫使刘伶去，忍别青旗燕尾叉。"]},{"t":"青州赠鼍矶研副以诗奉答","f":"七言律诗","c":["恭承锦字题文石，尚带青州海气浓。","蜃影几痕疑墨绣，雀台万瓦贱漳铜。","醉来好蘸张颠发，老去羞笺郑氏虫。","应有红丝螭匣底，宫鬟争捧写蘋风。"]},{"t":"莫老至聋矣","f":"七言律诗","c":["几度相逢莫丈人，几年断却耳根尘。","新潮正险君何冒，旧雨重来话只陈。","梅树一堤通处士，桃花双板闭渔津。","诗名到处南金重，自叹工诗老更贫。"]},{"t":"八月十八日阿枳三江观潮夜归示 其一","f":"七言律诗","c":["东来小港入潮枯，总直潮辰只大都。","父老犹谈钱氏弩，波涛终奉浙江符。","一城菜熟须盐急，百笠芦长缚蟹粗。","却问黄尘飞未得，秪言咸湿满头颅。"]},{"t":"八月十八日阿枳三江观潮夜归示 其二","f":"七言律诗","c":["闻道黄熊伯子宫，银山银海走银虹。","千花竞蹙鱼龙后，万里长来日月东。","河伯正骄秋水舌，非神亦弄广陵风。","莲姬自爱潮多信，看弄潮儿欲嫁侬。"]},{"t":"八月十八日阿枳三江观潮夜归示 其三","f":"七言律诗","c":["胡马帆樯故不禁，鸣潮故避大江深。","非关冰许滹沱合，信是鳅高海浪沈。","处处新妆邀步袜，年年旧雪涨城阴。","阿宣也锁书堂去，独曳青藜咏玉簪。"]},{"t":"戏拟不往","f":"七言律诗","c":["白头笋箨斋中坐，赤脚莲花顶上行。","九节閒将邛竹杖，一筹输与老门生。","迩来奼嫁粗酬债，此去风波任打萍。","五岳高头谁掖我，肉身菩萨未身轻。"]},{"t":"读某悯妇吊集","f":"七言律诗","c":["孀镜难教两处明，空桑真见一儿生。","喷乾口血枭初大，綵落梁尘雉自经。","寸骨峥嵘争壑雪，百吟风雨响窗晴。","急须一本弹渔鼓，恐有中郎别唱行。"]},{"t":"拟吊苏小墓","f":"七言律诗","c":["一抔苏小是耶非，绣口花腮烂舞衣。","自古佳人难再得，从今虑翼罢双飞。","薤边露眼啼痕浅，松下同心结带稀。","恨不颠狂如大阮，欠将一哭恸兵闺。"]},{"t":"闻里中有买得扶桑花者 其一","f":"古风","c":["忆别汤江五十霜，蛮花长忆烂扶桑。","陆郎第尔知何等，赵尉㘽侬定几行。","蜀魄啼?乾夜夜，猩魂搏血湿苍苍。","狂香结态堪谁比，个是憨儿醉后妆。"]},{"t":"闻里中有买得扶桑花者 其二","f":"七言律诗","c":["炎花冷蕊逐时开，当取当垆著处陪。","海女缠头虽绛帕，江枫落叶亦殷腮。","千金知向何番买，一朵分簪破帽来。","夺取胭脂等閒事，只愁儿女太安排。"]},{"t":"闻里中有买得扶桑花者 其三","f":"七言律诗","c":["箧茜奁螺取次将，长红大翠尽蛮娘。","阑干笑语腮堪译，浣火衫裙焰未凉。","白浪有缘陪贾客，江潮无伴醉槟榔。","吾乡恶热连年更，带得蒲葵上海航。"]},{"t":"闻里中有买得扶桑花者 其四","f":"七言律诗","c":["鹤林寺里别袈裟，又幻扶桑到若耶。","溪女惜香还菡萏，海人浇醉歇枇杷。","似闻此地春犹雪，悔上孤帆晓载霞。","腊社少年貂帽上，簪红莫忘遍茶花。"]},{"t":"今来自岭海者云扶桑花也予昔所见殊不类是殆大苏所咏涓涓泣露紫含笑焰焰烧空红拂桑耳花家剪双头见寄始觉首四作之误乘酒漫成六首以赎差错插砚水瓶嫣然有笑语意岂亦怜老人之衰眊耶复取馀沥浇之当缠头耳滇蜀村歌云披蓑衣打杖头鼓风流在何处予拟答乡谚云雪落长江里依旧化作水何不落则雨却要是个底不知花神有知作何平章夜见梦云叟所谓黄连树下弹琴也 其一","f":"七言律诗","c":["昔者曾怜佛桑贱，今来却见贵扶桑。","天鸡叫罢日才上，海蜃楼高霞正忙。","此时此花染欲醉，是株是朵茜成行。","都争茜颊堪千镒，谁问莲花似六郎。"]},{"t":"今来自岭海者云扶桑花也予昔所见殊不类是殆大苏所咏涓涓泣露紫含笑焰焰烧空红拂桑耳花家剪双头见寄始觉首四作之误乘酒漫成六首以赎差错插砚水瓶嫣然有笑语意岂亦怜老人之衰眊耶复取馀沥浇之当缠头耳滇蜀村歌云披蓑衣打杖头鼓风流在何处予拟答乡谚云雪落长江里依旧化作水何不落则雨却要是个底不知花神有知作何平章夜见梦云叟所谓黄连树下弹琴也 其二","f":"七言律诗","c":["夭乔万里忘风土，天地中州若雨旸。","面面燕支凌虏妾，家家蝴蝶过邻墙。","巳闻好事狂通国，会见名园贱洛阳。","剩叶可医蚕病不，大家春箔卧银僵。"]},{"t":"今来自岭海者云扶桑花也予昔所见殊不类是殆大苏所咏涓涓泣露紫含笑焰焰烧空红拂桑耳花家剪双头见寄始觉首四作之误乘酒漫成六首以赎差错插砚水瓶嫣然有笑语意岂亦怜老人之衰眊耶复取馀沥浇之当缠头耳滇蜀村歌云披蓑衣打杖头鼓风流在何处予拟答乡谚云雪落长江里依旧化作水何不落则雨却要是个底不知花神有知作何平章夜见梦云叟所谓黄连树下弹琴也 其三","f":"七言律诗","c":["扶桑一掷百樗蒱，贾舶槌蚨罄镪涂。","万钵锹锄宁汝愿，几春烂熳为谁都。","盍从海岛陪田客，故试淮泥可木奴。","欲借边鸾花鸟手，为添王会百花图。"]},{"t":"今来自岭海者云扶桑花也予昔所见殊不类是殆大苏所咏涓涓泣露紫含笑焰焰烧空红拂桑耳花家剪双头见寄始觉首四作之误乘酒漫成六首以赎差错插砚水瓶嫣然有笑语意岂亦怜老人之衰眊耶复取馀沥浇之当缠头耳滇蜀村歌云披蓑衣打杖头鼓风流在何处予拟答乡谚云雪落长江里依旧化作水何不落则雨却要是个底不知花神有知作何平章夜见梦云叟所谓黄连树下弹琴也 其四","f":"七言律诗","c":["翠幄青栏半面扶，烘脂炙粉照苍梧。","稍疑垆妇频中酒，莫认昭君肯嫁胡。","幸尔波帆收北指，惭余霜鬓对东涂。","嫣然一笑如相问，侬是南鹏第几雏。"]},{"t":"今来自岭海者云扶桑花也予昔所见殊不类是殆大苏所咏涓涓泣露紫含笑焰焰烧空红拂桑耳花家剪双头见寄始觉首四作之误乘酒漫成六首以赎差错插砚水瓶嫣然有笑语意岂亦怜老人之衰眊耶复取馀沥浇之当缠头耳滇蜀村歌云披蓑衣打杖头鼓风流在何处予拟答乡谚云雪落长江里依旧化作水何不落则雨却要是个底不知花神有知作何平章夜见梦云叟所谓黄连树下弹琴也 其五","f":"七言律诗","c":["煖红滴滴两名娃，插向磁瓶研水些。","崔閤小纱缝杏子，石家人剪襞榴花。","无橐可倾河朔饮，有侬堪老邵平瓜。","矮檐破壁还愁汝，雨恶风狂燕掠斜。"]},{"t":"今来自岭海者云扶桑花也予昔所见殊不类是殆大苏所咏涓涓泣露紫含笑焰焰烧空红拂桑耳花家剪双头见寄始觉首四作之误乘酒漫成六首以赎差错插砚水瓶嫣然有笑语意岂亦怜老人之衰眊耶复取馀沥浇之当缠头耳滇蜀村歌云披蓑衣打杖头鼓风流在何处予拟答乡谚云雪落长江里依旧化作水何不落则雨却要是个底不知花神有知作何平章夜见梦云叟所谓黄连树下弹琴也 其六","f":"七言律诗","c":["将军池馆有王戎，何似扶桑到海东。","过岭风尘双袖暗，际天烟涨一裙红。","细腰回雪憎魔女，浓颊围灯笑醉翁。","寄语寒温须着意，别来泪血尚溶溶。"]},{"t":"寄吴通府以墨见寄","f":"七言律诗","c":["紫髯旧映郡斋长，闻道髯今亦著霜。","去定将军呵醉尉，生犹碑字满襄阳。","残躯乍别阿鼻鬼，宝匣遥飞片脑香。","近日东陵瓜好不，几从炎热转清凉。"]},{"t":"魏文靖公卮贮以梓匣辄赋","f":"七言律诗","c":["魏家名德并恢恢，魏氏宗彝并伟瑰。","既有贞观丞相笏，复传文靖钜公杯。","金螭百只誇谁氏，火色千陶翠此枚。","贳取邻醅赏新购，先浇一滴向西飞。"]},{"t":"卖貂","f":"七言律诗","c":["市上挟葛塞眼黄，将貂往市不成羊。","孟尝一腋收狐白，季子千金敝洛阳。","固是此方饶毒热，亦窥生事正空囊。","鹿皮破尽惟斑在，大雪关门拥坏床。"]},{"t":"卖磬","f":"七言律诗","c":["贫来一石不能留，解赠王郎愧取酬。","庄舄恋乡声自旧，金人辞汉泪长流。","半肩荷蒉过门诮，一叶师襄入海游。","寄语春秋休责备，后来能有此人不。"]},{"t":"卖画","f":"古风","c":["一束丹青半贽诗，稍如吏部长安时。","萧条客舍弹棋得，流落人间作记垂。","到处冯将临赝估，倾箱?共蠹鱼饥。","卧游忽夺正惆怅，壁隙何遮风太吹。"]},{"t":"卖书","f":"七言律诗","c":["贝叶千翻粟一提，持经换饱笑僧尼。","僮书我亦王家作，偶散谁非大块泥。","带草连年高纂述，中箱一日去筌蹄。","聊堆剩本充高枕，一字不看眠日低。"]},{"t":"长至次朝","f":"七言律诗","c":["昨日凉云绛色微，朝来南鸟北笼飞。","一丸自弄玄黄剧，百线争穿傀儡机。","小劫鳌蹄撑略住，大人龙伯负将归。","何年姤复鞭为马，数尽河沙未放鞿。"]},{"t":"某君生朝抹牡丹为寿","f":"七言律诗","c":["道德固为长久物，崇高亦是圣贤嘉。","莫言白首疏狂客，也䫉朱阑富贵花。","一研温风轻散冻，数尖浓叶醉涂鸦。","试教挂向西京宅，未许尧夫算有涯。"]},{"t":"十月廿二日园西樱桃数花便有蝶至 其一","f":"七言律诗","c":["令节初冬逼下旬，樱桃数杪著花新。","天寒翠袖宜深幕，日莫红帘讶美人。","小颊预施三月粉，微脂未褪昨宵唇。","梨花定不开天上，百姓人家借小春。"]},{"t":"十月廿二日园西樱桃数花便有蝶至 其二","f":"七言律诗","c":["夏实每看当鸟尽，冬花何事向人妍。","不堪憔悴行吟后，故弄阳春欲雪前。","正苦白头愁兀兀，谁家黄蝶过娟娟。","杖藜立断斜阳影，泪尽西风送菊天。"]},{"t":"九月朔与诸友醉某子长安邸舍得花字","f":"七言律诗","c":["满庭山色半阑花，觞曲交飞古侠家。","肝胆易倾除酒畔，弟兄难会最天涯。","不教酩酊归何事，望到茱萸节尚赊。","烛暗沟浑都莫虑，近来官道铲堆沙。"]},{"t":"桐乡冯母 其一","f":"七言律诗","c":["三迁近俎苦霜时，一尺殊恩湛露垂。","自古男儿婴曰少，谁家嫠妇帝王知。","高斋客饭宁辞发，落叶寒机几断丝。","见说仙郎栖海曲，更无鱼鲊到塘西。"]},{"t":"桐乡冯母 其二","f":"七言律诗","c":["青史他年定几行，太夫人传在中央。","不须窃药居明月，自解将心结暗霜。","片匣远飞鸾字重，单雌亲刷凤毛长。","罗敷虽老携筐在，付与吴姬出采桑。"]},{"t":"画鱼既作古诗矣久之复得七律","f":"七言律诗","c":["兹图稍似少陵诗，微风吹雨出鱼儿。","尺梢讵许牛涔活，远水何劳象队移。","是处有鱼争聚网，画心无獭稳摇鬐。","五侯刀几知多少，免尔为鲭正在斯。"]},{"t":"拟送巡滇者 其一","f":"七言律诗","c":["握节新为万里行，何人不羡旧书生。","一簪白笔襜帷冷，几驿红毡祖道平。","清净共推周柱下，纠弹交指沭黔宁。","故家门第须乔木，何况先皇许世臣。"]},{"t":"拟送巡滇者 其二","f":"七言律诗","c":["孟密土官争宝井，临安那大反狂酋。","两番并属先人抚，一字曾无太史收。","正值同袍巡此地，却嫌泥壁向高头。","况无杯酒为侬别，安得忉忉絮所求。"]},{"t":"过伯升宅玩骨董而菖蒲尤盛鱼有红色有蓝色有玉有锦俱三尾如鼎又有水晶四尾者","f":"七言律诗","c":["菖蒲钵钵虎须抽，玳瑁盆盆锦鲫浮。","衰老一尘几不染，小儿百件欲拿周。","言归肯问迟和早，再到宁知得与不。","落日青山三四点，几回舟子促回舟。"]},{"t":"雪中移居 其一","f":"七言律诗","c":["十度移家四十年，今来移迫莫冬天。","破书一束苦湿雪，折足双铛愁断烟。","罗雀是门都解冷，啼莺换谷不成迁。","只堪醉咏梅花下，其奈杖头无酒钱。"]},{"t":"雪中移居 其二","f":"七言律诗","c":["高雪压瓦轰折椽，跋冻移家劳可怜。","长须赤脚泥一尺，买佣呼酒赊百钱。","饥鸟待我彼檐外，梅花送客此窗前。","百苦千愁不在念，肠断茫茫黯黯天。"]},{"t":"送娄某丞丹阳","f":"七言律诗","c":["吾兄骢马后昆贤，今佐鸣琴倍洒然。","双杪长松厅事后，三吴流水大江边。","应怜道路疲迎送，莫买鲟鳇糜俸钱。","他日相过莫相忘，金山顶上酌清泉。"]},{"t":"答嘉则","f":"七言律诗","c":["十年才一问平安，只尺浑如对面看。","旧日诗评虽有价，近来公论孰登坛。","百年忽巳崦嵫暮，一齿时崩苜蓿盘。","腊雪秋潮同马日，何人不道是金兰。"]},{"t":"诣五泄驴上口占寄骆怀远","f":"七言律诗","c":["胜赏犹县百里堤，蹄僵路滑不胜泥。","溪山待客寒云外，雨雪逢君枫树西。","束带岂难官自懒，尺箠不重老能提。","何由共辔苍苔上，指与诸峰一一题。"]},{"t":"九流","f":"七言律诗","c":["九流渭也落何流，戴发星星一比丘。","红袖曾酣楼上舞，黑风仍堕海洋舟。","偷醅毕卓生为酒，辟谷张良死在留。","每枉尊罍思一报，几时将辖井中投。"]},{"t":"鸡声","f":"七言律诗","c":["云中丹灶伴神仙，亦有栖迟高树颠。","向夕既来回客梦，凌晨特去喨霜天。","韵飘篱外雏俱集，颈涨花前绣愈圆。","不似吴门塘上鸭，只将名姓向人宣。"]},{"t":"蛙声","f":"七言律诗","c":["陂塘科斗书犹易，海国侏儒译较难。","草际不知何物语，灯前直听几宵阑。","榴风为递愁蛇觉，梅雨交喧乱鸭栏。","五寸即且留不得，令人为尔发长叹。"]},{"t":"闻有赋坏翅鹤者予尝伤事废餐羸眩致跌右臂骨脱突肩臼昨冬涉夏复病脚软必杖而后行兹也感仙癯之易贼羡令威而不皆横榻哀吟辄得二首 其一","f":"七言律诗","c":["泽国秋飙海色鲜，飞腾无计只颓然。","双栖入夜遮烟独，半影拖花写雪偏。","衣袒右肩慵梵客，柳生左肘任皇天。","可怜独剩沧溟气，乞与昂藏步榻边。"]},{"t":"闻有赋坏翅鹤者予尝伤事废餐羸眩致跌右臂骨脱突肩臼昨冬涉夏复病脚软必杖而后行兹也感仙癯之易贼羡令威而不皆横榻哀吟辄得二首 其二","f":"古风","c":["欲鸣不鸣拍不禁，况复苍苍万里心。","舞袖今馀两垂手，曝衣惟障一边阴。","不辞摇拽将池绕，似解跰?照井深。","倾国捧心翻所贵，一庭欹影换清吟。"]},{"t":"建阳李君寄驯鹇俄殪野狸信至燕哀以三曲 其一","f":"七言律诗","c":["鱼鸟寻盟未许同，冥栖谁复伴龙钟。","荒栏取食曾呼掌，绣尾回霜罢扫笼。","老去逢愁消不易，秋来见月放成空。","定知此夜魂游处，多在武夷山水中。"]},{"t":"建阳李君寄驯鹇俄殪野狸信至燕哀以三曲 其二","f":"七言律诗","c":["索姿驯态碧山空，剧爪贪涎一饱充。","残粟几乾遗瓮水，落花时起堕毛风。","千里提携两蛮峤，四回豢养一飘蓬。","将诗换得胡家者，向后不知何所终。"]},{"t":"建阳李君寄驯鹇俄殪野狸信至燕哀以三曲 其三","f":"七言律诗","c":["忆昨含悽下主庭，殊方远嫁俨姬嬴。","正怜妙羽摇孤雪，忍为饥饕烂一腥。","草色应枯武夷道，书闻亦湿建阳缨。","情钟此辈非关癖，猿鹤年来一壑情。"]},{"t":"赋得万绿枝头红一点","f":"古风","c":["名园树树老啼莺，叶底孤花巧弄春。","巳?浓阴浑覆鸟，独留残艳尚撩人。","青楼百座迎桃叶，翠袖倾宫捧太真。","记得陇西长吉语，斗筲如海为朱唇。"]},{"t":"王乡人寻二十年之父榇归自卫辉合其母圹","f":"七言律诗","c":["寄埋丛冢北邙同，有客求尸万莽中。","白骨两乡儿得父，黄泉一笑妪迎翁。","泪馀指点居亭老，血尽锹函夜壑红。","千古灯檠归榇事，莫论真膺总输侬。"]},{"t":"赋得渔人网集澄潭下","f":"七言律诗","c":["红椒碧鲊数夔州，百网家家白鹭洲。","柳外鸣榔喧隔浦，夜来燃竹满中流。","长鲸未必愁连弩，公子仍烦饵一牛。","提向酒家都藿叶，可怜无计避铛油。"]},{"t":"十七夕","f":"七言律诗","c":["银带边儿骏马驮，西墙倒酒剧悬河。","高松入座无人对，明月当杯奈夜何。","此际乡心愁不少，满城流水响无多。","东房老衲怜牢落，夜夜来吹鹘打鹅。"]},{"t":"赋得贾客船随返照来","f":"七言律诗","c":["千金不惜买鸣筝，万斛鱼盐水上行。","几度烟波愁日莫，半程风物趁天晴。","西郊鹳鹤摩云入，困道舲舠晚饭迎。","笑指红霞如有意，乾衣骑马广陵城。"]},{"t":"书刘子梅谱 其一","f":"七言律诗","c":["曳裾才谢楚江兰，却写梅花赠岁寒。","马上不殊新折寄，雪中又少旧年看。","影从棘畔墙俱白，挂到宵阑月倍团。","分付东风好将护，他年山馆障阑干。"]},{"t":"书刘子梅谱 其二","f":"七言律诗","c":["江南风物在新春，笔底生花幻水村。","似月付将千片影，因风欲动一窗痕。","逢人固是难攀折，入帐还应恼梦魂。","笑杀朝来无粒米，呼童捲向市边门。"]},{"t":"送某之太仓","f":"七言律诗","c":["吴中曾客几经年，此去书帷得主贤。","潮认旧人频到岸，燕穿新柳特迎船。","芦芽白白河豚上，梅雨昏昏海国眠。","应忆越山笼鹤在，长于月出叫孤圆。"]},{"t":"将牧羊庚戌元旦筮之得明夷之上六","f":"七言律诗","c":["入地登天两不妨，从来作戏在逢场。","门前昼静堪罗雀，城上春深好牧羊。","披褐家门孙令尹，入山经纪卜中郎。","已知此意无人会，閒坐看云点太阳。"]},{"t":"元夕休宁道中遥忆乡里","f":"七言律诗","c":["陌上双双结袂频，翩如飞燕蹴轻尘。","一年乐事花流水，几夜他乡月照人。","驿路酒家留去马，溪桥梅色弄新春。","相随惟有孤龙剑，会向囊中笑客贫。"]},{"t":"赋得清秋落叶","f":"七言律诗","c":["白帝乘秋秉素蜺，青娥挟露弄风威。","荣枯不敢违天意，摇落偏当寄客衣。","大漠霜凄随角散，孤城月白伴砧飞。","镜中不久繁桃李，愁杀秦川织锦机。"]},{"t":"凊风岭","f":"七言律诗","c":["赤霞城畔女郎身，曾将罗袖障胡尘。","半岩竹泪犹啼月，一水菱花解照人。","那取藁砧还破镜，秪持完壁碎强秦。","江天风雨来何急，似觉诗成泣鬼神。"]},{"t":"焦山","f":"七言律诗","c":["徵君祠庙碧山隈，僧舍中流面面开。","全楚客帆遮浦下，广陵涛色漫窗来。","曝鼋何事当牛触，养鹤翻劳刻石埋。","隔取深泥题不得，空持黄绢立磨厓。"]},{"t":"林先生迁教泷水","f":"七言律诗","c":["特将一铎岭南行，水郭山邮路几程。","方为郡人教弟子，又从海国领诸生。","石中鸲鹆当泥迸，帐里桄榔入夏清。","莫以遐荒频作念，古来谁不重端城。"]},{"t":"读易园诗应一仕人之索","f":"七言律诗","c":["为园读易几卢都，归藏连山尽野狐。","大过久无仍假我，绝韦犹在尽伊吾。","百茎蓍草龟相守，一角梅花鹤自呼。","曾与京焦相问难，至今记得石渠无。"]},{"t":"马策之奉母住凤凰山下之水楼","f":"七言律诗","c":["凤凰山下绕清流，策也迎亲住此洲。","正好敲冰求尺鲤，倍宜垂雪饭高楼。","月中醉客摇船夜，露下听虫助竹秋。","何日细鳞随网得，招予沽酒柳桥头。"]},{"t":"狐裘","f":"七言律诗","c":["狐裘赊去止三金，大海投鱼两岁沈。","鹰马趁风嫌未急，檐阶负日苦长阴。","歌闻未必如金石，肘见真应捉领襟。","犹喜雪宵看信国，发冲冠顶汗淋淋。"]},{"t":"岁暮夜雪招二王诗人齑果小饮","f":"七言律诗","c":["二王二王来何难，榼榼清酤顿欲乾。","何处王门无短衱，最傩客路是长安。","齑盐雪糁充瓶立，蔗藕霜消饱膈酸。","四海论交头尽白，至今胆落醴交寒。"]},{"t":"宣府槐龙篇","f":"古风","c":["大树将军号，乔松大夫封。","何如兹茂荫，宛尔作深笼。","目目尖成兔，条条结绾龙。","乘凉翠葆飒，撑暑碧油烘。","开府何年买，天王旧物钟。","宾觞飞递外，塞略坐筹中。","鹏翼垂天下，龟裙覆海穹。","柯南蚁垒国，甃北乳方泓。","的的朱门照，霏霏绿雾濛。","干云榆所接，影月桂能通。","赭荚承新蜕，青丝断坠虫。","五楹团广厦，百柱卓雄风。","大漠驯骄子，长城属令公。","一枝阴虏马，半叶扫边烽。","矢石无忘备，尊罍稍可从。","先朝勤灌溉，后代倚幢?。","虬拟皇情悦，黄犹御气蒙。","长陵如可作，愿柱大明宫。"]},{"t":"水仙","f":"五言古诗","c":["弃粉当妆匣，抛脂落茜坡。","黄姑插金雁，织女洗银河。","敢以人间色，来方天上娥。","借烟行作雨，不黛扫成蛾。","渡海群骑燕，横江或跨鹅。","盈盈素罗袜，泛泛绿鳞波。","剩馥迷湘芷，馀娇付越荷。","兔房秋杵药，鲛室夜珠梭。","道子描难似，非烟绣不过。","张颠狂草笔，涂罢一高歌。"]},{"t":"万历二年翰林院中白燕双乳辅臣以 献进两宫并赏殊瑞闻而赋之","f":"五言古诗","c":["白燕自何方，双娇乳玉堂。","若非翻向壁，只道斲从梁。","易许青藜映，难教黑扇藏。","宫钗今两只，巷口几斜阳。","并语栽薇处，交栖视草旁。","春情堪与译，秋翮好填潢。","御水沿沟岸，名园隔苑墙。","穿花雪片叠，落絮剪刀长。","递拂宵麻素，争摇晓禁苍。","随珂迷贾至，遮字冷孙康。","未及郊禖候，先歌命鸟章。","两宫看带笑，万乘盻生光。","或向罘罳度，闲冯女寺量。","江南来舞苧，海国堕绡裆。","哺蝶欺残粉，捎蜂糁嫩黄。","古词卑苜蓿，新曲断沧浪。","出入皆清禁，差池半紫房。","姬姜红线系，姊妹缟巾扬。","巷咏偏谐谑，延裁必雅庄。","冰霜俱入句，咀嚼总生凉。","饮啄如知介，飞鸣迥不常。","琼瑶报圣主，文彩伴仙郎。","自古生贤佐，多因尔兆祥。","试看今稷契，还奉旧虞唐。"]},{"t":"送史叔考读书兵坑","f":"五言古诗","c":["连岁赓酬久，兹晨伴侣稀。","百觥浇鹤卯，一砚匣鼍矶。","渐到鸣滩岸，微穿聚叶晖。","穷经朱简断，拓字墨光肥。","霜白兴鸡早，茅红掣兔飞。","逐时文股丽，入悟习心非。","水远缄鱼断，山深脯兽晞。","客来供鹿蹠，雉下警罗扉。","竹筏何曾烂，耽玄自不归。"]},{"t":"观浴象","f":"五言古诗","c":["帝京初伏候，出象浴城湍。","乍映长壕黑，时泅巨浪漫。","有颠皆积垢，无尾不藏瘢。","出没漩涡口，崔嵬甃岸端。","巴蛇吞未下，滟石浸还乾。","决荡粗泥落，吹喷细雪残。","鼻卷荷屈水，牙划藕穿澜。","逐队趋蹄易，呼群拭背难。","秣刍厮养习，湔刷羽林官。","并是生殊域，同来饲一阑。","不争俦力大，共荷主恩宽。","带湿惊钩铁，携凉卧藁抟。","鼋鼍心不畏，鼠豕额何攒。","昨日谁狂走，今朝尔顿安。","从兹须自爱，莫更损阑干。"]},{"t":"和葛景文","f":"五言古诗","c":["十丈高垣地，团团绕棘柴。","青天县鲋涸，黑洞锁龙乖。","不以无穷变，来萦有尽怀。","提壶向前去，付锸许渠埋。","每剖遗鱼素，翻思去鸟偕。","真成秋落羽，欲插上冲骸。"]},{"t":"抱琴美人图","f":"五言古诗","c":["身去盻犹转，抱琴何处来。","定知清夜里，去听长卿回。","细细腰宜舞，轻轻步懒催。","睡浓妆略淡，性慧相多猜。","眉下波含柳，颅心风落梅。","对人莲欲语，袖手藕藏荄。","浣水倾吴国，为云到楚台。","带飞修曳缟，佩响细衡瑰。","绿帐愁单掩，朱唇似善诙。","冰弦写离怨，洞閤远諠豗。","晓户玲珑启，春花次第开。","相将折芍药，掩映过莓苔。","蜀国倡娇薛，河中色妙崔。","试将同伫立，正惬两徘徊。","宫髻发一尺，明珠环两枚。","自然宜淡扫，故不画烟煤。","或荐珊瑚枕，如倾玳瑁杯。","息芳将近近，粉腻愈皑皑。","按曲回成雪，徵车响轶雷。","翟衣真帝也，荇菜合悠哉。","箜篌传丽玉，琵琶伏善才。","何如鼓流水，真若溯沿洄。","别鹤引如弄，求凰调转哀。","有人于座上，奈尔隔屏隈。","采药人闻阮，游仙者姓裴。","不言偶襄汉，定说见天台。","巧笑金难买，多香玉借胎。","绣穿新样领，绶结古文罍。","皎似珠游浦，清如露滴槐。","采花棚上竹，斗草砌隅台。","约伴携双手，怀人在两腮。","鸳鸯何处觅，鹦鹉有时挼。","增减俱难中，短长元自该。","赵妃宅里妹，宋玉里中魁。","宛尔凝如望，嫣然乍可偎。","临波即帝子，食肉亦蓬莱。","懊恼思金谷，阑干哭马嵬。","流波与流态，令稿复令灰。","绝代诚难得，瑰姿理莫推。","如斯落鱼雁，母乃梦蛇虺。","侠客气何壮，佳人弃若隤。","将来换骏马，期在得高騋。","艳冶非不爱，纵横良有材。","从他形袅袅，不恋志恢恢。","凑两难为粲，为屏并作傀。","麝香新热饼，兽鼎旧安能。","兹画何人染，钱塘漆子裁。","拂暾惊卧榻，助腕汲新醅。","持过西陵下，因啼苏小堆。","青松帷下鸟，红颊巳成煨。","潮长日初仄，春深草渐莓。","山家时嗾犬，捕雉又张䍙。","上下凫鸥没，擎拳翡翠毸。","物华迅流转，颜色总尘埃。","处女元吾守，明时肯自媒。","有时求柱桷，不信舍徂徕。","忌嫉生宫阃，刍梁饱驽胎。","秪闻饥婉恋，不见斥虺尵。","戏论摛多韵，谈虚遍九垓。","性空色不著，养致体逾颓。","既巳成图画，其何忍剥摧。","屏图装巳匝，花月任为灾。","书舍潇潇影，奇花一一栽。","对卿长比并，顾彼独浇培。","风飒罗帷里，虫鸣玉砌陔。","此时汉武见，又道李魂回。"]},{"t":"先除夕二日雪甚如婴儿拳","f":"五言古诗","c":["腊尽接春将，孤眠枕被凉。","朝兴惊六出，午晏俛千篁。","兀坐愁空瓮，群栖塞坏墙。","抟酥几鹤卵，絮柳未鹅黄。","堪取为毬打，行看挂霤僵。","明年从大有，连岁却馀殃。","见说开元寺，重新古道场。","一髡担化主，十殿敞阎王。","犹记迎春昔，长颓此地觞。","解姬捎诞马，蛮子袄绵羊。","楼角娇波聚，亭椒嫩采妆。","百垆忙酒保，四郭挤村娘。","兽圈攘牛土，虫枝试鸟簧。","不知今日赏，还有此风光。"]},{"t":"画坐草栗鼠","f":"五言古诗","c":["鼠有能跳者，名因嗜栗传。","儿童袖里串，松桧顶尖县。","写跃难为逸，描蹲易犯妍。","臀肥隈草煖，尾大刷瓜圆。","叫唤孤雌别，银铛旧伴牵。","坐思禁一饱，暨产大如拳。"]},{"t":"电","f":"五言古诗","c":["列缺俨睢盱，绯冠绛裤襦。","䃸磹鲜舌哆，烟焰涨天嘘。","侍从排焦额，槐檀塞太虚。","光中藏栲栳，麦处借幡旟。","鸡吐朝官绶，龙逢海豻驱。","阿香开镜数，玉女笑壶输。","好作王戎眼，休烧李绩须。","灭明难捉摸，搜索愈逃逋。","或见焚鳞尾，徒闻绕斗枢。","金蛇穿雨划，赤兔驾雷屠。","煨烬乾坤赭，飞腾日月徐。","闭门遭斧凿，冯塔养蜘蛛。","铛斗何工煅，硫硭若帑储。","旱乾于闪魃，冬蛰伴泥猪。","万瓦穿如瞰，孤窗热欲糜。","淫威神卤莽，侥倖鬼揶揄。","昨夕狂倾潦，群灵俨聚诛。","弥霄红落燕，罄海白跳珠。","但劈梧桐去，何曾打即且。"]},{"t":"芭蕉花","f":"五言古诗","c":["芭蕉种四年，华蕊发茨檐。","玉兰为媵姊，木笔是曾玄。","十一希莲萏，寻常类马肝。","坼难劙海蚌，瓣厚落河蚶。","香色无非敛，蜂胥有自閒。","古妆蚕妇出，立马使君寒。","春久枝俱果，霞长雁正还。","寄书苏蕙老，挟扇婕妤孱。","我昔南过岭，蛮多种在田。","实甜藤俎上，丝冷葛机边。","和荔烧天紫，同椰盖海炎。","别来频屈指，秃后止馀颠。","不道孤亭畔，言抽径尺团。","逡巡无术致，描写恨才悭。","太华尖崩半，平原颍脱刓。","鹿遮樵者梦，鱼沈美人丹。","苦少榴枝泛，珊瑚奉倚栏。"]},{"t":"子侯芳园王瓜骈秀传闻远迩快睹咏歌附骥非才续貂聊漫","f":"五言古诗","c":["老后圃聊便，栽蔬夹芋田。","坏轳牵远井，破屋傍邻椽。","脱帽当茶灶，持劖掘笋鞭。","忽来新莫逆，幸忝旧忘年。","却说渠家圃，如承帝眷惓。","瓜虽非五色，蒂却领双圆。","杵向秋砧挂，旒添晓纩县。","孪胎咽并纽，蜼尾鼻俱穿。","自是生成偶，非关造化偏。","瘿孤羞杜预，面对俨庭坚。","未羡三眠柳，那论并萼莲。","娇黄浓鬓钿，浅黑撅针绵。","花谢知谁后，藤升许孰先。","客欢浮自赏，妇喜用红缠。","野鼠分行抱，墙蜗别队缘。","霜时争画捲，月令特书传。","杨尹诗几首，柳州表一联。","合欢光简策，内履慎周旋。","骈拇从来贱，重■自昔怜。","冯他閒估校，何处定媸妍。"]},{"t":"宴游西郊诗","f":"五言古诗","c":["艾候当龙舫，萍踪集凤城。","凌晨催邸饭，乘暇出郊行。","短短蒲抽玉，交交鸟弄笙。","辞幨排拥蔽，并马得峥嵘。","碧岫红云幻，磁壶白雪擎。","候宾宾未集，顾仆仆频倾。","蒟酱何方至，胡桃朴地横。","骑龙排木凳，剪虎缀冠缨。","綵扇临杯舄，蒲团就几冯。","甲蔬香百种，根拨秀千英。","菡萏含冰脑，樱桃滴水晶。","胡蜂俱仰蜜，家鸽半栖甍。","熟果从枝摘，秾花得叶清。","看馀锦绮色，听断辘轳声。","买竹金千镒，温瓜火一星。","钩弯迟桂魄，流曲拟兰亭。","菱藕堆盘雪，蝇蚊避席冰。","江南浑缩地，塞北总怡情。","折简招群彦，联床胜百朋。","来希主情懒，别易客心惊。","折柳条馀几，牵衣泪镇零。","舞腰宁自赏，歌曲迟侬听。","日炙嫣红袖，风狂散绿萍。","盆供春色满，簟展晚凉迎。","茉莉簪纱帽，玫瑰袅醑觥。","习池淹席幕，金谷较输赢。","可惜朱卿去，偏当赤地晴。","锦帆风不进，玉斝月谁赓。","孤闷当芦发，颓躯倚树撑。","长空生咄唶，懊绪付娉婷。","得意才俱隽，相如赋拟成。","吹嘘真俗话，放浪自浮生。","毬绕飞明月，山来匝翠屏。","归雅分树掠，饥马望刍鸣。","入郭斜榆影，回鞭指柳营。","侯家银烛朗，客座綵帘明。","贝叶书难译，莲筒吸判酲。","辖沈惊座睡，楼迥景阳訇。","朝马摇鸣佩，升乌影画棂。","百川如变海，重此醉长鲸。"]},{"t":"张氏子黄鹦鹉","f":"五言古诗","c":["见说黄鹦鹉，西来自氐羌。","色今分间正，天与改文章。","竟夺春鹂羽，全为汉鹄翔。","能言猩敢并，借染蜜初房。","稍挂杨丝乱，聊毸菊瓣张。","金钗翘卫女，红豆惹萧娘。","恼燕依人紫，愁鹰掠兔苍。","香拳閒铁爪，妙影闪铜梁。","江夏埋词客，秦山问上皇。","赭袍双映浅，芳草一洲长。","梦兆呈妃子，琵琶唤海倡。","性情胎戊巳，音韵合宫商。","百鸟窥应噪，孤凰见必伤。","未能求一友，差可哭三良。","老病浑如昨，新闻喜未尝。","借看如可许，香稻当茶汤。"]},{"t":"后闻鹦鹉眼系直度两眶人可洞视","f":"五言古诗","c":["双瞳穿脑过，对面两菱花。","琥珀钻松窍，琉璃钉扇纱。","隔颠孤碧炯，横准一梁加。","饮啄千峰物，雌雄万树家。","回头忽不见，交睫梦成赊。","摩荡晶初日，玲珑射落霞。","照拳明蕨脑，夹喙影姜芽。","恋月眶寒晕，啼烟泪涩沙。","端州鸲鹆研，蛮郡石榴砂。","睥睨雄生怒，迷离媚作邪。","倾城秋水顾，阿堵虎头誇。","认客休青白，韬光混瑾瑕。","如怜蔡家女，分镜葬琵琶。"]},{"t":"题宋刻丝蓼花立鸟图","f":"五言古诗","c":["江上深秋景，偏于蘋蓼妍。","娟娟啼叶鸟，淡淡入村烟。","生色浑疑画，微丝却是牵。","精时愁吕纪，妙处失黄筌。","久挂方知定，初惊只欲翩。","天孙无限巧，乞与世人传。"]},{"t":"丁卯六月十六日五鼓梦一宪公更讯予狱予颇恳乞且历数古人事宪公乃取片纸手画一白犬从雪中猎作题且曰汝赋得十韵即止予赋得十二句而宪公逡巡起予亦觉半忘矣今续成之","f":"五言古诗","c":["太白高秦雪，材官选汉都。","西獒非远物，冬狩是雄图。","冰溜蹄兼滑，花销毳结酥。","逐方馀狡兔，烹岂遽韩卢。","羽搏纷迷素，毛燖糁共疏。","一声非口吹，万壑遍鹰呼。","驰影争飞霰，蹲身印守株。","穷搜寒愈急，冻尾煖微濡。","固取矜獢猲，还宜解网罟。","莫教将耿雉，文锦碎模糊。"]},{"t":"奉侍少保公宴集龙游之翠光岩","f":"七言古诗","c":["楼船几日下钱塘，胜地临江绮席张。","虎帐山开萝作带，龙潭水积剑为光。","芳羞自出船窗底，妙响偏宜舞扇傍。","日映桅樯兼树密，风吹丝竹袅云长。","渔郎贾客停何事，桂楫兰桡渡不妨。","暂脱锦袍悬翠壁，忽抽彤管拂青缃。","閒中国计筹能悉，醉后兵符发更详。","宝马嘶群行杂锦，红旗悬的射穿杨。","霜前下叶沙俱积，雨后残磾藓更香。","野旷牙官分作队，林疏甲士补成行。","松杉借翠连幢碧，橘柚分金映甲黄。","羽扇周郎临赤壁，轻裘叔子在襄阳。","庾楼无月人犹往，郤幕开风客不藏。","远眺非关耽丽景，雄心先巳到遐荒。","建溪露布风雷急，涧水兵威草木扬。","却与从行诸幕士，维舟九曲泛清觞。"]},{"t":"连雪后迎春忆旧十二韵","f":"古风","c":["土牛一夕添神采，雨霰连朝妒客鞋。","邀队本期相跳踯，踏游不畅只挤排。","冰牢北斗璿玑涩，冻滑东郊仗引乖。","老病似虫吟荜窦，少年如梦忆莲?。","飞香塞巷堪经宿，立帽平檐别墁街。","夺綵连毬追宝马，争梅带雪上金钗。","花房醉客槌朱鹭，水店垆姬馔紫鲑。","小市温淘槐尽叶，贵筵饼饵韭初荄。","萧条邑里难如昨，想象风光未必皆。","是处从今趺尽草，中央偏我立如柴。","一隅掩鼻真成笑，七字瞒心戏作俳。","青帝秪今何处去，勾芒一似不曾来。"]},{"t":"题画 其一","f":"五言绝句","c":["嫩筱捎空碧，高枝梗太清。","总看奔逸势，犹带早雷惊。"]},{"t":"题画 其二","f":"五言绝句","c":["当其寻丈节，数寸蛇与蝉。","化工无笔墨，个字写青天。"]},{"t":"题画 其三","f":"五言绝句","c":["朵朵西施靥，年年墙外窥。","莫嫌妆不澹，带酒未醒时。"]},{"t":"题画 其四","f":"五言绝句","c":["枝枝出墙语，朵朵向人窥。","宋玉邻家女，施朱太赤时。"]},{"t":"扇中双蝶","f":"五言绝句","c":["春至百花繁，名园蛱蝶翻。","美人将扇扑，拓得一双痕。"]},{"t":"蜂","f":"五言绝句","c":["双股粉黄笼，飞迟趁晚风。","君王方课蜜，不敢恋花丛。"]},{"t":"白牡丹桃花","f":"五言绝句","c":["桃艳比夭姬，花王富贵姿。","楚襄春日下，閒坐选蛾眉。"]},{"t":"剪春罗垂丝海棠","f":"五言绝句","c":["美人睡不足，春愁奈若何。","垂丝绿窗下，聊为绣春罗。"]},{"t":"石榴荷花","f":"五言绝句","c":["画得荷花朵，傍依海石榴。","西施夜浴罢，催火照梳头。"]},{"t":"两蝗虫","f":"五言绝句","c":["深雪打茆茨，飞蝗惨不孳。","无由苗上见，画取两雄雌。"]},{"t":"叉萝卜","f":"五言绝句","c":["团内一锄浅，毫端两诧深。","广州初断葛，上党未蒸参。"]},{"t":"回回马","f":"五言绝句","c":["西马入瓜沙，风尘道路赊。","试言如此匹，消得几筐茶。"]},{"t":"毛鱼作队游茭塘","f":"五言绝句","c":["作队撼春萍，双头寸未盈。","老渔暂相借，江海几长鲸。"]},{"t":"画","f":"五言绝句","c":["朱夏郁蒸时，晶瓜碧玉滋。","疏帘三尺雪，小簟一枰棋。"]},{"t":"咏画四首 其一 春","f":"五言绝句","c":["春娇最何物，桃花与杨柳。","惹侬或有诗，市远那得酒。"]},{"t":"咏画四首 其二 夏","f":"五言绝句","c":["城市或嚣炎，在野心不热。","意欲施茶汤，行人他处渴。"]},{"t":"咏画四首 其三 秋","f":"五言绝句","c":["何处住高人，低茅水上贴。","江阔杳难寻，过客指红叶。"]},{"t":"咏画四首 其四 冬","f":"五言绝句","c":["梅花一万梢，红寺五十里。","天晚不到门，雪深没驴耳。"]},{"t":"江船一老看雁群初起","f":"古风","c":["警雁避罗舠，江长起未高。","眼?一饷后，看到入云梢。"]},{"t":"似赤壁游","f":"五言绝句","c":["一艇泛三人，多疑游赤壁。","无处少江山，但无此好客。"]},{"t":"石榴","f":"五言绝句","c":["闺染趋花色，衫裙尚正红。","近娇瓜子茜，贱杀石榴浓。"]},{"t":"竹染绿色","f":"五言绝句","c":["我亦狂涂竹，翻飞水墨梢。","不能将石绿，细写鹦哥毛。"]},{"t":"对岸观崖大瀑","f":"五言绝句","c":["瀑布挂江北，望者江南猜。","雪花那不到，霹雳过江来。"]},{"t":"独钓寒江","f":"五言绝句","c":["大海有鲸鱼，五岳其鼻额。","任公钓不来，烦尔一丝雪。"]},{"t":"阅书者倚老树","f":"五言绝句","c":["尔自作蠹鱼，我不阅一字。","逢著好树根，抱著枕头睡。"]},{"t":"雪景","f":"五言绝句","c":["此际山阴道，啼惟有莫鸦。","万山无寸碧，何处认梅花。"]},{"t":"鱼蟹","f":"五言绝句","c":["夜窗宾主话，秋浦蟹鱼肥。","配饮无钱买，思将画换归。"]},{"t":"杏燕子","f":"五言绝句","c":["玉京红线断，樊素绛唇娇。","好著鞦韆架，其如不解描。"]},{"t":"写竹答许口北年礼","f":"五言绝句","c":["羹鲤稻粱餐，沈思欲答难。","只裁残拜帖，写竹当春盘。"]},{"t":"写兰与仙华子","f":"五言绝句","c":["仙华学杜诗，其词拙而古。","如我写兰竹，无媚有清苦。"]},{"t":"尖头麻蛰","f":"五言绝句","c":["身轻宜歇草，头锐欲钻螺。","正苦毛锥乏，如侬太软何。"]},{"t":"蒲桃","f":"五言绝句","c":["闻道羌葡萄，家家用醅酒。","老夫画笔渴，此时堪一斗。"]},{"t":"张氏别业八首 其一 乐志堂","f":"五言绝句","c":["备言志所乐，何关堂与基。","主人向我道，但看鸟悦枝。"]},{"t":"张氏别业八首 其二 流霞阁","f":"五言绝句","c":["阁中餐霞人，绝无烟火色。","谁宰武陵鸡，来作渔郎食。"]},{"t":"张氏别业八首 其三 竹坞","f":"五言绝句","c":["题诗竹坞中，竹长时出垣。","谁能将铁笔，一画牡丹园。"]},{"t":"张氏别业八首 其四 青莲岛","f":"五言绝句","c":["小岛含巨浸，能滋化叶开。","青莲大如许，跏坐几如来。"]},{"t":"张氏别业八首 其五 小若耶","f":"五言绝句","c":["别沼分湖水，因名小若耶。","水流有大小，却一样荷花。"]},{"t":"张氏别业八首 其六 芙渠径","f":"五言绝句","c":["大堤绕芙渠，平铺三百步。","谁云水中花，不甃陆行路。"]},{"t":"张氏别业八首 其七 浣花桥","f":"五言绝句","c":["镜水及苧萝，相望不盈尺。","郎家浣花桥，妾家浣纱石。"]},{"t":"张氏别业八首 其八 水墨轩","f":"五言绝句","c":["万顷茫茫处，开轩榻绛州。","水光自湿研，不用汲池流。"]},{"t":"桃叶渡 其一","f":"五言绝句","c":["书中见桃叶，相忆如不死。","今过桃叶渡，但见一条水。"]},{"t":"桃叶渡 其二","f":"五言绝句","c":["忆渡桃叶时，绿杨娇粉面。","丈水五石泥，好影照不见。"]},{"t":"村家饮","f":"古风","c":["新竹巳成蛇尾，秋云乍起龙鳞。","不雨空啼布谷，乘风且脱纱巾。"]},{"t":"渔家图","f":"古风","c":["小练乳儿红袜，斜阳曝网黄芦。","但得同心夜浦，不愿嫁与秋胡。"]},{"t":"列子御风图","f":"古风","c":["旬馀身在遥空，一叶枝辞芳树。","若教风歇青蘋，试问人归何处。"]},{"t":"赠吕山人","f":"七言绝句","c":["西陵渡头秋水寒，年年岁岁走儒冠。","不知天姥山中客，十载关门傲长官。"]},{"t":"龛山凯歌 其一","f":"七言绝句","c":["县尉卑官禄米微，教辞黄绶著戎衣。","贼中何事先寒胆，海上连年数破围。"]},{"t":"龛山凯歌 其二","f":"七言绝句","c":["短剑随鎗暮合围，寒风吹血著人飞。","朝来边土看归骑，一片红冰冷铁衣。"]},{"t":"嘉靖辛丑之夏妇翁潘公即阳江官舍将令予合婚其乡刘寺丞公代为之媒先以三绝见遗后六年而细子弃帷又三年闻刘公亦谢世癸丑冬徙书室检旧札见之不胜悽惋因赋五首 其一","f":"七言绝句","c":["十年前与一相逢，光景犹疑在梦中。","记得当时官舍里，熏风巳过荔枝红。"]},{"t":"嘉靖辛丑之夏妇翁潘公即阳江官舍将令予合婚其乡刘寺丞公代为之媒先以三绝见遗后六年而细子弃帷又三年闻刘公亦谢世癸丑冬徙书室检旧札见之不胜悽惋因赋五首 其二","f":"七言绝句","c":["华堂日晏绮罗开，伐鼓吹箫一两回。","帐底画眉犹未了，寺丞亲著绛纱来。"]},{"t":"嘉靖辛丑之夏妇翁潘公即阳江官舍将令予合婚其乡刘寺丞公代为之媒先以三绝见遗后六年而细子弃帷又三年闻刘公亦谢世癸丑冬徙书室检旧札见之不胜悽惋因赋五首 其三","f":"七言绝句","c":["筵前半醉起逡巡，窄袖长袍妥著身。","若使吹箫人尚在，今宵应解说伊人。"]},{"t":"嘉靖辛丑之夏妇翁潘公即阳江官舍将令予合婚其乡刘寺丞公代为之媒先以三绝见遗后六年而细子弃帷又三年闻刘公亦谢世癸丑冬徙书室检旧札见之不胜悽惋因赋五首 其四","f":"七言绝句","c":["掩映双鬟绣扇新，当时相见各青春。","傍人细语亲听得，道是神仙会里人。"]},{"t":"嘉靖辛丑之夏妇翁潘公即阳江官舍将令予合婚其乡刘寺丞公代为之媒先以三绝见遗后六年而细子弃帷又三年闻刘公亦谢世癸丑冬徙书室检旧札见之不胜悽惋因赋五首 其五","f":"七言绝句","c":["箧里残花色尚明，分明世事隔前生。","坐来不觉西窗暗，飞尽寒梅雪未晴。"]},{"t":"将入闽方许二君饯别分韵","f":"七言绝句","c":["万丈高城控井闉，谁家池馆隔江津。","胜筵不用扶红袖，杨柳芙蓉拥醉人。"]},{"t":"凯歌赠参将戚公 其二","f":"七言绝句","c":["金印累累肘后垂，桃花宝玉称腰支。","丈夫意气本如此，自笑读书何所为。"]},{"t":"七里滩 其一","f":"七言绝句","c":["百番狮象一溪泅，一顷银光万个头。","水石何缘能有此，星辰尽夜殒寒流。"]},{"t":"七里滩 其二","f":"七言绝句","c":["浅水矾头蘸几堆，清涎齿缝破生梅。","竹舟欲过从何处，无数游鱼磕额回。"]},{"t":"武林馆中与徐仁卿同宿因赠 其二","f":"七言绝句","c":["自造提刀偃月文，诸工围煅焰吹云。","当时试舞犹嫌薄，铁把连环六十斤。"]},{"t":"赵君将买妾戏寄之","f":"七言绝句","c":["宫髻一鬟堆燕雏，胭脂两朵晕红酥。","三千仙子云中有，十五吴姬天下无。"]},{"t":"禅房夜话和韵书付玉公","f":"七言绝句","c":["一月真时月月真，何须种种别前尘。","禅房昨夜灯前话，谁是客人谁主人。"]},{"t":"折桃花","f":"七言绝句","c":["谁家桃树倚西邻，摘下还存树底新。","日暮插头过市上，疏疏数朵颇宜人。"]},{"t":"徐济之携新妇侍亲扬州","f":"七言绝句","c":["初绾同心结尚松，那堪波浪度江风。","华堂一入姑亲道，新妇扬州芍药红。"]},{"t":"送丁子范","f":"七言绝句","c":["君去高邮是壮游，风吹树叶绿娇秋。","归来佩剑不须脱，寻我武夷山上头。"]},{"t":"竹枝词 其一 袁宏道评曰：刘荪州无此奥","f":"七言绝句","c":["风前烛焰片时红。","马首西时马尾东。","两只鸳鸯睡不醒，一只相思愁杀侬。"]},{"t":"竹枝词 其二 袁宏道评曰：刘荪州无此奥","f":"七言绝句","c":["笼中鹞子不得出。","笼外要入将奈何。","一边虫粘蜘蛛网，一边窗打扑灯蛾。"]},{"t":"予自浙抵新安登齐云还浙道中旅馆颇多奇景而不成一字至衢自嘲一绝","f":"七言绝句","c":["系马梅花索酒时，溪山遥映酒家旗。","何为每到堪题处，不解吟成一字诗。"]},{"t":"索马乡丈紫竹罗汉即席书扇遗之","f":"七言绝句","c":["春来携酒醉春萝，乞得春花一两窠。","不若取将松竹去，成阴留待主人过。"]},{"t":"送陆子之闽","f":"七言绝句","c":["羡尔宁亲向百蛮，扁舟日下万重滩。","经过旧路吾能说，雪浪屏山画里看。"]},{"t":"留别倪子","f":"七言绝句","c":["小门一径柳垂丝，帘下垂裾话别离。","却问归来是何日，海榴如火烧高枝。"]},{"t":"天目山 其一","f":"七言绝句","c":["铁罗汉巳烧成尘，瓦铸观音又一新。","见说前村披木叶，青裙夜降紫姑神。"]},{"t":"天目山 其二","f":"七言绝句","c":["赭铁青铜凌紫烟，能为人语向人间。","二千年事说不尽，夜夜青溪劳往还。"]},{"t":"天目山 其三","f":"七言绝句","c":["断壁孤杉四十围，不关雨雪阴霏霏。","柯南一国痴蝼蚁，长怪曾无白日飞。"]},{"t":"南海曲","f":"七言绝句","c":["一尺高鬟十五人，爱侬云鬓怯侬胜。","近来海舶久不到，欲寄玳瑁簪未曾。"]}]};